INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C1','kor',4,2,'u6',2,'원인과 결과의 뜻 — 원인은 일이 일어난 까닭, 결과는 그래서 벌어진 일',ARRAY['[4국01-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C2','kor',4,2,'u6',2,'결과가 다시 원인이 됨 — 어떤 일의 결과는 다음 일의 원인이 되기도 해서 이야기가 한 줄로 길게 이어짐',ARRAY['[4국01-02]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C3','kor',4,2,'u6',2,'예상의 까닭은 드러난 것에서 — 다음 일을 예상한 까닭은 앞 장면에 이미 나와 있는 것에서 댐 — 「그냥 그럴 것 같아서」·「더 재미있어서」 ✗',ARRAY['[4국01-02]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C4','kor',4,2,'u6',2,'소식에 빠지면 안 되는 두 가지 — 일을 옮길 때 왜 일어났는지(원인)와 그래서 어떻게 되었는지(결과)가 빠지면 듣는 사람이 되묻게 됨',ARRAY['[4국01-02]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C5','kor',4,2,'u6',2,'상상할 때 가장 먼저 생각할 것 — 이어질 내용을 상상할 때는 앞에서 어떤 일이 왜 일어났는지부터 봄 — 가장 놀라운 일 · 가장 길게 쓰는 법 ✗',ARRAY['[4국01-02][4국05-01]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C6','kor',4,2,'u6',2,'이 단원에서 배울 두 가지 — 원인과 결과를 생각하며 보고 듣기 · 이어질 내용을 상상해 쓰기 — 둘 다 까닭을 따져 보는 일에서 시작',ARRAY['[4국01-02][4국05-01]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C7','kor',4,2,'u6',2,'영상은 따져 보는 것 — 영상은 넘기는 것이 아니라 무슨 일이 일어났는지 → 왜 일어났는지 → 그래서 어떻게 되었는지를 따져 보는 것',ARRAY['[4국01-02]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C8','kor',4,2,'u6',2,'일어난 일 먼저 붙잡기 — 장면에 그대로 나와 있는 것만 일어난 일로 고름 — 짐작을 덧붙이지 않음',ARRAY['[4국01-02]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C9','kor',4,2,'u6',2,'까닭이 달라지면 다음도 달라짐 — 있을 법한 까닭은 여럿일 수 있고, 어떤 까닭으로 보느냐에 따라 그래서 할 일이 달라짐',ARRAY['[4국01-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C10','kor',4,2,'u6',2,'예상과 견주어 말하기 — 「무엇을 까닭으로 이렇게 예상했는데 그 부분이 같았다/달랐다」처럼 말함 — 「같아서 좋았다·달라서 아쉬웠다」 같은 느낌만 ✗',ARRAY['[4국01-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C11','kor',4,2,'u6',2,'중심 사건의 앞과 뒤 — 가운데 사건을 붙잡고 앞(그 일의 원인)과 뒤(그 일의 결과)로 뻗어 나감 — 있을 만한 곳이 아닌 데에 있으면 까닭이 궁금해짐',ARRAY['[4국01-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C12','kor',4,2,'u6',2,'예상은 달라도 까닭은 장면 안에서 — 친구와 다른 예상을 해도 되지만 그렇게 생각한 까닭을 장면 안에서 찾을 수 있어야 함 — 까닭을 댈 수 없으면 아무 말',ARRAY['[4국01-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C13','kor',4,2,'u6',2,'보면서 메모하기 — 가장 큰 사건 · 그 일이 왜 생겼는지 · 그래서 어떻게 되었는지 — 글자를 다 쓰지 않고 화살표와 그림으로 적어도 됨',ARRAY['[4국01-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C14','kor',4,2,'u6',4,'결과이면서 원인인 일 — 사슬 가운데의 일은 앞 일의 결과이면서 동시에 뒤 일의 원인 — 하나의 일이 두 몫을 함께 맡음',ARRAY['[4국01-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C17','kor',4,2,'u6',4,'일이 일어난 차례대로 정리 — 일을 차례대로 놓고 보면 어디가 까닭이었는지가 드러남',ARRAY['[4국01-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C18','kor',4,2,'u6',4,'짝은 여러 겹 — 한 이야기 안에 원인과 결과의 짝이 여러 개 들어 있음 — 짝을 여러 개 찾을수록 이야기가 더 잘 보임',ARRAY['[4국01-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C19','kor',4,2,'u6',4,'원인이 하나뿐인 것은 아님 — 줄이 끊어진 데에는 거친 돌도 있었고, 까닭을 찾지 않고 줄만 바꾼 일도 있었음',ARRAY['[4국01-02]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C20','kor',4,2,'u6',4,'이야기에 나온 일끼리만 잇기 — 원인과 결과의 짝은 이야기에 실제로 나온 일끼리만 이음 — 그럴듯해도 나오지 않은 일을 끌어오지 않음',ARRAY['[4국01-02]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C21','kor',4,2,'u6',4,'말과 행동에 드러난 성격 — 한 말이 없어도 행동에서 성격이 보임 — 범수는 까닭을 찾을 때까지 꼼꼼히 살펴보는 아이',ARRAY['[4국01-02]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C22','kor',4,2,'u6',4,'들으며 짧게 메모하기 — 나오는 사람 · 일어난 일 · 그 일의 까닭과 그다음을 짧게 — 화살표만 그어 두어도 나중에 되살아남',ARRAY['[4국01-02]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C23','kor',4,2,'u6',4,'다른 이야기에도 세 물음 — 읽을 때마다 무슨 일이 일어났나 · 왜 일어났나 · 그래서 어떻게 되었나를 물음',ARRAY['[4국01-02]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C24','kor',4,2,'u6',4,'스스로 확인하기 표 — 「아니요」가 나온 줄로 돌아가 다시 읽는 표 — 점수가 없음(「예」로 고치기 · 넘기기 ✗)',ARRAY['[4국01-02]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C26','kor',4,2,'u6',6,'방법 ① 인물의 성격 — 인물의 성격을 알면 앞으로 할 행동이 그려짐 — 성격은 따로 적혀 있지 않고 말과 행동 속에 있음',ARRAY['[4국05-01]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C27','kor',4,2,'u6',6,'방법 ② 이야기의 흐름 — 처음 · 가운데 · 지금을 차례대로 늘어놓으면 다음 칸이 보이기 시작함',ARRAY['[4국05-01]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C28','kor',4,2,'u6',6,'흐름에 맞는 다음 일 — 앞에서 이어져 온 이야기가 지금 묻고 있는 일(저 연을 어떻게 할까)로 이어짐 — 흐름과 상관없는 일 ✗',ARRAY['[4국05-01]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C29','kor',4,2,'u6',6,'방법 ③ 원인과 결과 — 상상한 일도 까닭이 있어야 이야기가 됨 — 「그래서」·「왜냐하면」을 넣어 말이 되면 이어진 것',ARRAY['[4국05-01]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C30','kor',4,2,'u6',6,'정답은 없지만 아무거나도 아님 — 이어질 내용에는 정답이 없어 친구와 아주 달라도 되지만, 앞에서 일어난 일이 까닭이 되어 그 일이 생겨야 함',ARRAY['[4국05-01]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C31','kor',4,2,'u6',6,'알맞지 않은 상상의 까닭 — 평범한지 · 글자 수가 적은지가 아니라 앞에 나온 성격·행동과 이어지지 않는지를 봄',ARRAY['[4국05-01]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C32','kor',4,2,'u6',6,'두 상상 견주기 — 더 놀라운 쪽이 아니라 성격도 흐름도 까닭도 앞과 더 이어지는 쪽을 고름',ARRAY['[4국05-01]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C33','kor',4,2,'u6',8,'끊긴 대목에서 시작 — 앞 이야기 칸으로 여기까지 있었던 일을 먼저 붙잡고, 인물의 성격 · 이야기의 흐름 · 원인과 결과 셋을 한꺼번에 씀',ARRAY['[4국05-01]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C36','kor',4,2,'u6',8,'누구를 따라가느냐 — 같은 일을 보고도 두 인물이 다르게 움직여서, 누구를 따라가느냐에 따라 이어질 내용이 달라짐',ARRAY['[4국05-01]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C37','kor',4,2,'u6',8,'성격을 이용한 상상 — 궁금하면 확인해야 잠이 오는 동규이라면 매듭을 맬 줄 아는 사람을 찾아 나섬 — 앞의 행동과 같은 결',ARRAY['[4국05-01]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C39','kor',4,2,'u6',8,'가장 자연스러운 상상 고르기 — 인물이 앞의 모습 그대로 움직이는가 · 흐름에서 이어지는가 · 까닭이 앞에 있는가 — 「가장 놀라운 것」은 기준이 아님',ARRAY['[4국05-01]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C40','kor',4,2,'u6',8,'성격을 바꾸려면 까닭도 — 앞과 다른 성격으로 움직이게 하려면 왜 바뀌었는지를 함께 써야 함 — 바꾸었다고 선언만 하고 까닭을 안 쓰면 끊김',ARRAY['[4국05-01]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C41','kor',4,2,'u6',8,'뒷이야기를 쓸 때 스스로 묻기 — 「이 사람이 이렇게 할 까닭이 앞에 있나?」 — 있으면 쓰고, 없으면 까닭을 먼저 만들어 넣음',ARRAY['[4국05-01]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C42','kor',4,2,'u6',11,'이야기 이어 말하기 — 앞 문장이 까닭이 되는 문장을 이음 — 길게 말하는 사람이 이기는 놀이가 아니라 끊기지 않게 잇는 놀이',ARRAY['[4국01-02][4국05-01]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C43','kor',4,2,'u6',11,'이야기가 끊기는 때 — 앞과 아무 상관 없는 일을 새로 꺼낼 때 · 까닭 없이 갑자기 큰일이 벌어질 때 · 이미 끝난 일을 없던 일로 돌릴 때',ARRAY['[4국01-02][4국05-01]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C44','kor',4,2,'u6',11,'성격에 맞는 대사 — 역할놀이의 다음 대사는 그 인물의 성격에서 나옴 — 일이 생기면 먼저 방법을 찾는 효주라면 따지기보다 방법을 내놓음',ARRAY['[4국01-02][4국05-01]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C45','kor',4,2,'u6',11,'역할놀이 준비 — 인물마다 성격을 한 줄로 정하기 · 뒤에 벌어질 일에 까닭 붙이기 · 대사와 함께 몸짓 정하기',ARRAY['[4국01-02][4국05-01]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C46','kor',4,2,'u6',11,'역할놀이에서 가장 먼저 볼 것 — 인물의 성격과 앞 이야기에 자연스럽게 이어지는가 — 가장 웃긴가 · 대사가 가장 긴가 ✗',ARRAY['[4국01-02][4국05-01]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C47','kor',4,2,'u6',11,'(으)로서 — 자격이나 신분을 나타냄 — 누구인가, 어떤 몫을 맡고 있는가',ARRAY['[4국04-04](차시 머리 표기 — (으)로서·(으)로써)']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C48','kor',4,2,'u6',11,'(으)로써 — 재료나 수단 · 도구를 나타냄 — 무엇을 가지고, 무엇을 써서',ARRAY['[4국04-04](차시 머리 표기 — (으)로서·(으)로써)']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C53','kor',4,2,'u6',11,'이어지면서도 새로울 수 있음 — 「아주 달라야 재미있다」도 「정해진 답이 하나 있다」도 아님 — 까닭을 달고 가면 새로우면서도 이어질 수 있어 둘은 맞바꾸는 것이 아님',ARRAY['[4국05-01]']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C54','kor',4,2,'u6',11,'원인과 결과는 생활 속에도 — 늦은 아침·시든 화분에도 원인이 있음 — 까닭을 찾으면 그다음을 바꿀 수 있음(줄만 바꾼 마을 사람들과 돌을 살핀 범수)',ARRAY['[4국01-02]']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C55','kor',4,2,'u6',2,'「소연이네 반에서 일어난 일」 내용 알기 — 옥상 텃밭에서 기른 방울토마토가 감쪽같이 사라짐 → 까닭 예상(새가 쪼아 먹음 / 누군가 가져감) → 뒷부분: 새가 가져가서 허수아비를 설치함',ARRAY['[4국01-02]']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C56','kor',4,2,'u6',2,'얼룩말 뉴스 영상 — 중심 사건(얼룩말이 주택가에 나타남)의 앞(동물원 탈출)과 뒤(경찰과 소방관이 동물원으로 돌려보냄)를 예상하고 영상과 비교함',ARRAY['[4국01-02]']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C57','kor',4,2,'u6',4,'「방 씨 규수의 이야기」 내용 알기 — 하인이 화살을 훔쳐 감 → 도둑들이 쳐들어옴 → 화살이 떨어짐 → 방 씨 규수가 대나무를 화살인 척 내던짐 → 도둑들이 달아남(지혜롭고 침착함)',ARRAY['[4국01-02]']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C58','kor',4,2,'u6',6,'「당나귀 실베스터와 요술 조약돌」 내용 알기 — 요술 조약돌을 손에 쥐고 빈 소원이 이루어짐 → 사자를 만나 놀라고 당황해 바위가 됨 → 손이 없어 조약돌을 집지 못함',ARRAY['[4국02-03][4국05-01]']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C59','kor',4,2,'u6',8,'「랑랑별 때때롱」 내용 알기 — 때때롱이 새달이네 씨호박을 따 가 호박죽을 끓여 먹고 돌담 위에 랑랑별 호박씨 다섯 개를 두고 감 · 새달이(궁금한 것을 참지 못함)·때때롱(장난치는 것을 좋아함)',ARRAY['[4국02-03][4국05-01]']::text[],59) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C60','kor',4,2,'u6',8,'「랑랑별 때때롱」 낱말 알기 — 탐이 나다(가지거나 차지하고 싶은 마음이 생기다) · 혀를 차다(마음이 언짢거나 불만스러움을 나타내다) · 어이가 없다(일이 너무 뜻밖이어서 기가 막히는 듯하다) · 씨호박 · 갈무리하다',ARRAY['[4국05-01]']::text[],60) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C61','kor',4,2,'u6',11,'뜻을 보고 본문에서 낱말 찾기 — 서운하다(마음에 모자라 아쉽거나 섭섭한 느낌이 있다) · 놀라다(뜻밖의 일이나 무서움에 가슴이 두근거리다) · 찜찜하다(마음에 꺼림칙한 느낌이 있다)',ARRAY['[4국05-01]']::text[],61) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u6-C62','kor',4,2,'u6',11,'겹받침 낱말 바르게 쓰기 — 겉핥기 · 훑다 · 읊조리다 · 닳다 · 싫증 · 옳다 · 끓다를 겹받침 그대로 바르게 씀(기초 다지기 글씨 쓰기)',ARRAY['기초 다지기 글씨 쓰기(성취기준 표기 없음)']::text[],62) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X01','kor',4,'u6',ARRAY['K4-2-u6-C1']::text[],'원인과 결과를 뒤바꾸어, 그래서 벌어진 일을 원인으로 여긴다','까닭이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X02','kor',4,'u6',ARRAY['K4-2-u6-C2','K4-2-u6-C14']::text[],'하나의 일은 원인이거나 결과 가운데 하나만 된다고 여긴다','두 몫을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X03','kor',4,'u6',ARRAY['K4-2-u6-C3']::text[],'예상한 까닭을 앞 장면에서 찾지 않고 「그냥 그럴 것 같아서」·「더 재미있어서」로 댄다','이미 나와 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X04','kor',4,'u6',ARRAY['K4-2-u6-C4']::text[],'일을 옮길 때 빠진 것을 때와 곳·꾸미는 표현에서 찾고, 원인과 결과가 빠진 것은 보지 못한다','왜? 그래서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X05','kor',4,'u6',ARRAY['K4-2-u6-C5','K4-2-u6-C39']::text[],'이어질 내용을 상상할 때 「가장 놀라운 일이 무엇일까」를 가장 먼저 생각한다','앞 이야기에서 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X06','kor',4,'u6',ARRAY['K4-2-u6-C5']::text[],'이어질 내용을 상상할 때 「어떻게 하면 가장 길게 쓸까」를 가장 먼저 생각한다','길이가 아니라 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X07','kor',4,'u6',ARRAY['K4-2-u6-C6','K4-2-u6-C7','K4-2-u6-C23']::text[],'영상이나 이야기를 넘기며 무슨 일이 일어났는지만 보고 왜·그래서는 따지지 않는다','넘기지 말고 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X08','kor',4,'u6',ARRAY['K4-2-u6-C8','K4-2-u6-C34']::text[],'장면이나 이야기에 나오지 않은 일을 짐작으로 덧붙여 일어난 일로 고른다','나와 있는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X09','kor',4,'u6',ARRAY['K4-2-u6-C9','K4-2-u6-C38']::text[],'까닭이 달라져도 그다음 일은 같다고 여기거나, 원인과 그다음 일을 엇갈리게 잇는다','까닭에 맞는 다음 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X10','kor',4,'u6',ARRAY['K4-2-u6-C9','K4-2-u6-C12']::text[],'있을 법한 까닭이 여럿인데도 정답인 까닭이 하나만 있다고 여긴다','까닭은 여럿일 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X11','kor',4,'u6',ARRAY['K4-2-u6-C10']::text[],'예상과 견줄 때 「같아서 좋았다·달라서 아쉬웠다」처럼 느낌만 말한다','무엇을 까닭으로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X12','kor',4,'u6',ARRAY['K4-2-u6-C11']::text[],'장면을 보고 놀란 까닭을 장소가 아닌 엉뚱한 데(무서워서·조용해서)에서 찾는다','있을 만한 곳인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X13','kor',4,'u6',ARRAY['K4-2-u6-C12','K4-2-u6-C30']::text[],'장면에서 근거를 댈 수 없는 예상(마법·책을 읽고 싶어서)도 알맞은 예상이라 여긴다','까닭은 장면 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X14','kor',4,'u6',ARRAY['K4-2-u6-C13','K4-2-u6-C22']::text[],'메모는 보거나 들은 것을 한 글자도 빼지 않고 모두 받아 적는 것이라 여긴다','짧게 · 화살표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X15','kor',4,'u6',ARRAY['K4-2-u6-C18','K4-2-u6-C19']::text[],'원인과 결과의 짝을 하나만 찾고 끝내거나, 한 일의 원인은 하나뿐이라고 여긴다','짝은 여러 겹') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X16','kor',4,'u6',ARRAY['K4-2-u6-C15','K4-2-u6-C19']::text[],'일이 일어난 까닭을 겉으로 보이는 것(줄이 나빠서·솜씨가 나빠서)에서만 찾는다','같은 곳에 난 자국') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X17','kor',4,'u6',ARRAY['K4-2-u6-C16']::text[],'까닭을 없애려고 한 행동을 꾸미기처럼 엉뚱한 목적으로 여긴다','무엇을 없애려고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X18','kor',4,'u6',ARRAY['K4-2-u6-C20']::text[],'이야기에 나오지 않은 일을 끌어와 원인과 결과의 짝으로 잇는다','나온 일끼리만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X19','kor',4,'u6',ARRAY['K4-2-u6-C17']::text[],'일이 일어난 차례를 뒤섞어 놓는다','무엇이 먼저였나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X20','kor',4,'u6',ARRAY['K4-2-u6-C21','K4-2-u6-C26']::text[],'성격을 말과 행동이 아닌 데서 짐작하거나, 한 말이 없으면 성격을 알 수 없다고 여긴다','행동에도 성격이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X21','kor',4,'u6',ARRAY['K4-2-u6-C24']::text[],'스스로 확인하기 표에서 「아니요」를 「예」로 고치거나 넘기거나 점수를 매긴다','그 줄로 돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X22','kor',4,'u6',ARRAY['K4-2-u6-C25']::text[],'앞 이야기에서 일이 생긴 까닭을 바로 앞에 나온 일이 아닌 데서 찾는다','바로 앞에 무슨 일이?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X23','kor',4,'u6',ARRAY['K4-2-u6-C26','K4-2-u6-C36']::text[],'인물의 말·행동과 성격을 엇갈리게 잇거나, 성격과 반대되는 행동을 그 인물다운 행동으로 고른다','이 사람이라면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X24','kor',4,'u6',ARRAY['K4-2-u6-C27','K4-2-u6-C28','K4-2-u6-C33']::text[],'지금까지의 흐름과 상관없는 일을 다음 일로 고르거나, 앞 이야기를 건너뛴다','지금 무엇을 묻나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X25','kor',4,'u6',ARRAY['K4-2-u6-C30','K4-2-u6-C53']::text[],'이어질 내용에는 정답이 없으니 까닭 없이 아무거나 상상해도 된다고 여긴다','아무거나도 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X26','kor',4,'u6',ARRAY['K4-2-u6-C30','K4-2-u6-C53']::text[],'이어질 내용에도 정해진 답이 하나 있어서 친구와 다르면 틀린 것이라 여긴다','정답은 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X27','kor',4,'u6',ARRAY['K4-2-u6-C31']::text[],'상상이 알맞지 않은 까닭을 「너무 평범해서」에서 찾는다','평범함은 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X28','kor',4,'u6',ARRAY['K4-2-u6-C31']::text[],'상상이 알맞은지를 글자 수나 문장 길이로 따진다','길이는 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X29','kor',4,'u6',ARRAY['K4-2-u6-C32','K4-2-u6-C39']::text[],'더 놀랍고 신기한 상상이 더 알맞은 상상이라고 여긴다','더 이어지는 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X31','kor',4,'u6',ARRAY['K4-2-u6-C36']::text[],'같은 일을 보면 누구나 똑같이 움직여서 누구를 따라가도 이어질 내용이 같다고 여긴다','사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X32','kor',4,'u6',ARRAY['K4-2-u6-C40','K4-2-u6-C37']::text[],'인물의 성격을 바꾸어 놓고 왜 바뀌었는지는 쓰지 않은 상상을 알맞다고 여긴다','바뀐 까닭은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X34','kor',4,'u6',ARRAY['K4-2-u6-C42']::text[],'이야기 이어 말하기를 길게 말하는 사람이 이기는 놀이로 여긴다','끊기지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X35','kor',4,'u6',ARRAY['K4-2-u6-C43']::text[],'앞과 아무 상관 없는 일을 새로 꺼내도 이어진 것이라 여긴다','앞 문장이 까닭?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X36','kor',4,'u6',ARRAY['K4-2-u6-C43']::text[],'까닭 없이 갑자기 큰일이 벌어지는 문장도 이어진 것이라 여긴다','갑자기는 까닭이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X37','kor',4,'u6',ARRAY['K4-2-u6-C43']::text[],'앞에서 이미 일어난 일을 없던 일로 돌리는 문장도 이어진 것이라 여긴다','끝난 일은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X38','kor',4,'u6',ARRAY['K4-2-u6-C44']::text[],'역할놀이의 다음 대사를 인물의 성격과 상관없이 짓는다','그 인물이라면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X39','kor',4,'u6',ARRAY['K4-2-u6-C46']::text[],'역할놀이에서 가장 웃긴 모둠을 가장 먼저 살펴볼 것으로 여긴다','웃음보다 이어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X40','kor',4,'u6',ARRAY['K4-2-u6-C46','K4-2-u6-C45']::text[],'역할놀이에서 대사가 가장 긴 것을 가장 잘한 것으로 여긴다','길이는 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X41','kor',4,'u6',ARRAY['K4-2-u6-C47','K4-2-u6-C48']::text[],'재료·수단·도구를 나타낼 자리에 (으)로서를 쓴다','무엇을 써서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X42','kor',4,'u6',ARRAY['K4-2-u6-C47','K4-2-u6-C48']::text[],'자격·신분을 나타낼 자리에 (으)로써를 쓴다','누구인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X46','kor',4,'u6',ARRAY['K4-2-u6-C52']::text[],'겹받침 낱말을 소리 나는 대로 적는다(안따 · 만타 · 괜찬타)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X48','kor',4,'u6',ARRAY['K4-2-u6-C54']::text[],'원인과 결과는 이야기 속에만 있다고 여기거나, 까닭을 찾지 않고 겉만 바꾸면 된다고 여긴다','생활 속에도 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X49','kor',4,'u6',ARRAY['K4-2-u6-C53']::text[],'이어지려면 뻔한 일만 써야 하고, 새로우려면 앞과 달라져야 한다고 둘을 맞바꾸는 것으로 여긴다','함께 갈 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X50','kor',4,'u6',ARRAY['K4-2-u6-C45']::text[],'역할놀이는 대사만 외우면 된다고 여겨 성격·까닭·몸짓을 정하지 않는다','성격 · 까닭 · 몸짓') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X51','kor',4,'u6',ARRAY['K4-2-u6-C29','K4-2-u6-C42']::text[],'「그래서」를 넣어 읽어 어색한데도 이어진 것이라 여긴다','넣어서 말이 되나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X52','kor',4,'u6',ARRAY['K4-2-u6-C30','K4-2-u6-C39','K4-2-u6-C41']::text[],'이어질 이야기는 상상이니까 너무 장난스럽거나 황당하게(까닭 없이 엉뚱한 큰일) 지어내도 괜찮다고 여긴다','재미있어도 앞 이야기·인물과 어울리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X53','kor',4,'u6',ARRAY['K4-2-u6-C60','K4-2-u6-C61']::text[],'이야기 속 표현(탐이 나다·혀를 차다·어이가 없다·서운하다·찜찜하다 등)의 뜻을 엇갈리게 안다','그 표현이 쓰인 문장에 뜻을 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X54','kor',4,'u6',ARRAY['K4-2-u6-C10','K4-2-u6-C56']::text[],'자신의 예상과 영상을 비교할 때 예상이 맞았는지·같은지만 따지고, 예상한 원인과 결과가 인과 관계를 충분히 고려했는지는 살피지 않는다','무엇을 까닭으로 그렇게 예상했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u6-X55','kor',4,'u6',ARRAY['K4-2-u6-C9','K4-2-u6-C12']::text[],'예상한 원인이 실제 영상 내용과 다르면, 앞부분 내용으로 미루어 그럴 만한(개연성 있는) 예상이어도 틀린 예상이라 여긴다','앞부분으로 보아 그럴 만한 까닭인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#1','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C1',1,'mc','auto','수영이는 뉴스를 보고 친구들에게 이야기했어요. 수영이의 설명에서 잘못된 점은 무엇인가요?',ARRAY['K4-2-u6-X04','K4-2-u6-X01']::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"수영이는 뉴스를 보고 친구들에게 이야기했어요. 수영이의 설명에서 잘못된 점은 무엇인가요?","options":[{"t":"바다가 빛나는 까닭을 「관광객이 많아서」라고 원인과 결과를 거꾸로 말했다","correct":true},{"t":"바다의 이름을 빠뜨리고 말했다","mis":"K4-2-u6-X04"},{"t":"「신기한」 같은 꾸미는 말을 쓰지 않았다","mis":"K4-2-u6-X04"},{"t":"관광객이 많아진 것을 바다가 빛나는 까닭으로 바르게 말했다","mis":"K4-2-u6-X01"}],"explanation":["뉴스에서는 빛을 내는 생물이 바닷속에 있어서 바다가 빛난다고 했어요.","관광객이 많아진 것은 그 신기한 모습을 보러 온 결과예요.","수영이는 결과를 원인처럼 말해서 친구들이 「관광객?」 하고 되물었어요."],"asset":{"type":"speech","turns":[{"who":"뉴스","text":"밤이면 푸른 형광색으로 변하는 바다가 있다고 합니다. 그 까닭은 자극을 받으면 빛을 내는 생물이 바닷속에 있기 때문입니다."},{"who":"뉴스","text":"이 신기한 모습을 보기 위해 관광객이 많아지고 있다고 합니다."},{"who":"수영","text":"너희 그거 알아? 밤이면 푸른 형광색으로 변하는 바다가 있대."},{"who":"친구","text":"왜 그런 일이 생긴 거야?"},{"who":"수영","text":"관광객이 많아서 그랬다고 한 것 같은데?"},{"who":"친구","text":"관광객?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#2','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C55',1,'mc','auto','「소연이네 반에서 일어난 일」에서 소연이네 반 친구들이 놀란 까닭은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X19']::text[],false,'{"seq":2,"concept":"K4-2-u6-C55","difficulty":1,"kind":"mc","stem":"「소연이네 반에서 일어난 일」에서 소연이네 반 친구들이 놀란 까닭은 무엇인가요?","options":[{"t":"수확을 기대했던 잘 익은 방울토마토가 감쪽같이 사라졌기 때문","correct":true},{"t":"방울토마토가 하나도 열리지 않았기 때문","mis":"K4-2-u6-X08"},{"t":"옥상 텃밭에 허수아비가 서 있었기 때문","mis":"K4-2-u6-X19"},{"t":"새가 방울토마토를 쪼아 먹는 것을 보았기 때문","mis":"K4-2-u6-X08"}],"explanation":["친구들은 봄부터 옥상 텃밭에서 방울토마토를 길렀어요.","수확을 기대했는데 잘 익은 방울토마토가 감쪽같이 사라졌어요.","영상 앞부분에 나온 일만 일어난 일로 골라요."],"asset":{"type":"passage","lines":["(간추림) 소연이네 반 친구들은 올해 봄부터 옥상 텃밭에서 방울토마토를 길렀다.","(간추림) 친구들은 방울토마토를 수확할 날을 기대하고 있었다.","(간추림) 그런데 잘 익은 방울토마토가 감쪽같이 사라졌다."],"title":"「소연이네 반에서 일어난 일」 앞부분 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#3','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C55',1,'sa','auto','「소연이네 반에서 일어난 일」에서 소연이네 반 친구들이 올해 봄부터 옥상 텃밭에서 기른 것은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u6-C55","difficulty":1,"kind":"sa","stem":"「소연이네 반에서 일어난 일」에서 소연이네 반 친구들이 올해 봄부터 옥상 텃밭에서 기른 것은 무엇인지 쓰세요.","answer":["방울토마토","토마토"],"explanation":["영상은 옥상 텃밭에서 일어난 일이에요.","친구들은 봄부터 방울토마토를 길렀어요.","무엇에 대한 영상인지 먼저 붙잡아요."],"asset":{"type":"passage","lines":["(간추림) 소연이네 반 친구들은 올해 봄부터 옥상 텃밭에서 방울토마토를 길렀다.","(간추림) 친구들은 방울토마토를 수확할 날을 기대하고 있었다.","(간추림) 그런데 잘 익은 방울토마토가 감쪽같이 사라졌다."],"title":"「소연이네 반에서 일어난 일」 앞부분 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#4','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C3',1,'ox','auto','생각 열기에서 「개구리가 파리를 잡아먹을 것 같다」고 예상한 까닭은 그림 속에서 찾을 수 있어요.',ARRAY['K4-2-u6-X03']::text[],false,'{"seq":4,"concept":"K4-2-u6-C3","difficulty":1,"kind":"ox","stem":"생각 열기에서 「개구리가 파리를 잡아먹을 것 같다」고 예상한 까닭은 그림 속에서 찾을 수 있어요.","answer":"O","reason_options":[{"t":"시무룩하던 개구리가 파리를 보자 생기 있는 표정으로 바뀌고 입맛을 다시고 있기 때문에","correct":true},{"t":"개구리는 원래 무엇이든 잘 먹는다고 들은 적이 있기 때문에","mis":"K4-2-u6-X03"}],"mis":"K4-2-u6-X03","explanation":["개구리는 배가 고파 시무룩한 표정을 짓고 있었어요.","파리가 나타나자 생기 있는 표정으로 바뀌고 입맛을 다셨어요.","예상의 까닭은 그림에 이미 나와 있는 것에서 찾아요."],"asset":{"type":"passage","lines":["[그림] 배고픈 개구리가 시무룩한 표정을 짓고 있다.","[그림] 개구리 눈앞에 파리가 나타나자 생기 있는 표정으로 바뀌었다.","[그림] 개구리가 파리를 바라보며 입맛을 다시고 있다."],"numbered":false,"title":"생각 열기 「앞으로 어떤 일이 일어날까요?」 — 『국어』 253쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#5','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C9',2,'mc','auto','방울토마토가 없어진 까닭을 ㉮처럼 예상한 친구가 이어서 예상할 뒷일로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X09','K4-2-u6-X13','K4-2-u6-X07']::text[],false,'{"seq":5,"concept":"K4-2-u6-C9","difficulty":2,"kind":"mc","stem":"방울토마토가 없어진 까닭을 ㉮처럼 예상한 친구가 이어서 예상할 뒷일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"허수아비를 세워 새를 쫓을 것이다","correct":true},{"t":"경고 팻말을 세워 사람이 가져가지 못하게 할 것이다","mis":"K4-2-u6-X09"},{"t":"방울토마토가 저절로 다시 열릴 것이다","mis":"K4-2-u6-X13"},{"t":"옥상 텃밭을 그냥 그대로 둘 것이다","mis":"K4-2-u6-X07"}],"explanation":["㉮는 새가 방울토마토를 쪼아 먹었다고 본 예상이에요.","원인을 새로 보았으니 새를 쫓는 방법이 이어져요.","예상한 원인에 따라 이후 결과 부분도 달라져야 해요."],"asset":{"type":"passage","lines":["㉮ 새가 방울토마토를 쪼아 먹었을 것이다.","㉯ 방울토마토를 누군가 가져갔을 것이다."],"numbered":false,"title":"방울토마토가 없어진 까닭 예상 — 『국어』 257쪽 2번 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#6','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C4',2,'match','auto','기억에 남는 학교 소식을 떠올리며 묻는 말이에요. 각 물음이 알아보려는 것을 바르게 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u6-C4","difficulty":2,"kind":"match","stem":"기억에 남는 학교 소식을 떠올리며 묻는 말이에요. 각 물음이 알아보려는 것을 바르게 이어 보세요.","pairs":[{"l":"내용은 무엇이었나요?","r":"일어난 일"},{"l":"그 사건은 왜 일어났나요?","r":"원인"},{"l":"그 결과 어떻게 되었나요?","r":"결과"}],"mis":"K4-2-u6-X04","explanation":["소식을 전할 때는 무슨 일이 일어났는지부터 말해요.","왜 일어났는지가 원인이에요.","그래서 어떻게 되었는지가 결과예요."],"asset":{"type":"passage","lines":["● 기억에 남는 학교 소식이 있나요?","● 내용은 무엇이었나요?","● 그 사건은 왜 일어났나요?","● 그 결과 어떻게 되었나요?"],"numbered":false,"title":"기억에 남는 우리 학교 소식 떠올리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#7','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C2',2,'mc','auto','수영이가 본 영상의 내용을 원인과 결과로 정리했어요. 가운데 줄 「밤이면 바다가 푸른 형광색으로 빛난다.」는 어떤 일인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X08']::text[],false,'{"seq":7,"concept":"K4-2-u6-C2","difficulty":2,"kind":"mc","stem":"수영이가 본 영상의 내용을 원인과 결과로 정리했어요. 가운데 줄 「밤이면 바다가 푸른 형광색으로 빛난다.」는 어떤 일인가요?","options":[{"t":"앞 일의 결과이면서 뒤 일의 원인인 일","correct":true},{"t":"원인만 되는 일","mis":"K4-2-u6-X02"},{"t":"결과만 되는 일","mis":"K4-2-u6-X02"},{"t":"원인도 결과도 아닌 일","mis":"K4-2-u6-X08"}],"explanation":["빛을 내는 생물이 바닷속에 살아서 바다가 빛나요(결과).","그 신기한 모습에 반해 관광객이 찾아와요(원인).","어떤 일의 결과는 다음 일의 원인이 되기도 해요."],"asset":{"type":"passage","lines":["원인 자극을 받으면 빛을 내는 생물들이 바닷속에 살고 있다.","→ 밤이면 바다가 푸른 형광색으로 빛난다.","결과 신기한 모습에 반해 많은 관광객이 찾게 되었다."],"numbered":false,"title":"수영이가 본 영상 속 사건의 원인과 결과 — 『국어』 254쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#8','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C11',2,'mc','auto','그림 속 아저씨가 놀란 표정을 지은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X12','K4-2-u6-X08']::text[],false,'{"seq":8,"concept":"K4-2-u6-C11","difficulty":2,"kind":"mc","stem":"그림 속 아저씨가 놀란 표정을 지은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"동물원에나 있을 법한 얼룩말이 사람들이 사는 주택가에 갑자기 나타났기 때문","correct":true},{"t":"얼룩말의 줄무늬가 무서워 보였기 때문","mis":"K4-2-u6-X12"},{"t":"주택가가 너무 조용했기 때문","mis":"K4-2-u6-X12"},{"t":"아저씨가 얼룩말을 처음 기르게 되었기 때문","mis":"K4-2-u6-X08"}],"explanation":["얼룩말이 나타난 곳은 사람들이 사는 주택가 한복판이에요.","얼룩말이 주택가에 있는 것은 일반적인 상황이 아니에요.","그래서 당황스럽고 겁이 났을 거예요."],"asset":{"type":"passage","lines":["[그림] 사람들이 사는 주택가 한복판에 얼룩말이 나타났다.","[그림] 그 모습을 본 아저씨가 놀란 표정을 짓고 있다."],"numbered":false,"title":"영상의 한 장면 — 『국어』 258쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#9','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C10',2,'blank','auto','영상의 뒷부분을 보고 자신의 예상과 비교해 쓴 글이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_basic#10','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_basic','lesson_basic','K4-2-u6-C12',3,'essay','teacher','얼룩말 그림을 보고, 얼룩말이 주택가에 나타나기 전에 있었을 일(원인)과 그 뒤에 벌어질 일(결과)을 예상해 쓰세요. 그렇게 예상한 까닭도 그림에서 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C12","difficulty":3,"kind":"essay","stem":"얼룩말 그림을 보고, 얼룩말이 주택가에 나타나기 전에 있었을 일(원인)과 그 뒤에 벌어질 일(결과)을 예상해 쓰세요. 그렇게 예상한 까닭도 그림에서 찾아 쓰세요.","answer_guide":{"answer":"예: 이전에 있었던 일 — 근처 동물원에서 얼룩말이 탈출했을 것이다. 뒤에 벌어질 일 — 얼룩말이 번잡한 도심에 놀라 여러 물건을 망가뜨렸을 것이다. 까닭 — 얼룩말은 동물원에나 있을 법한 동물인데 주택가에 있고, 아저씨도 놀란 표정을 짓고 있기 때문이다.","scoring_points":["중심 사건 이전에 있었을 일(원인)을 썼는가","중심 사건 뒤에 벌어질 일(결과)을 썼는가","그렇게 예상한 까닭을 그림에 근거해 썼는가"]},"explanation":["먼저 중심 사건을 붙잡아요.","그 앞은 원인, 그 뒤는 결과로 이어 써요.","예상은 저마다 달라도 까닭은 그림에서 찾아요."],"asset":{"type":"passage","lines":["[그림] 사람들이 사는 주택가 한복판에 얼룩말이 나타났다.","[그림] 그 모습을 본 아저씨가 놀란 표정을 짓고 있다."],"numbered":false,"title":"영상의 한 장면 — 『국어』 258쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#1','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C6',2,'mc','auto','「무엇을 배울까요」를 살펴보았어요. 소단원 2에서 가장 먼저 배울 내용은 무엇인가요?',ARRAY['K4-2-u6-X19']::text[],false,'{"seq":1,"concept":"K4-2-u6-C6","difficulty":2,"kind":"mc","stem":"「무엇을 배울까요」를 살펴보았어요. 소단원 2에서 가장 먼저 배울 내용은 무엇인가요?","options":[{"t":"이어질 내용을 상상해 쓰는 방법 알기","correct":true},{"t":"원인과 결과를 생각하며 영상 보기","mis":"K4-2-u6-X19"},{"t":"원인과 결과를 생각하며 이야기 듣기","mis":"K4-2-u6-X19"},{"t":"이야기를 읽고 이어질 내용을 상상해 쓰기","mis":"K4-2-u6-X19"}],"explanation":["소단원 1은 원인과 결과를 생각하며 듣기예요.","소단원 2는 이어질 내용을 상상해 쓰기예요.","소단원 2에서는 쓰는 방법을 먼저 알고, 그다음 이야기를 읽고 써요."],"asset":{"type":"passage","lines":["소단원 1 원인과 결과를 생각하며 듣기","  ① 원인과 결과를 생각하며 영상 보기","  ② 원인과 결과를 생각하며 이야기 듣기","소단원 2 이어질 내용을 상상해 쓰기","  ① 이어질 내용을 상상해 쓰는 방법 알기","  ② 이야기를 읽고 이어질 내용을 상상해 쓰기"],"numbered":false,"title":"무엇을 배울까요 — 『국어』 255쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#2','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C13',2,'mc','auto','영상을 보며 내용을 기억하려고 메모를 해요. 메모하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X14','K4-2-u6-X07','K4-2-u6-X08']::text[],false,'{"seq":2,"concept":"K4-2-u6-C13","difficulty":2,"kind":"mc","stem":"영상을 보며 내용을 기억하려고 메모를 해요. 메모하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"중심 사건, 그 일이 일어난 까닭, 그래서 어떻게 되었는지를 기호나 화살표를 써서 간단히 적는다","correct":true},{"t":"들리는 말을 한 글자도 빼지 않고 모두 받아 적는다","mis":"K4-2-u6-X14"},{"t":"영상이 다 끝난 뒤에 기억나는 것만 한 번에 적는다","mis":"K4-2-u6-X07"},{"t":"사람들의 옷 색깔처럼 눈에 띄는 것부터 적는다","mis":"K4-2-u6-X08"}],"explanation":["메모는 본 내용을 기억하는 데 도움이 돼요.","글자만 쓰지 않고 기호나 화살표를 써도 돼요.","무엇이 일어났고 왜, 그래서 어떻게 되었는지가 남게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#3','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C1',3,'error','auto','『국어』 254쪽 3번처럼 형광 바다를 친구들에게 설명했어요. 원인과 결과를 알맞지 않게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X01']::text[],false,'{"seq":3,"concept":"K4-2-u6-C1","difficulty":3,"kind":"error","stem":"『국어』 254쪽 3번처럼 형광 바다를 친구들에게 설명했어요. 원인과 결과를 알맞지 않게 말한 것은 무엇인가요?","options":[{"t":"“관광객이 많이 찾아온 결과, 바닷속에 빛을 내는 생물들이 살게 되었어.”","correct":true,"mis_target":"K4-2-u6-X01"},{"t":"“밤이면 바다가 푸른 형광색으로 변하는 까닭은 바닷속에 빛을 내는 생물들이 살고 있기 때문이야.”","mis":"K4-2-u6-X01"},{"t":"“그 결과, 바닷가는 많은 관광객으로 붐비게 되었어.”","mis":"K4-2-u6-X01"}],"explanation":["빛을 내는 생물이 바닷속에 사는 것이 처음 원인이에요.","바다가 빛나는 모습을 보러 관광객이 찾아온 것은 결과예요.","관광객 때문에 생물이 살게 되었다는 말은 원인과 결과를 거꾸로 이은 것이에요."],"asset":{"type":"speech","turns":[{"who":"뉴스","text":"밤이면 푸른 형광색으로 변하는 바다가 있다고 합니다. 그 까닭은 자극을 받으면 빛을 내는 생물이 바닷속에 있기 때문입니다."},{"who":"뉴스","text":"이 신기한 모습을 보기 위해 관광객이 많아지고 있다고 합니다."},{"who":"수영","text":"너희 그거 알아? 밤이면 푸른 형광색으로 변하는 바다가 있대."},{"who":"친구","text":"왜 그런 일이 생긴 거야?"},{"who":"수영","text":"관광객이 많아서 그랬다고 한 것 같은데?"},{"who":"친구","text":"관광객?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#4','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C55',3,'mc','auto','방울토마토를 ㉯처럼 「누군가 가져갔다」고 예상한 친구가 영상의 뒷부분을 보았어요. 자신의 예상과 같은 점으로 쓸 수 있는 것은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X09','K4-2-u6-X11']::text[],false,'{"seq":4,"concept":"K4-2-u6-C55","difficulty":3,"kind":"mc","stem":"방울토마토를 ㉯처럼 「누군가 가져갔다」고 예상한 친구가 영상의 뒷부분을 보았어요. 자신의 예상과 같은 점으로 쓸 수 있는 것은 무엇인가요?","options":[{"t":"방울토마토를 지키려고 무엇인가를 세워 노력했다는 점","correct":true},{"t":"사람이 방울토마토를 가져갔다는 점","mis":"K4-2-u6-X08"},{"t":"경고 팻말을 세웠다는 점","mis":"K4-2-u6-X09"},{"t":"내 예상과 같아서 기분이 좋았다는 점","mis":"K4-2-u6-X11"}],"explanation":["뒷부분에서 방울토마토를 가져간 것은 새였어요.","그래서 경고 팻말이 아니라 허수아비를 설치했어요.","방울토마토를 지키려고 노력한 부분은 예상과 같아요."],"asset":{"type":"passage","lines":["(간추림) 방울토마토는 사람이 아니라 새가 가져간 것이었다.","(간추림) 그래서 새를 쫓는 방법으로 허수아비를 설치했다."],"title":"「소연이네 반에서 일어난 일」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#5','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C10',3,'mc','auto','자신의 예상과 영상의 뒷부분을 비교해 쓴 글이에요. 인과 관계에 초점을 맞추어 알맞게 쓴 것은 무엇인가요?',ARRAY['K4-2-u6-X11','K4-2-u6-X54']::text[],false,'{"seq":5,"concept":"K4-2-u6-C10","difficulty":3,"kind":"mc","stem":"자신의 예상과 영상의 뒷부분을 비교해 쓴 글이에요. 인과 관계에 초점을 맞추어 알맞게 쓴 것은 무엇인가요?","options":[{"t":"“새가 쪼아 먹었다는 것을 까닭으로 허수아비를 세울 것이라고 예상했는데 그 부분이 같았다.”","correct":true},{"t":"“내 예상과 같아서 좋았다.”","mis":"K4-2-u6-X11"},{"t":"“내 예상과 달라서 아쉬웠다.”","mis":"K4-2-u6-X11"},{"t":"“내 예상이 맞았으니 내가 정답을 맞힌 것이다.”","mis":"K4-2-u6-X54"}],"explanation":["같아서 좋았다, 달라서 아쉬웠다는 느낌만 말한 것이에요.","맞았는지만 따지는 것도 비교가 아니에요.","무엇을 까닭으로 예상했는데 어느 부분이 같거나 달랐는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#6','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C12',3,'ox','auto','방울토마토가 없어진 까닭을 「누군가 가져갔다」고 예상했는데 영상에서는 새가 가져간 것이었어요. 그러니 이 예상은 받아들일 수 없는 엉터리 예상이에요.',ARRAY['K4-2-u6-X55']::text[],false,'{"seq":6,"concept":"K4-2-u6-C12","difficulty":3,"kind":"ox","stem":"방울토마토가 없어진 까닭을 「누군가 가져갔다」고 예상했는데 영상에서는 새가 가져간 것이었어요. 그러니 이 예상은 받아들일 수 없는 엉터리 예상이에요.","answer":"X","reason_options":[{"t":"영상 앞부분의 내용으로 미루어 그럴 만한 까닭이라면 받아들일 수 있는 예상이기 때문에","correct":true},{"t":"실제 영상과 다르게 예상하면 모두 틀린 예상이기 때문에","mis":"K4-2-u6-X55"}],"mis":"K4-2-u6-X55","explanation":["예상은 정답을 맞히는 활동이 아니에요.","앞부분의 내용으로 보아 그럴 만하면 받아들여요.","다만 예상한 원인에 맞게 결과도 달라져야 해요."],"asset":{"type":"passage","lines":["(간추림) 방울토마토는 사람이 아니라 새가 가져간 것이었다.","(간추림) 그래서 새를 쫓는 방법으로 허수아비를 설치했다."],"title":"「소연이네 반에서 일어난 일」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#7','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C56',3,'mc','auto','얼룩말이 사람들에게 피해를 주었을 것이라고 예상한 친구가 뉴스 영상을 보았어요. 예상과 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X54','K4-2-u6-X08','K4-2-u6-X19']::text[],false,'{"seq":7,"concept":"K4-2-u6-C56","difficulty":3,"kind":"mc","stem":"얼룩말이 사람들에게 피해를 주었을 것이라고 예상한 친구가 뉴스 영상을 보았어요. 예상과 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"얼룩말은 별다른 피해를 주지 않았고, 경찰과 소방관에 의해 동물원으로 돌아갔다","correct":true},{"t":"얼룩말이 동물원에서 탈출했다","mis":"K4-2-u6-X54"},{"t":"얼룩말이 사람들을 공격했다","mis":"K4-2-u6-X08"},{"t":"얼룩말이 주택가에 나타났다","mis":"K4-2-u6-X19"}],"explanation":["동물원에서 탈출했다는 예상은 뉴스와 같았어요.","피해를 주었을 것이라는 예상은 뉴스와 달랐어요.","같은 점과 다른 점을 원인과 결과에 따라 나누어 말해요."],"asset":{"type":"passage","lines":["(간추림) 얼룩말 세로가 동물원을 탈출해 주택가에 나타났다.","(간추림) 신고를 받고 출동한 경찰과 소방관이 얼룩말을 동물원에 돌려보냈다."],"title":"뉴스 영상의 내용 — 『국어』 259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#8','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C7',4,'essay','teacher','기억에 남는 우리 학교 소식 하나를 떠올려, 무슨 일이 일어났는지, 그 일이 왜 일어났는지, 그 결과 어떻게 되었는지가 드러나게 친구에게 설명하는 말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C7","difficulty":4,"kind":"essay","stem":"기억에 남는 우리 학교 소식 하나를 떠올려, 무슨 일이 일어났는지, 그 일이 왜 일어났는지, 그 결과 어떻게 되었는지가 드러나게 친구에게 설명하는 말을 쓰세요.","answer_guide":{"answer":"예: 지난주에 우리 학교 운동회가 다음 주로 미루어졌어. 운동회 날 아침에 비가 많이 와서 운동장이 물웅덩이투성이가 되었기 때문이야. 그 결과 우리는 운동회 대신 교실에서 수업을 했고, 일주일 동안 이어달리기 연습을 더 할 수 있었어.","scoring_points":["무슨 일이 일어났는지 썼는가","그 일이 일어난 원인을 썼는가","그 결과 어떻게 되었는지 썼는가"]},"explanation":["소식에서 일어난 일을 먼저 붙잡아요.","「왜냐하면 …… 때문이야」로 원인을 말해요.","「그 결과」로 어떻게 되었는지 이어요."],"asset":{"type":"passage","lines":["● 기억에 남는 학교 소식이 있나요?","● 내용은 무엇이었나요?","● 그 사건은 왜 일어났나요?","● 그 결과 어떻게 되었나요?"],"numbered":false,"title":"기억에 남는 우리 학교 소식 떠올리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#9','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C10',4,'essay','teacher','얼룩말 그림을 보고 예상한 내용과 뉴스 영상의 내용을 비교해, 같은 점과 다른 점을 「무엇을 까닭으로 예상했는데 어느 부분이 같았다/달랐다」가 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C10","difficulty":4,"kind":"essay","stem":"얼룩말 그림을 보고 예상한 내용과 뉴스 영상의 내용을 비교해, 같은 점과 다른 점을 「무엇을 까닭으로 예상했는데 어느 부분이 같았다/달랐다」가 드러나게 쓰세요.","answer_guide":{"answer":"예: 얼룩말이 동물원에나 있을 법한 동물이라는 것을 까닭으로 동물원에서 탈출했을 것이라고 예상했는데 그 부분이 같았다. 번잡한 도심에 놀라 사람들에게 피해를 주었을 것이라고 예상했는데, 영상을 보니 얼룩말은 별다른 피해를 주지 않고 경찰과 소방관에 의해 동물원으로 돌아간 점이 달랐다.","scoring_points":["같은 점을 예상의 까닭과 함께 썼는가","다른 점을 예상의 까닭과 함께 썼는가","「좋았다·아쉬웠다」 같은 느낌만 쓰지 않았는가"]},"explanation":["먼저 내가 무엇을 까닭으로 예상했는지 떠올려요.","영상에서 같은 부분과 다른 부분을 찾아요.","인과 관계에 초점을 맞추어 비교해요."],"asset":{"type":"passage","lines":["(간추림) 얼룩말 세로가 동물원을 탈출해 주택가에 나타났다.","(간추림) 신고를 받고 출동한 경찰과 소방관이 얼룩말을 동물원에 돌려보냈다."],"title":"뉴스 영상의 내용 — 『국어』 259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L02_challenge#10','kor',4,2,'u6','L02','tb_g4_2_kor_u6_L02_challenge','lesson_challenge','K4-2-u6-C1',4,'essay','teacher','『국어』 254쪽 3번처럼, 밤이면 바다가 푸른 형광색으로 변하는 사건을 원인과 결과를 생각하며 친구들에게 설명하는 말을 쓰세요. 「원인」과 「결과」라는 말을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C1","difficulty":4,"kind":"essay","stem":"『국어』 254쪽 3번처럼, 밤이면 바다가 푸른 형광색으로 변하는 사건을 원인과 결과를 생각하며 친구들에게 설명하는 말을 쓰세요. 「원인」과 「결과」라는 말을 넣어 쓰세요.","answer_guide":{"answer":"예: 밤이면 푸른 형광색으로 변하는 바다가 있어. 이런 일이 발생하는 원인은 자극을 받으면 빛을 내는 생물들이 바닷속에 살고 있기 때문이야. 그 결과, 바닷가는 이 신기한 모습을 보려는 많은 관광객으로 붐비게 되었어.","scoring_points":["일어난 일(바다가 형광색으로 변함)을 썼는가","원인(빛을 내는 생물)을 바르게 썼는가","결과(관광객이 많아짐)를 바르게 이어 썼는가"]},"explanation":["일어난 일을 먼저 말해요.","바다가 빛나는 까닭은 바닷속 생물이에요.","관광객은 그 결과로 이어 말해요."],"asset":{"type":"passage","lines":["원인 자극을 받으면 빛을 내는 생물들이 바닷속에 살고 있다.","→ 밤이면 바다가 푸른 형광색으로 빛난다.","결과 신기한 모습에 반해 많은 관광객이 찾게 되었다."],"numbered":false,"title":"수영이가 본 영상 속 사건의 원인과 결과 — 『국어』 254쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#1','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C23',1,'mc','auto','경험 떠올리기 만화를 읽었어요. 세린이에게 어떤 일이 일어났나요?',ARRAY['K4-2-u6-X08','K4-2-u6-X01']::text[],false,'{"seq":1,"concept":"K4-2-u6-C23","difficulty":1,"kind":"mc","stem":"경험 떠올리기 만화를 읽었어요. 세린이에게 어떤 일이 일어났나요?","options":[{"t":"눈이 오는 날 얇은 옷을 입고 밖에 나가서 놀다가 감기에 걸렸다","correct":true},{"t":"엄마 말씀대로 옷을 따뜻하게 입고 놀았다","mis":"K4-2-u6-X08"},{"t":"병원에 갔다가 넘어져서 다쳤다","mis":"K4-2-u6-X08"},{"t":"감기에 걸려서 밖에 나가 놀았다","mis":"K4-2-u6-X01"}],"explanation":["엄마는 옷을 따뜻하게 입으라고 하셨어요.","세린이는 눈 오는 날 얇은 옷차림으로 밖에서 놀았어요.","그래서 감기에 걸려 병원에 갔어요."],"asset":{"type":"passage","lines":["1 엄마: “세린아, 오늘 날씨가 추우니까 옷 따뜻하게 입어.” 세린: “네.”","2 세린: “얼른 밖에 나가서 놀아야지!” [그림] 눈이 오는 날 얇은 옷차림","3 엄마: “감기에 걸렸나 보네. 얼른 병원에 가자.”","4 의사: “‘아’ 해 보세요.” 세린: “아.”"],"numbered":false,"title":"경험 떠올리기 만화 — 『국어』 260쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#2','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C14',1,'mc','auto','만화에서 「감기에 걸렸다」는 어떤 일인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X02']::text[],false,'{"seq":2,"concept":"K4-2-u6-C14","difficulty":1,"kind":"mc","stem":"만화에서 「감기에 걸렸다」는 어떤 일인가요?","options":[{"t":"얇은 옷차림으로 논 일의 결과이면서, 병원에 간 일의 원인","correct":true},{"t":"병원에 간 일의 결과","mis":"K4-2-u6-X01"},{"t":"얇은 옷차림으로 논 일의 원인","mis":"K4-2-u6-X01"},{"t":"다른 일과 이어지지 않는 일","mis":"K4-2-u6-X02"}],"explanation":["얇은 옷차림으로 밖에서 논 결과 감기에 걸렸어요.","감기에 걸려서 병원에 갔어요.","어떤 일의 결과가 다음 일의 원인이 되기도 해요."],"asset":{"type":"passage","lines":["1 엄마: “세린아, 오늘 날씨가 추우니까 옷 따뜻하게 입어.” 세린: “네.”","2 세린: “얼른 밖에 나가서 놀아야지!” [그림] 눈이 오는 날 얇은 옷차림","3 엄마: “감기에 걸렸나 보네. 얼른 병원에 가자.”","4 의사: “‘아’ 해 보세요.” 세린: “아.”"],"numbered":false,"title":"경험 떠올리기 만화 — 『국어』 260쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#3','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C57',1,'sa','auto','「방 씨 규수의 이야기」에서 방 씨 규수가 화살인 척하며 대청마루 위에 한 아름 내던진 것은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u6-C57","difficulty":1,"kind":"sa","stem":"「방 씨 규수의 이야기」에서 방 씨 규수가 화살인 척하며 대청마루 위에 한 아름 내던진 것은 무엇인지 쓰세요.","answer":["대나무","베 짜는 데 쓰던 대나무","대나무 한 아름"],"explanation":["방 씨 규수는 베 짜는 데 쓰던 물건을 가져왔어요.","그것을 한 아름 대청마루 위에 내던졌어요.","떨어지는 소리가 화살이 쏟아지는 소리 같았어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#4','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C21',1,'mc','auto','「방 씨 규수의 이야기」에서 짐작할 수 있는 방 씨 규수의 성격으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X23','K4-2-u6-X20']::text[],false,'{"seq":4,"concept":"K4-2-u6-C21","difficulty":1,"kind":"mc","stem":"「방 씨 규수의 이야기」에서 짐작할 수 있는 방 씨 규수의 성격으로 알맞은 것은 무엇인가요?","options":[{"t":"지혜롭고 침착하다","correct":true},{"t":"겁이 많고 쉽게 당황한다","mis":"K4-2-u6-X23"},{"t":"욕심이 많다","mis":"K4-2-u6-X23"},{"t":"게으르다","mis":"K4-2-u6-X20"}],"explanation":["화살이 떨어진 다급한 때에 방 씨 규수가 나섰어요.","대나무를 화살인 척 내던져 도둑들을 속였어요.","이런 행동에서 지혜롭고 침착한 성격을 짐작할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#5','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C57',2,'mc','auto','도둑들이 하인을 시켜 방진의 화살을 미리 없앤 까닭은 무엇인가요?',ARRAY['K4-2-u6-X13','K4-2-u6-X08','K4-2-u6-X01']::text[],false,'{"seq":5,"concept":"K4-2-u6-C57","difficulty":2,"kind":"mc","stem":"도둑들이 하인을 시켜 방진의 화살을 미리 없앤 까닭은 무엇인가요?","options":[{"t":"방진이 백발백중의 활쏘기 솜씨로 소문이 자자해서, 화살로 자신들을 공격하지 못하게 하려고","correct":true},{"t":"화살을 팔아 돈을 벌려고","mis":"K4-2-u6-X13"},{"t":"방진에게 새 화살을 선물하려고","mis":"K4-2-u6-X08"},{"t":"방 씨 규수가 대나무를 던지게 하려고","mis":"K4-2-u6-X01"}],"explanation":["방진은 활쏘기 솜씨로 소문난 사람이었어요.","도둑들은 그 소문을 듣고 미리 손을 써 두었어요.","화살이 없으면 공격을 받지 않을 것이라 생각했어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#6','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C57',2,'mc','auto','방 씨 규수가 대나무를 한 아름 대청마루 위에 내던진 까닭은 무엇일까요?',ARRAY['K4-2-u6-X17','K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C57","difficulty":2,"kind":"mc","stem":"방 씨 규수가 대나무를 한 아름 대청마루 위에 내던진 까닭은 무엇일까요?","options":[{"t":"화살을 던질 때와 비슷한 소리가 나게 해서, 도둑들이 집에 화살이 있다고 생각하고 겁을 먹게 하려고","correct":true},{"t":"도둑들에게 대나무를 나누어 주려고","mis":"K4-2-u6-X17"},{"t":"대청마루에서 베를 짜려고","mis":"K4-2-u6-X08"},{"t":"대청마루를 깨끗이 치우려고","mis":"K4-2-u6-X17"}],"explanation":["떨어지는 소리가 마치 화살이 쏟아지는 소리 같았어요.","도둑들은 집에 화살이 아직 많다고 생각했어요.","방 씨 규수는 소리로 도둑들에게 겁을 주려고 했어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#7','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C17',2,'mc','auto','「방 씨 규수의 이야기」를 다시 듣고 일이 일어난 차례대로 늘어놓았어요. 바른 것은 무엇인가요?',ARRAY['K4-2-u6-X19']::text[],false,'{"seq":7,"concept":"K4-2-u6-C17","difficulty":2,"kind":"mc","stem":"「방 씨 규수의 이야기」를 다시 듣고 일이 일어난 차례대로 늘어놓았어요. 바른 것은 무엇인가요?","options":[{"t":"㉰ → ㉮ → ㉱ → ㉯","correct":true},{"t":"㉮ → ㉰ → ㉱ → ㉯","mis":"K4-2-u6-X19"},{"t":"㉮ → ㉱ → ㉯ → ㉰","mis":"K4-2-u6-X19"},{"t":"㉱ → ㉮ → ㉰ → ㉯","mis":"K4-2-u6-X19"}],"explanation":["이야기에서는 도둑들이 쳐들어온 뒤에 화살을 훔친 일이 나와요.","하지만 하인이 화살을 훔친 일은 그보다 먼저 일어났어요.","시간의 흐름에 따라 정리하면 원인과 결과가 잘 보여요."],"asset":{"type":"passage","lines":["㉮ 도둑들이 방진의 집 앞마당까지 쳐들어왔다.","㉯ 도둑들은 깜짝 놀라 달아났다.","㉰ 도둑들과 한편인 하인이 방진의 화살을 훔쳐 없애 버렸다.","㉱ 화살이 떨어지자 방 씨 규수가 대나무를 한 아름 대청마루 위에 내던졌다."],"numbered":false,"title":"일이 일어난 차례 정리하기 (뒤섞임) — 『국어』 262쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#8','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C18',2,'blank','auto','「방 씨 규수의 이야기」를 원인과 결과에 따라 정리했어요. ㉡에 들어갈 결과로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X18','K4-2-u6-X01']::text[],false,'{"seq":8,"concept":"K4-2-u6-C18","difficulty":2,"kind":"blank","stem":"「방 씨 규수의 이야기」를 원인과 결과에 따라 정리했어요. ㉡에 들어갈 결과로 알맞은 것은 무엇인가요?","options":[{"t":"도둑들이 화살인 줄 알고 도망갔다.","correct":true},{"t":"방진이 화살을 새로 사 왔다.","mis":"K4-2-u6-X18"},{"t":"하인이 방진의 화살을 훔쳤다.","mis":"K4-2-u6-X01"},{"t":"방 씨 규수가 베 짜는 대나무를 찾았다.","mis":"K4-2-u6-X01"}],"explanation":["대나무를 내던진 것이 원인이에요.","그 소리를 듣고 도둑들이 화살인 줄 알고 도망갔어요.","한 이야기에 원인과 결과의 짝이 여러 개 있어요."],"asset":{"type":"passage","lines":["원인 방진의 활쏘기 솜씨에 대한 소문을 듣고 미리 하인에게 손을 써서","대부분의 화살을 훔쳐서 가지고 나갔다.","결과 (    ㉠    )","원인 방 씨 규수가 대나무를 한 아름 화살인 척하며 대청마루 위에 내던졌다.","결과 (    ㉡    )"],"numbered":false,"title":"원인과 결과로 이야기 내용 정리하기 — 『국어』 263쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#9','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C22',2,'mc','auto','이야기를 들으며 원인과 결과를 파악하려고 해요. 듣는 동안 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X14','K4-2-u6-X07']::text[],false,'{"seq":9,"concept":"K4-2-u6-C22","difficulty":2,"kind":"mc","stem":"이야기를 들으며 원인과 결과를 파악하려고 해요. 듣는 동안 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나오는 사람, 일어난 일, 그 일의 까닭과 그다음 일을 간단히 메모한다","correct":true},{"t":"들은 말을 한 글자도 빼지 않고 받아 적는다","mis":"K4-2-u6-X14"},{"t":"이야기가 다 끝날 때까지 아무것도 생각하지 않는다","mis":"K4-2-u6-X07"},{"t":"마음에 드는 낱말만 골라 적는다","mis":"K4-2-u6-X07"}],"explanation":["이야기를 들을 때 간단히 메모하며 들어요.","누가, 무엇을, 왜 했는지가 남게 적어요.","메모를 보고 일어난 차례와 원인과 결과를 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_basic#10','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_basic','lesson_basic','K4-2-u6-C18',3,'essay','teacher','「방 씨 규수의 이야기」에서 원인과 결과의 짝을 『국어』 263쪽에 나온 것 말고 두 개 더 찾아 「(원인) …… → (결과) ……」로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C18","difficulty":3,"kind":"essay","stem":"「방 씨 규수의 이야기」에서 원인과 결과의 짝을 『국어』 263쪽에 나온 것 말고 두 개 더 찾아 「(원인) …… → (결과) ……」로 쓰세요.","answer_guide":{"answer":"예: (원인) 도둑들은 방진의 재산을 탐냈다. → (결과) 집 안마당까지 쳐들어왔다. / (원인) 방 씨 규수의 지혜로운 행동이 널리 전파되었다. → (결과) 방 씨 규수의 명성이 더욱 높아졌다.","scoring_points":["이야기에 나온 일끼리 짝을 지었는가","원인과 결과를 바르게 나누었는가","짝을 두 개 썼는가"]},"explanation":["가능한 한 많은 인과 관계를 찾아요.","이야기에 실제로 나온 일끼리만 이어요.","「그래서」를 넣어 읽어 말이 되면 짝이에요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#1','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C23',2,'mc','auto','다른 인물의 이야기 「포도 치마」를 들었어요. 신사임당이 여인에게 치마를 벗어서 건네 달라고 한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X13']::text[],false,'{"seq":1,"concept":"K4-2-u6-C23","difficulty":2,"kind":"mc","stem":"다른 인물의 이야기 「포도 치마」를 들었어요. 신사임당이 여인에게 치마를 벗어서 건네 달라고 한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"얼룩진 치마폭에 그림을 그려 치마를 되살려 주려고","correct":true},{"t":"치마를 빨아서 돌려주려고","mis":"K4-2-u6-X08"},{"t":"치마를 자기가 입으려고","mis":"K4-2-u6-X08"},{"t":"치마를 더럽힌 여인을 혼내려고","mis":"K4-2-u6-X13"}],"explanation":["여인은 빌려 입은 치마에 얼룩이 생겨 눈물을 글썽였어요.","신사임당은 치마폭에 붓으로 그림을 그렸어요.","얼룩이 멋진 포도송이로 바뀌었어요."],"asset":{"type":"passage","lines":["(간추림) 마을 잔칫날, 한 여인이 빌려 입은 치마에 국물을 쏟아 큰 얼룩이 생겼다.","(간추림) 신사임당은 여인을 달래며 치마를 벗어서 건네 달라고 했다.","(간추림) 신사임당은 정성스럽게 먹을 갈더니 치마폭에 붓으로 그림을 그렸다.","“얼룩이 어느새 멋진 포도송이로 바뀌었네!”","(간추림) 아름다운 치마는 비싼 값에 팔려 여인은 빌린 치맛값을 갚을 수 있었다."],"title":"「포도 치마」 간추린 내용 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#2','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C14',2,'blank','auto','「포도 치마」를 일의 차례, 원인과 결과에 따라 정리했어요. 빈칸에 알맞은 일은 무엇인가요?
(원인) 국물을 쏟아 치마에 큰 얼룩이 생겼다. → (결과·원인) (    ) → (결과) 포도 그림이 그려진 멋진 치마가 탄생했다.',ARRAY['K4-2-u6-X19','K4-2-u6-X01']::text[],false,'{"seq":2,"concept":"K4-2-u6-C14","difficulty":2,"kind":"blank","stem":"「포도 치마」를 일의 차례, 원인과 결과에 따라 정리했어요. 빈칸에 알맞은 일은 무엇인가요?\n(원인) 국물을 쏟아 치마에 큰 얼룩이 생겼다. → (결과·원인) (    ) → (결과) 포도 그림이 그려진 멋진 치마가 탄생했다.","options":[{"t":"신사임당이 얼룩진 치마폭에 붓으로 포도 그림을 그렸다","correct":true},{"t":"여인이 치마를 비싼 값에 팔았다","mis":"K4-2-u6-X19"},{"t":"여인이 잔치에 치마를 빌려 입고 왔다","mis":"K4-2-u6-X19"},{"t":"사람들이 깜짝 놀랐다","mis":"K4-2-u6-X01"}],"explanation":["얼룩이 생긴 일이 원인이 되어 신사임당이 그림을 그렸어요.","그림을 그린 일은 다시 원인이 되어 멋진 치마가 탄생했어요.","어떤 일의 결과는 또 다른 일의 원인이 될 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 마을 잔칫날, 한 여인이 빌려 입은 치마에 국물을 쏟아 큰 얼룩이 생겼다.","(간추림) 신사임당은 여인을 달래며 치마를 벗어서 건네 달라고 했다.","(간추림) 신사임당은 정성스럽게 먹을 갈더니 치마폭에 붓으로 그림을 그렸다.","“얼룩이 어느새 멋진 포도송이로 바뀌었네!”","(간추림) 아름다운 치마는 비싼 값에 팔려 여인은 빌린 치맛값을 갚을 수 있었다."],"title":"「포도 치마」 간추린 내용 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#3','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C19',3,'mc','auto','「방 씨 규수의 이야기」에서 도둑들이 도망간 데에는 여러 일이 함께 원인이 되었어요. 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X15','K4-2-u6-X18','K4-2-u6-X01']::text[],false,'{"seq":3,"concept":"K4-2-u6-C19","difficulty":3,"kind":"mc","stem":"「방 씨 규수의 이야기」에서 도둑들이 도망간 데에는 여러 일이 함께 원인이 되었어요. 알맞게 말한 것은 무엇인가요?","options":[{"t":"도둑들이 방진의 활쏘기 솜씨를 알고 있었고, 대나무 소리가 화살이 쏟아지는 소리처럼 들렸다","correct":true},{"t":"대나무 소리 하나만이 원인이다","mis":"K4-2-u6-X15"},{"t":"도둑들이 원래 겁이 많은 사람들이었다","mis":"K4-2-u6-X18"},{"t":"방진이 다음 날 도둑들을 찾아냈다","mis":"K4-2-u6-X01"}],"explanation":["도둑들은 방진이 활을 잘 쏜다는 것을 알고 두려워했어요.","그런데 화살이 아직 많은 것 같은 소리가 났어요.","한 가지 결과에 원인이 여럿일 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#4','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C20',3,'error','auto','「방 씨 규수의 이야기」에서 찾은 원인과 결과의 짝이에요. 이야기에 나오지 않은 일을 끌어와 알맞지 않게 이은 것은 무엇인가요?',ARRAY['K4-2-u6-X18']::text[],false,'{"seq":4,"concept":"K4-2-u6-C20","difficulty":3,"kind":"error","stem":"「방 씨 규수의 이야기」에서 찾은 원인과 결과의 짝이에요. 이야기에 나오지 않은 일을 끌어와 알맞지 않게 이은 것은 무엇인가요?","options":[{"t":"“도둑들이 방진의 재산을 탐냈다. → 그래서 방진은 집 둘레에 담을 높이 쌓았다.”","correct":true,"mis_target":"K4-2-u6-X18"},{"t":"“방 씨 규수의 지혜로운 행동이 널리 전파되었다. → 방 씨 규수의 명성이 더욱 높아졌다.”","mis":"K4-2-u6-X18"},{"t":"“도둑들은 방진의 재산을 탐냈다. → 집 안마당까지 쳐들어왔다.”","mis":"K4-2-u6-X18"}],"explanation":["원인과 결과의 짝은 이야기에 실제로 나온 일끼리 이어요.","담을 높이 쌓았다는 일은 이야기에 나오지 않아요.","그럴듯해도 나오지 않은 일은 끌어오지 않아요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#5','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C21',3,'mc','auto','방 씨 규수가 침착한 성격이라는 것을 짐작할 수 있는 근거로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X20']::text[],false,'{"seq":5,"concept":"K4-2-u6-C21","difficulty":3,"kind":"mc","stem":"방 씨 규수가 침착한 성격이라는 것을 짐작할 수 있는 근거로 가장 알맞은 것은 무엇인가요?","options":[{"t":"화살이 떨어진 다급한 때에 당황하지 않고 대나무를 화살인 척 내던졌다","correct":true},{"t":"방 씨 규수의 나이가 열두 살이었다","mis":"K4-2-u6-X20"},{"t":"방 씨 규수가 뒷날 이순신 장군과 혼인했다","mis":"K4-2-u6-X20"},{"t":"방 씨 규수의 아버지가 활을 잘 쏘았다","mis":"K4-2-u6-X20"}],"explanation":["성격은 인물이 처한 상황에서 한 말과 행동으로 짐작해요.","나이나 집안은 성격의 근거가 아니에요.","다급한 때에 침착하게 꾀를 낸 행동이 근거예요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#6','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C14',3,'mc','auto','『국어활동』 83쪽 「도경이가 겪은 일」 정리에서 원인으로도, 결과로도 쓰인 일을 모두 고른 것은 무엇인가요?',ARRAY['K4-2-u6-X02','K4-2-u6-X15']::text[],false,'{"seq":6,"concept":"K4-2-u6-C14","difficulty":3,"kind":"mc","stem":"『국어활동』 83쪽 「도경이가 겪은 일」 정리에서 원인으로도, 결과로도 쓰인 일을 모두 고른 것은 무엇인가요?","options":[{"t":"빠르게 달린 일, 지수와 함께 넘어진 일","correct":true},{"t":"우리 편이 뒤처진 일, 석고 붕대를 한 일","mis":"K4-2-u6-X02"},{"t":"지수와 함께 넘어진 일 하나뿐","mis":"K4-2-u6-X15"},{"t":"네 가지 일 모두","mis":"K4-2-u6-X02"}],"explanation":["뒤처진 일은 처음 원인이고, 석고 붕대를 한 일은 마지막 결과예요.","빠르게 달린 일과 넘어진 일은 앞 일의 결과이면서 뒤 일의 원인이에요.","가운데에 있는 일은 두 몫을 함께 해요."],"asset":{"type":"passage","lines":["이어달리기 시합에서 우리 편이 뒤처지기 시작했다.","→ 나는 상대편인 지수를 따라잡기 위해 더욱 빠르게 달렸다.","→ 발이 엉키면서 지수와 함께 넘어졌다.","→ 지수는 발목에 석고 붕대를 하게 됐다."],"numbered":false,"title":"『국어활동』 83쪽 예시 답안에 실린 「도경이가 겪은 일」 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#7','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C23',3,'mc','auto','나눔의 날 인터뷰에서 어린이가 「굉장히 보람 있고 뿌듯했어요.」라고 했어요. 그 원인으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X18','K4-2-u6-X01','K4-2-u6-X16']::text[],false,'{"seq":7,"concept":"K4-2-u6-C23","difficulty":3,"kind":"mc","stem":"나눔의 날 인터뷰에서 어린이가 「굉장히 보람 있고 뿌듯했어요.」라고 했어요. 그 원인으로 알맞은 것은 무엇인가요?","options":[{"t":"사용하지 않지만 깨끗하고 쓸모 있는 물건을 필요한 친구들에게 나누어 주었다","correct":true},{"t":"샤프를 한 자루 잃어버렸다","mis":"K4-2-u6-X18"},{"t":"서랍 속에 물건을 잔뜩 모아 두었다","mis":"K4-2-u6-X01"},{"t":"행사에 사람이 많이 모였다","mis":"K4-2-u6-X16"}],"explanation":["어린이는 쓰지 않는 물건을 필요한 친구들에게 나누었어요.","그래서 보람 있고 뿌듯한 마음이 들었어요.","마음(결과)에도 그렇게 된 까닭(원인)이 있어요."],"asset":{"type":"passage","lines":["(간추림) ○○시에서 ‘나눔의 날’ 행사가 열렸다.","어린이: 사용하지 않는 깨끗하고 쓸모 있는 물건들을 필요한 친구들에게 나누어 주었습니다.","어린이: 친구는 사용하지 않지만 저에게는 꼭 필요한 샤프를 한 자루 받았어요.","어린이: 굉장히 보람 있고 뿌듯했어요.","어린이: 서랍 속에 잠자고 있던 물건이 꼭 필요한 사람에게 가게 되어 기뻤고요."],"numbered":false,"title":"원인과 결과를 생각하며 글 읽기 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#8','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C14',4,'essay','teacher','「포도 치마」의 내용을 일의 차례, 원인과 결과에 따라 네 칸으로 정리하세요. 가운데 칸의 일이 어떻게 결과이면서 원인이 되는지 밝혀 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C14","difficulty":4,"kind":"essay","stem":"「포도 치마」의 내용을 일의 차례, 원인과 결과에 따라 네 칸으로 정리하세요. 가운데 칸의 일이 어떻게 결과이면서 원인이 되는지 밝혀 쓰세요.","answer_guide":{"answer":"예: 국물을 쏟아 치마에 큰 얼룩이 생겼다. → 신사임당이 얼룩진 치마폭에 포도 그림을 그렸다. → 포도 그림이 그려진 멋진 치마가 탄생했다. → 치마가 비싼 값에 팔려 여인은 빌린 치맛값을 갚았다. 그림을 그린 일은 얼룩이 생긴 일의 결과이면서 멋진 치마가 탄생한 원인이다.","scoring_points":["일이 일어난 차례대로 썼는가","원인과 결과가 이어지게 썼는가","결과이면서 원인인 일을 밝혀 썼는가"]},"explanation":["먼저 일이 일어난 차례를 정리해요.","앞 일이 뒤 일의 까닭인지 확인해요.","어떤 일의 결과는 또 다른 일의 원인이 돼요."],"asset":{"type":"passage","lines":["(간추림) 마을 잔칫날, 한 여인이 빌려 입은 치마에 국물을 쏟아 큰 얼룩이 생겼다.","(간추림) 신사임당은 여인을 달래며 치마를 벗어서 건네 달라고 했다.","(간추림) 신사임당은 정성스럽게 먹을 갈더니 치마폭에 붓으로 그림을 그렸다.","“얼룩이 어느새 멋진 포도송이로 바뀌었네!”","(간추림) 아름다운 치마는 비싼 값에 팔려 여인은 빌린 치맛값을 갚을 수 있었다."],"title":"「포도 치마」 간추린 내용 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#9','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C18',4,'essay','teacher','『국어활동』 83쪽 3번처럼, 원인과 결과를 생각하며 「도경이가 겪은 일」의 뒷이야기를 상상해 쓰세요. 앞 이야기의 결과(지수의 석고 붕대)가 원인이 되어 이어지게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C18","difficulty":4,"kind":"essay","stem":"『국어활동』 83쪽 3번처럼, 원인과 결과를 생각하며 「도경이가 겪은 일」의 뒷이야기를 상상해 쓰세요. 앞 이야기의 결과(지수의 석고 붕대)가 원인이 되어 이어지게 쓰세요.","answer_guide":{"answer":"예: 나는 용기를 내어 지수에게 미안하다고 말했다. 지수는 크게 다친 것은 아니니 신경 쓰지 말라고 말해 주었다. 나는 지수의 다리가 나을 때까지 지수의 가방을 들어 주며 함께 등교하기로 결심했다.","scoring_points":["앞 이야기의 마지막 결과에서 이어 썼는가","원인과 결과가 자연스럽게 이어지는가","인물이 할 법한 행동으로 썼는가"]},"explanation":["앞 이야기의 마지막 일을 다시 읽어요.","그 일이 원인이 되어 무슨 일이 생길지 생각해요.","뒷이야기가 자연스럽게 이어졌는지 점검해요."],"asset":{"type":"passage","lines":["이어달리기 시합에서 우리 편이 뒤처지기 시작했다.","→ 나는 상대편인 지수를 따라잡기 위해 더욱 빠르게 달렸다.","→ 발이 엉키면서 지수와 함께 넘어졌다.","→ 지수는 발목에 석고 붕대를 하게 됐다."],"numbered":false,"title":"『국어활동』 83쪽 예시 답안에 실린 「도경이가 겪은 일」 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L04_challenge#10','kor',4,2,'u6','L04','tb_g4_2_kor_u6_L04_challenge','lesson_challenge','K4-2-u6-C23',4,'essay','teacher','「서윤이의 일기」를 듣고, 서윤이가 집에 늦게 돌아온 까닭을 원인과 결과가 드러나게 쓰고, 서윤이가 「억울한 생각」이 든 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C23","difficulty":4,"kind":"essay","stem":"「서윤이의 일기」를 듣고, 서윤이가 집에 늦게 돌아온 까닭을 원인과 결과가 드러나게 쓰고, 서윤이가 「억울한 생각」이 든 까닭도 쓰세요.","answer_guide":{"answer":"예: 서윤이는 길을 잃은 어린이를 아무도 도와주지 않는 것을 보고 걱정이 되어 근처 파출소까지 데려다주고 왔기 때문에 늦었다. 그런데 어머니께서 놀다 오느라 늦은 것으로 오해하셔서 억울한 생각이 들었다.","scoring_points":["늦은 까닭(어린이를 도와줌)을 썼는가","「때문에」처럼 원인과 결과가 드러나게 썼는가","억울한 까닭(어머니의 오해)을 썼는가"]},"explanation":["이야기를 듣고 일이 일어난 차례를 떠올려요.","「왜냐하면 …… 때문이다」를 넣어 까닭을 밝혀요.","서윤이의 마음에도 원인이 있어요."],"asset":{"type":"passage","lines":["(간추림) 학교를 마치고 오는 길에 혼자 울고 있는 대여섯 살쯤 된 아이를 보았다.","(간추림) 누가 도와주겠지 하고 지나갔다가, 아무도 돕지 않아 아이에게 되돌아갔다.","“집을 못 찾겠어.” “이사 와서 몰라.”","(간추림) 가까운 파출소의 경찰관 아저씨께 아이를 데려다주니 뿌듯한 마음이 들었다.","“서윤아, 도대체 왜 이렇게 늦었어? 어디에서 놀다 온 거니?”","(간추림) 평소보다 한참 늦어 죄송했지만 한편으로 억울한 생각이 들었다."],"title":"「서윤이의 일기」 간추린 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#1','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C58',1,'mc','auto','「당나귀 실베스터와 요술 조약돌」을 읽고 만든 질문이에요. 「모양과 색깔이 특이한 조약돌을 모으는 것을 좋아하는 등장인물은 누구인가요?」의 답은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":1,"concept":"K4-2-u6-C58","difficulty":1,"kind":"mc","stem":"「당나귀 실베스터와 요술 조약돌」을 읽고 만든 질문이에요. 「모양과 색깔이 특이한 조약돌을 모으는 것을 좋아하는 등장인물은 누구인가요?」의 답은 무엇인가요?","options":[{"t":"실베스터","correct":true},{"t":"사자","mis":"K4-2-u6-X08"},{"t":"실베스터의 엄마","mis":"K4-2-u6-X08"},{"t":"실베스터의 아빠","mis":"K4-2-u6-X08"}],"explanation":["이야기 첫머리에 실베스터가 좋아하는 것이 나와요.","실베스터는 특이한 조약돌 모으기를 좋아했어요.","답이 글에 그대로 있는 질문은 글을 다시 보며 찾아요."],"asset":{"type":"passage","lines":["(간추림) 꼬마 당나귀 실베스터는 모양과 색깔이 특이한 조약돌 모으기를 좋아했다.","(간추림) 비 오는 토요일, 시냇가에서 새빨갛고 동그란 조약돌 하나를 찾아냈다.","“아, 제발 비 좀 그만 왔으면.”","(간추림) 그러자 비가 한순간에 딱 그쳤다.","(간추림) 돌을 땅 위에 내려놓고 말했을 때는 아무 일도 일어나지 않았지만,","(간추림) 돌을 손에 쥐고 같은 말을 하자 비가 억수같이 쏟아졌다."],"title":"「당나귀 실베스터와 요술 조약돌」 앞부분 — 『국어』 264~265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#2','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C58',1,'sa','auto','실베스터가 사자와 마주쳤을 때 요술 조약돌을 손에 쥐고 빈 소원은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u6-C58","difficulty":1,"kind":"sa","stem":"실베스터가 사자와 마주쳤을 때 요술 조약돌을 손에 쥐고 빈 소원은 무엇인지 쓰세요.","answer":["바위가 되는 것","바위","바위가 되고 싶다","바위면 좋겠다","바위가 되게 해 달라는 것"],"explanation":["실베스터는 굶주린 사자를 보고 너무 놀라고 당황했어요.","그래서 「내, 내가 바, 바, 바위면 좋겠어.」라고 말했어요.","그러자 곧바로 바위가 되었어요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#3','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C58',1,'mc','auto','실베스터가 알아낸 요술 조약돌의 요술이 일어나는 때는 언제인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X18','K4-2-u6-X13']::text[],false,'{"seq":3,"concept":"K4-2-u6-C58","difficulty":1,"kind":"mc","stem":"실베스터가 알아낸 요술 조약돌의 요술이 일어나는 때는 언제인가요?","options":[{"t":"조약돌이 몸에 닿은 채 소원을 말할 때","correct":true},{"t":"조약돌을 땅 위에 내려놓고 소원을 말할 때","mis":"K4-2-u6-X08"},{"t":"비가 오는 날에만","mis":"K4-2-u6-X18"},{"t":"소원을 큰 소리로 외칠 때","mis":"K4-2-u6-X13"}],"explanation":["돌을 땅에 내려놓고 말했을 때는 아무 일도 일어나지 않았어요.","돌을 손에 쥐고 말하자 비가 쏟아졌어요.","요술은 돌이 몸에 닿아야 일어나요."],"asset":{"type":"passage","lines":["(간추림) 꼬마 당나귀 실베스터는 모양과 색깔이 특이한 조약돌 모으기를 좋아했다.","(간추림) 비 오는 토요일, 시냇가에서 새빨갛고 동그란 조약돌 하나를 찾아냈다.","“아, 제발 비 좀 그만 왔으면.”","(간추림) 그러자 비가 한순간에 딱 그쳤다.","(간추림) 돌을 땅 위에 내려놓고 말했을 때는 아무 일도 일어나지 않았지만,","(간추림) 돌을 손에 쥐고 같은 말을 하자 비가 억수같이 쏟아졌다."],"title":"「당나귀 실베스터와 요술 조약돌」 앞부분 — 『국어』 264~265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#4','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C26',1,'ox','auto','인물의 성격은 인물의 말과 행동을 보면 알 수 있어요.',ARRAY['K4-2-u6-X20']::text[],false,'{"seq":4,"concept":"K4-2-u6-C26","difficulty":1,"kind":"ox","stem":"인물의 성격은 인물의 말과 행동을 보면 알 수 있어요.","answer":"O","reason_options":[{"t":"성격을 알면 인물이 앞으로 할 행동을 예상할 수 있고, 성격은 말과 행동에 드러나기 때문에","correct":true},{"t":"성격은 이야기 첫 줄에 늘 따로 적혀 있기 때문에","mis":"K4-2-u6-X20"}],"mis":"K4-2-u6-X20","explanation":["친구 1은 성격을 알면 앞으로 할 행동을 예상할 수 있다고 했어요.","친구 2는 성격은 말과 행동을 보면 안다고 했어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인물의 성격을 알면 인물이 앞으로 어떤 행동을 할지 예상할 수 있어."},{"who":"친구 2","text":"성격은 인물의 말과 행동을 보면 알 수 있지."},{"who":"친구 3","text":"앞 이야기와 뒤에 이어질 이야기가 자연스럽게 연결되려면 어떻게 해야 할까?"},{"who":"친구 4","text":"이야기의 흐름을 생각하며 뒤에 이어질 내용을 상상해 보자."},{"who":"친구 5","text":"앞으로 벌어질 일이 자연스러우려면 사건들 사이의 원인과 결과를 연결 지어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#5','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C26',2,'match','auto','실베스터의 말이나 행동과, 거기서 짐작할 수 있는 성격을 바르게 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u6-C26","difficulty":2,"kind":"match","stem":"실베스터의 말이나 행동과, 거기서 짐작할 수 있는 성격을 바르게 이어 보세요.","pairs":[{"l":"“내, 내가 바, 바, 바위면 좋겠어.”","r":"겁이 많고 쉽게 당황하는 성격"},{"l":"이 세상 모든 사람의 소원을 다 들어줘야지!","r":"가족과 친구들을 사랑하고 좋은 것을 나눌 수 있는 성격"},{"l":"특이한 조약돌을 모으고, 찾아낸 돌을 찬찬히 뜯어봄","r":"호기심이 많은 성격"}],"mis":"K4-2-u6-X23","explanation":["사자 앞에서 말을 더듬은 것은 겁이 나고 당황했기 때문이에요.","모두의 소원을 들어주겠다는 생각에서 나누는 마음이 보여요.","특이한 돌에 마음을 빼앗기는 모습에서 호기심이 보여요."],"asset":{"type":"passage","lines":["말이나 행동 ㉮ ‘엄마, 아빠, 친척이랑 친구들, 아니 이 세상 모든 사람의","소원을 다 들어줘야지!’"],"numbered":false,"title":"「당나귀 실베스터와 요술 조약돌」에서 성격을 짐작할 수 있는 생각 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#6','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C27',2,'blank','auto','「당나귀 실베스터와 요술 조약돌」의 흐름을 정리했어요. ③에 들어갈 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X24']::text[],false,'{"seq":6,"concept":"K4-2-u6-C27","difficulty":2,"kind":"blank","stem":"「당나귀 실베스터와 요술 조약돌」의 흐름을 정리했어요. ③에 들어갈 일로 알맞은 것은 무엇인가요?","options":[{"t":"신나게 집으로 향하던 실베스터는 굶주린 사자를 만났다.","correct":true},{"t":"실베스터는 다시 당나귀가 되었다.","mis":"K4-2-u6-X19"},{"t":"실베스터는 시냇가에서 조약돌을 처음 찾아냈다.","mis":"K4-2-u6-X19"},{"t":"실베스터는 사자와 친구가 되어 함께 놀았다.","mis":"K4-2-u6-X24"}],"explanation":["②에서 소원이 이루어지자 실베스터는 신이 났어요.","집으로 가던 길에 굶주린 사자를 만났어요.","그래서 ④에서 놀라고 당황해 바위가 되었어요."],"asset":{"type":"passage","lines":["① 실베스터는 시냇가에서 놀다가 아주 특이한 조약돌 하나를 찾아냈다.","② 실베스터가 조약돌을 손에 쥐고 비가 그만 왔으면 좋겠다고 하자 진짜 이루어졌다.","③ (                    )","④ 실베스터는 너무 놀라고 당황한 나머지 바위가 되고 싶다고 말했고 정말로 바위가 되었다."],"numbered":false,"title":"이야기의 흐름 정리 — 『국어』 269쪽 3 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#7','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C29',2,'mc','auto','실베스터가 바위가 된 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X22','K4-2-u6-X23']::text[],false,'{"seq":7,"concept":"K4-2-u6-C29","difficulty":2,"kind":"mc","stem":"실베스터가 바위가 된 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"굶주린 사자를 보고 너무 놀라고 당황한 나머지 바위면 좋겠다고 말했기 때문","correct":true},{"t":"조약돌을 땅 위에 내려놓았기 때문","mis":"K4-2-u6-X22"},{"t":"비가 그쳤기 때문","mis":"K4-2-u6-X22"},{"t":"원래 바위가 되고 싶은 꿈이 있었기 때문","mis":"K4-2-u6-X23"}],"explanation":["바로 앞에 실베스터가 사자를 만난 일이 있어요.","놀라고 당황해 「바위면 좋겠어.」라고 말했어요.","조약돌을 쥐고 있었으니 그 말이 그대로 이루어졌어요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#8','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C28',2,'mc','auto','바위가 된 실베스터의 뒤에 이어질 일로, 이야기의 흐름에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X36']::text[],false,'{"seq":8,"concept":"K4-2-u6-C28","difficulty":2,"kind":"mc","stem":"바위가 된 실베스터의 뒤에 이어질 일로, 이야기의 흐름에 가장 알맞은 것은 무엇인가요?","options":[{"t":"실베스터가 다시 당나귀로 돌아갈 방법을 찾게 되는 일","correct":true},{"t":"실베스터가 이웃 마을 학교에 입학하는 일","mis":"K4-2-u6-X24"},{"t":"사자가 숲속의 왕이 되는 일","mis":"K4-2-u6-X24"},{"t":"까닭 없이 하늘에서 당나귀가 떨어지는 일","mis":"K4-2-u6-X36"}],"explanation":["앞 이야기는 실베스터가 바위가 되어 조약돌을 집지 못하는 데서 끝나요.","그러니 다시 당나귀가 될 수 있을지가 이어질 일이에요.","흐름과 상관없는 일은 이어지지 않아요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#9','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C58',2,'mc','auto','작품을 읽고 만든 질문 ㉮~㉱ 가운데, 답이 이야기에 그대로 나와 있는 질문은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":9,"concept":"K4-2-u6-C58","difficulty":2,"kind":"mc","stem":"작품을 읽고 만든 질문 ㉮~㉱ 가운데, 답이 이야기에 그대로 나와 있는 질문은 무엇인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"K4-2-u6-X08"},{"t":"㉰","mis":"K4-2-u6-X08"},{"t":"㉱","mis":"K4-2-u6-X08"}],"explanation":["㉮의 답(바위가 되고 싶다는 소원)은 이야기에 그대로 나와요.","㉯는 인물의 마음을, ㉰·㉱는 앞으로의 일을 짐작해야 해요.","짐작한 것을 이야기에 나온 일처럼 여기지 않아요."],"asset":{"type":"passage","lines":["㉮ 실베스터가 사자와 마주쳤을 때 요술 조약돌을 손에 쥐고 빌었던 소원은 무엇인가요?","㉯ 실베스터가 사라졌을 때 엄마, 아빠는 어떤 마음이었을까요?","㉰ 바위로 변한 실베스터에게 어떤 일이 일어날까요?","㉱ 실베스터의 삶은 앞으로 바뀌게 될까요?"],"numbered":false,"title":"작품을 읽고 만든 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_basic#10','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_basic','lesson_basic','K4-2-u6-C29',3,'essay','teacher','『국어』 270쪽처럼, 원인과 결과를 생각하며 바위가 된 실베스터에게 이어질 이야기를 「원인 → 결과(원인) → 결과」 세 칸으로 상상해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C29","difficulty":3,"kind":"essay","stem":"『국어』 270쪽처럼, 원인과 결과를 생각하며 바위가 된 실베스터에게 이어질 이야기를 「원인 → 결과(원인) → 결과」 세 칸으로 상상해 쓰세요.","answer_guide":{"answer":"예: 원인 — 바위가 된 실베스터는 손이 없어 조약돌을 집을 수 없었다. → 결과(원인) — 실베스터는 바위로 지내며 날마다 다시 당나귀가 되기를 빌었다. → 결과 — 그 소리를 들은 바람이 조약돌을 굴려 실베스터에게 닿게 해 주었다.","scoring_points":["앞 이야기(바위가 되어 조약돌을 집지 못함)에서 시작했는가","앞 칸의 결과가 다음 칸의 원인이 되게 이었는가","세 칸이 자연스럽게 이어지는가"]},"explanation":["앞 이야기의 마지막 일을 원인으로 삼아요.","결과가 다시 원인이 되게 이어요.","「그래서」를 넣어 읽어 말이 되는지 봐요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#1','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C30',2,'mc','auto','친구들의 조언을 따라 실베스터의 뒷이야기를 쓰려고 해요. 가장 알맞게 쓰는 방법은 무엇인가요?',ARRAY['K4-2-u6-X52','K4-2-u6-X25','K4-2-u6-X26']::text[],false,'{"seq":1,"concept":"K4-2-u6-C30","difficulty":2,"kind":"mc","stem":"친구들의 조언을 따라 실베스터의 뒷이야기를 쓰려고 해요. 가장 알맞게 쓰는 방법은 무엇인가요?","options":[{"t":"앞 이야기와 자연스럽게 이어지고 실베스터의 성격과 어울리게 쓴다","correct":true},{"t":"재미있게 하려고 실베스터가 갑자기 우주로 날아가게 쓴다","mis":"K4-2-u6-X52"},{"t":"앞 이야기와 상관없이 쓰고 싶은 이야기를 쓴다","mis":"K4-2-u6-X25"},{"t":"친구가 쓴 뒷이야기와 똑같이 쓴다","mis":"K4-2-u6-X26"}],"explanation":["앞 이야기를 잘 살펴보고 자연스럽게 이어지게 써요.","재미있게 쓰는 것도 좋지만 너무 장난스럽지 않아야 해요.","상상한 이야기가 등장인물의 성격과 잘 어울려야 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"앞 이야기를 잘 살펴보고 자연스럽게 이어지도록 써야 해요."},{"who":"친구 2","text":"이야기를 재미있게 쓰는 것도 좋지만 너무 장난스럽지 않아야 해요."},{"who":"친구 3","text":"이야기의 흐름이 자연스러운지 살펴봐요."},{"who":"친구 4","text":"상상한 이야기가 등장인물의 성격과 잘 어울려야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#2','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C26',2,'mc','auto','‘엄마, 아빠, 친척이랑 친구들, 아니 이 세상 모든 사람의 소원을 다 들어줘야지!’에서 짐작한 성격을 살려 상상한 행동으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X23','K4-2-u6-X36']::text[],false,'{"seq":2,"concept":"K4-2-u6-C26","difficulty":2,"kind":"mc","stem":"‘엄마, 아빠, 친척이랑 친구들, 아니 이 세상 모든 사람의 소원을 다 들어줘야지!’에서 짐작한 성격을 살려 상상한 행동으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다시 당나귀가 되면 요술 조약돌로 엄마, 아빠의 소원부터 들어준다","correct":true},{"t":"조약돌을 혼자만 숨겨 두고 아무에게도 알리지 않는다","mis":"K4-2-u6-X23"},{"t":"엄마, 아빠를 모른 척하고 멀리 떠난다","mis":"K4-2-u6-X23"},{"t":"까닭 없이 사자를 잡으러 간다","mis":"K4-2-u6-X36"}],"explanation":["실베스터는 가족과 친구들을 사랑하는 성격이에요.","좋은 것을 나누고 싶어 했어요.","성격을 알면 앞으로 할 행동을 예상할 수 있어요."],"asset":{"type":"passage","lines":["말이나 행동 ㉮ ‘엄마, 아빠, 친척이랑 친구들, 아니 이 세상 모든 사람의","소원을 다 들어줘야지!’"],"numbered":false,"title":"「당나귀 실베스터와 요술 조약돌」에서 성격을 짐작할 수 있는 생각 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#3','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C31',3,'mc','auto','친구가 바위가 된 실베스터의 뒷이야기로 「실베스터는 다음 날 학교에 가서 친구들과 축구를 했다.」를 썼어요. 이 뒷이야기가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u6-X27','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":3,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"친구가 바위가 된 실베스터의 뒷이야기로 「실베스터는 다음 날 학교에 가서 친구들과 축구를 했다.」를 썼어요. 이 뒷이야기가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"바위가 되어 꼼짝도 못 한다는 앞 이야기와 이어지지 않기 때문","correct":true},{"t":"너무 평범한 일이기 때문","mis":"K4-2-u6-X27"},{"t":"문장이 너무 짧기 때문","mis":"K4-2-u6-X28"},{"t":"놀라운 일이 나오지 않기 때문","mis":"K4-2-u6-X29"}],"explanation":["바위가 된 실베스터는 딸기 언덕에서 꼼짝도 못 했어요.","학교에 가서 축구를 하려면 먼저 당나귀로 돌아와야 해요.","알맞은지는 앞 이야기와 이어지는지로 따져요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#4','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C32',3,'mc','auto','친구들이 쓴 실베스터의 뒷이야기 두 편을 견주어 더 알맞은 쪽을 고르려고 해요. 고르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X29','K4-2-u6-X28','K4-2-u6-X52']::text[],false,'{"seq":4,"concept":"K4-2-u6-C32","difficulty":3,"kind":"mc","stem":"친구들이 쓴 실베스터의 뒷이야기 두 편을 견주어 더 알맞은 쪽을 고르려고 해요. 고르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"인물의 성격, 이야기의 흐름, 원인과 결과가 앞 이야기와 더 자연스럽게 이어지는 쪽","correct":true},{"t":"더 놀랍고 신기한 일이 나오는 쪽","mis":"K4-2-u6-X29"},{"t":"더 길게 쓴 쪽","mis":"K4-2-u6-X28"},{"t":"더 장난스러워서 웃긴 쪽","mis":"K4-2-u6-X52"}],"explanation":["발표를 들을 때 인물의 성격을 생각해요.","이야기의 흐름과 인과 관계가 자연스러운지 봐요.","놀라움이나 길이는 기준이 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"앞 이야기를 잘 살펴보고 자연스럽게 이어지도록 써야 해요."},{"who":"친구 2","text":"이야기를 재미있게 쓰는 것도 좋지만 너무 장난스럽지 않아야 해요."},{"who":"친구 3","text":"이야기의 흐름이 자연스러운지 살펴봐요."},{"who":"친구 4","text":"상상한 이야기가 등장인물의 성격과 잘 어울려야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#5','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C30',3,'ox','auto','이어질 내용에는 정답이 하나 있어서, 『국어』 270쪽 예시와 다르게 상상하면 틀린 거예요.',ARRAY['K4-2-u6-X26']::text[],false,'{"seq":5,"concept":"K4-2-u6-C30","difficulty":3,"kind":"ox","stem":"이어질 내용에는 정답이 하나 있어서, 『국어』 270쪽 예시와 다르게 상상하면 틀린 거예요.","answer":"X","reason_options":[{"t":"정답은 없지만 인물의 성격, 이야기의 흐름, 원인과 결과에 어울리면 다르게 상상해도 되기 때문에","correct":true},{"t":"교과서 예시가 이어질 내용의 정답이기 때문에","mis":"K4-2-u6-X26"}],"mis":"K4-2-u6-X26","explanation":["이어질 내용은 사람마다 다르게 상상할 수 있어요.","다만 아무렇게나가 아니라 앞 이야기와 이어져야 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 실베스터는 바위로 변해 버려 조약돌을 다시 집을 수 없게 되었다.","② 조약돌을 집을 수 없게 된 실베스터는 바위로 살게 되었다.","③ 물, 흙, 바람, 나무는 실베스터의 사정을 듣고 도와주기로 했다.","④ 물, 흙, 바람, 나무는 서로 합심해 실베스터 쪽으로 조약돌을 옮겨 주었다.","⑤ 마침내 조약돌이 닿아 실베스터는 다시 소원을 빌어 당나귀로 변했다."],"numbered":false,"title":"원인과 결과를 생각하며 상상한 이어질 이야기 — 『국어』 270쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#6','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C29',3,'mc','auto','『국어』 270쪽 예시에서 ②와 ③은 어떤 관계인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X35','K4-2-u6-X02']::text[],false,'{"seq":6,"concept":"K4-2-u6-C29","difficulty":3,"kind":"mc","stem":"『국어』 270쪽 예시에서 ②와 ③은 어떤 관계인가요?","options":[{"t":"②가 원인이 되어 ③이 일어났다","correct":true},{"t":"③이 원인이 되어 ②가 일어났다","mis":"K4-2-u6-X01"},{"t":"②와 ③은 서로 아무 관계가 없다","mis":"K4-2-u6-X35"},{"t":"②는 결과일 뿐이라서 원인이 될 수 없다","mis":"K4-2-u6-X02"}],"explanation":["②는 ①의 결과예요(바위로 살게 됨).","바위로 사는 실베스터의 사정을 듣고 ③의 일이 생겼어요.","그래서 ②는 결과이면서 ③의 원인이에요."],"asset":{"type":"passage","lines":["① 실베스터는 바위로 변해 버려 조약돌을 다시 집을 수 없게 되었다.","② 조약돌을 집을 수 없게 된 실베스터는 바위로 살게 되었다.","③ 물, 흙, 바람, 나무는 실베스터의 사정을 듣고 도와주기로 했다.","④ 물, 흙, 바람, 나무는 서로 합심해 실베스터 쪽으로 조약돌을 옮겨 주었다.","⑤ 마침내 조약돌이 닿아 실베스터는 다시 소원을 빌어 당나귀로 변했다."],"numbered":false,"title":"원인과 결과를 생각하며 상상한 이어질 이야기 — 『국어』 270쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#7','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C58',3,'mc','auto','「당나귀 실베스터와 요술 조약돌」의 원래 이야기 끝과 『국어』 270쪽에서 상상한 이야기를 비교했어요. 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X26','K4-2-u6-X48','K4-2-u6-X29']::text[],false,'{"seq":7,"concept":"K4-2-u6-C58","difficulty":3,"kind":"mc","stem":"「당나귀 실베스터와 요술 조약돌」의 원래 이야기 끝과 『국어』 270쪽에서 상상한 이야기를 비교했어요. 알맞게 말한 것은 무엇인가요?","options":[{"t":"실베스터를 돕는 인물은 다르지만, 두 이야기 모두 요술 조약돌 덕분에 실베스터가 다시 당나귀가 된다","correct":true},{"t":"원래 이야기와 다르게 상상했으니 상상한 이야기는 틀렸다","mis":"K4-2-u6-X26"},{"t":"원래 이야기에는 원인과 결과가 나오지 않는다","mis":"K4-2-u6-X48"},{"t":"상상한 이야기가 원래 이야기보다 놀랍지 않으니 고쳐야 한다","mis":"K4-2-u6-X29"}],"explanation":["원래 이야기에서는 엄마, 아빠가 조약돌을 발견했어요.","상상한 이야기에서는 물, 흙, 바람, 나무가 조약돌을 옮겨 주었어요.","돕는 인물은 달라도 두 이야기 모두 원인과 결과가 이어져요."],"asset":{"type":"passage","lines":["(간추림) 봄이 오자 실베스터를 그리워하던 엄마, 아빠가 딸기 언덕으로 소풍을 갔다.","(간추림) 바위가 된 실베스터 위에 소풍 자리를 마련하다가 그 곁에서 요술 조약돌을 발견했다.","(간추림) 조약돌을 보며 실베스터를 생각하던 엄마, 아빠 덕분에 실베스터는 다시 당나귀가 되었다."],"title":"「당나귀 실베스터와 요술 조약돌」 원래 이야기의 끝 (『국어활동』 90~99쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#8','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C26',4,'essay','teacher','실베스터의 성격 하나를 골라 그렇게 짐작한 말이나 행동을 쓰고, 그 성격을 살려 실베스터가 다시 당나귀가 된 뒤에 할 행동을 상상해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C26","difficulty":4,"kind":"essay","stem":"실베스터의 성격 하나를 골라 그렇게 짐작한 말이나 행동을 쓰고, 그 성격을 살려 실베스터가 다시 당나귀가 된 뒤에 할 행동을 상상해 쓰세요.","answer_guide":{"answer":"예: 성격 — 가족과 친구들을 사랑하고 좋은 것을 나눌 줄 안다. 근거 — 조약돌을 얻자 엄마, 아빠, 친척이랑 친구들, 세상 모든 사람의 소원을 들어주겠다고 생각했다. 할 행동 — 다시 당나귀가 된 실베스터는 엄마, 아빠를 꼭 안고, 조약돌로 이웃들이 바라는 일을 하나씩 이루어 준다.","scoring_points":["성격을 하나 골라 썼는가","그 성격을 짐작한 말이나 행동을 근거로 썼는가","성격에 어울리는 행동을 상상해 썼는가"]},"explanation":["성격은 인물의 말과 행동에서 찾아요.","그 성격이라면 어떻게 할지 생각해요.","성격과 어울리게 상상해요."],"asset":{"type":"passage","lines":["말이나 행동 ㉮ ‘엄마, 아빠, 친척이랑 친구들, 아니 이 세상 모든 사람의","소원을 다 들어줘야지!’"],"numbered":false,"title":"「당나귀 실베스터와 요술 조약돌」에서 성격을 짐작할 수 있는 생각 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#9','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C30',4,'essay','teacher','『국어』 271쪽 4번처럼, 인물의 성격·이야기의 흐름·원인과 결과를 생각하며 「당나귀 실베스터와 요술 조약돌」의 뒷이야기를 쓰세요. 바위가 된 실베스터가 다시 당나귀가 되는 까닭이 드러나야 해요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C30","difficulty":4,"kind":"essay","stem":"『국어』 271쪽 4번처럼, 인물의 성격·이야기의 흐름·원인과 결과를 생각하며 「당나귀 실베스터와 요술 조약돌」의 뒷이야기를 쓰세요. 바위가 된 실베스터가 다시 당나귀가 되는 까닭이 드러나야 해요.","answer_guide":{"answer":"예: 다시 당나귀가 되려면 조약돌이 몸에 닿은 채 소원을 말해야 하는데, 바위가 된 실베스터는 조약돌을 집을 수 없었다. 실베스터는 포기하지 않고 계속 빌다가 물, 흙, 바람, 나무와 이야기할 수 있게 되었다. 사정을 들은 물과 흙, 바람, 나무가 힘을 모아 조약돌을 실베스터에게 옮겨 주었고, 실베스터는 다시 소원을 빌어 당나귀가 되었다.","scoring_points":["앞 이야기(조약돌을 집지 못함)와 자연스럽게 이어지는가","다시 당나귀가 되는 까닭(조약돌이 몸에 닿음)이 드러나는가","너무 장난스럽지 않고 인물의 성격과 어울리는가"]},"explanation":["요술은 돌이 몸에 닿아야 일어난다는 것을 떠올려요.","그 조건을 어떻게 이룰지 원인과 결과로 이어요.","다 쓰면 흐름이 자연스러운지 살펴봐요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L06_challenge#10','kor',4,2,'u6','L06','tb_g4_2_kor_u6_L06_challenge','lesson_challenge','K4-2-u6-C29',4,'essay','teacher','『국어활동』 89쪽 2번처럼 「두근두근」의 이어질 내용을 상상해 쓰세요. 브레드 씨를 찾아온 동물의 고민을 정하고, 브레드 씨의 빵이 그 고민을 어떻게 해결하는지 원인과 결과가 드러나게 쓰세요. (89쪽 예시 답안의 양 말고 다른 동물로)','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C29","difficulty":4,"kind":"essay","stem":"『국어활동』 89쪽 2번처럼 「두근두근」의 이어질 내용을 상상해 쓰세요. 브레드 씨를 찾아온 동물의 고민을 정하고, 브레드 씨의 빵이 그 고민을 어떻게 해결하는지 원인과 결과가 드러나게 쓰세요. (89쪽 예시 답안의 양 말고 다른 동물로)","answer_guide":{"answer":"예: 어느 날 밤, 다람쥐가 문을 두드렸어요. 「겨울잠을 자야 하는데 배가 고파서 잠이 안 와요.」 브레드 씨는 부끄러워 말은 잘 못했지만 도토리를 넣은 빵을 구워 주었어요. 배가 든든해진 다람쥐는 겨울잠을 푹 잘 수 있었고, 봄이 되자 브레드 씨에게 고맙다며 꽃을 가져왔어요.","scoring_points":["찾아온 동물의 고민을 썼는가","빵이 고민을 해결하는 과정을 원인과 결과로 이었는가","부끄러움을 많이 타고 빵을 잘 만드는 브레드 씨와 어울리는가"]},"explanation":["동물들의 고민을 먼저 생각해요.","브레드 씨의 빵이 그 고민을 어떻게 풀지 상상해요.","브레드 씨의 성격과 어울리게 써요."],"asset":{"type":"passage","lines":["(간추림) 「두근두근」의 브레드 씨는 부끄러움을 많이 타는 소심한 사람이다.","(간추림) 하지만 브레드 씨는 빵을 맛깔스럽게 만들 수 있다.","(간추림) 빵 만드는 실력 때문에 브레드 씨는 여러 동물을 만나 빵을 나누게 된다."],"title":"『국어활동』 84~88쪽 「두근두근」 인물과 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#1','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C59',1,'sa','auto','「랑랑별 때때롱」에서 때때롱이 새달이네 호박을 몰래 따고 돌담 위에 얹어 놓고 간 것은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u6-C59","difficulty":1,"kind":"sa","stem":"「랑랑별 때때롱」에서 때때롱이 새달이네 호박을 몰래 따고 돌담 위에 얹어 놓고 간 것은 무엇인지 쓰세요.","answer":["랑랑별 호박씨 다섯 개","호박씨 다섯 개","호박씨","랑랑별 호박씨"],"explanation":["이튿날 아침 새달이는 돌담에 가서 살펴보았어요.","종이 봉지 안에 예쁜 호박씨 다섯 개가 들어 있었어요.","때때롱이 호박 대신 놓고 간 것이에요."],"asset":{"type":"passage","lines":["(간추림) 그날 밤, 때때롱이 새달이네 호박을 따다가 호박죽을 끓여 먹었다고 했다.","(간추림) 새달이는 화가 나고 기가 막혔다.","(간추림) 때때롱은 화내지 말라며, 대신 돌담 위에 호박씨를 놓고 왔으니 내년에 심어 보라고 했다.","(간추림) 이튿날 아침 돌담 위 종이 봉지에 예쁜 호박씨 다섯 개가 들어 있었다."],"title":"「랑랑별 때때롱」 — 『국어』 273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#2','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C60',1,'mc','auto','「가지거나 차지하고 싶은 마음이 생기다.」라는 뜻을 가진 표현은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":2,"concept":"K4-2-u6-C60","difficulty":1,"kind":"mc","stem":"「가지거나 차지하고 싶은 마음이 생기다.」라는 뜻을 가진 표현은 무엇인가요?","options":[{"t":"탐이 나다","correct":true},{"t":"혀를 차다","mis":"K4-2-u6-X53"},{"t":"어이가 없다","mis":"K4-2-u6-X53"}],"explanation":["엄마는 누가 탐이 나서 호박을 훔쳐 간 것 같다고 했어요.","갖고 싶은 마음이 생길 때 「탐이 나다」라고 해요.","보기의 뜻 ㉮와 이어 보아요."],"asset":{"type":"passage","lines":["보기: 어이가 없다 · 탐이 나다 · 혀를 차다","㉮ 가지거나 차지하고 싶은 마음이 생기다.","㉯ 마음이 언짢거나 불만스러움을 나타내다.","㉰ 일이 너무 뜻밖이어서 기가 막히는 듯하다."],"numbered":false,"title":"낱말 알기 — 『국어』 277쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#3','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C59',1,'mc','auto','호박이 없어진 것을 알았을 때 엄마의 마음으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":3,"concept":"K4-2-u6-C59","difficulty":1,"kind":"mc","stem":"호박이 없어진 것을 알았을 때 엄마의 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"몹시 서운하고 아까웠다","correct":true},{"t":"무척 기쁘고 신이 났다","mis":"K4-2-u6-X08"},{"t":"조금도 아깝지 않았다","mis":"K4-2-u6-X08"},{"t":"호박이 없어진 줄 몰랐다","mis":"K4-2-u6-X08"}],"explanation":["엄마는 호박이 없어진 것을 무척 아까워했어요.","혀를 끌끌 차면서 몹시 서운한 눈치였어요.","인물의 말과 행동에서 마음을 알 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 엄마가 돌담 위 호박 넝쿨을 살피다가 호박이 없어진 것을 알았다.","(간추림) 씨호박 하려던 호박이었는데, 아빠도 새달이도 마달이도 몰랐다.","(간추림) 엄마는 누가 탐이 나서 훔쳐 간 것 같다며 아까워했다.","엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다."],"title":"「랑랑별 때때롱」 — 『국어』 272~273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#4','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C37',1,'mc','auto','『국어』 278쪽에서 정리한 새달이의 성격은 무엇인가요?',ARRAY['K4-2-u6-X23']::text[],false,'{"seq":4,"concept":"K4-2-u6-C37","difficulty":1,"kind":"mc","stem":"『국어』 278쪽에서 정리한 새달이의 성격은 무엇인가요?","options":[{"t":"궁금한 것을 참지 못한다","correct":true},{"t":"장난치는 것을 좋아한다","mis":"K4-2-u6-X23"},{"t":"부끄러움을 많이 탄다","mis":"K4-2-u6-X23"},{"t":"겁이 많고 쉽게 당황한다","mis":"K4-2-u6-X23"}],"explanation":["새달이는 때때롱에게 호박을 어떻게 따 갔는지 물었어요.","높은 하늘에서 무얼로 어떻게 따 갔는지 알고 싶어 했어요.","이런 말에서 궁금한 것을 참지 못하는 성격을 알 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#5','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C59',2,'mc','auto','때때롱이 호박을 몰래 따 갔다는 말을 들었을 때 새달이의 마음은 어떻게 바뀌었나요?',ARRAY['K4-2-u6-X08','K4-2-u6-X19']::text[],false,'{"seq":5,"concept":"K4-2-u6-C59","difficulty":2,"kind":"mc","stem":"때때롱이 호박을 몰래 따 갔다는 말을 들었을 때 새달이의 마음은 어떻게 바뀌었나요?","options":[{"t":"처음에는 몹시 화가 났지만 대화를 나누면서 궁금해졌다","correct":true},{"t":"처음부터 끝까지 기뻤다","mis":"K4-2-u6-X08"},{"t":"처음에는 궁금했지만 나중에 몹시 화가 났다","mis":"K4-2-u6-X19"},{"t":"처음부터 끝까지 무서웠다","mis":"K4-2-u6-X08"}],"explanation":["새달이는 처음에 화도 나고 어이가 없었어요.","나중에는 호박을 어떻게 따 갔는지 알고 싶어 때때롱을 기다렸어요.","마음이 바뀐 차례를 이야기에서 찾아요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#6','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C60',2,'mc','auto','「엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다.」에서 「혀를 차다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":6,"concept":"K4-2-u6-C60","difficulty":2,"kind":"mc","stem":"「엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다.」에서 「혀를 차다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"마음이 언짢거나 불만스러움을 나타내다","correct":true},{"t":"가지거나 차지하고 싶은 마음이 생기다","mis":"K4-2-u6-X53"},{"t":"일이 너무 뜻밖이어서 기가 막히는 듯하다","mis":"K4-2-u6-X53"},{"t":"맛있는 것을 먹고 기분이 좋아지다","mis":"K4-2-u6-X53"}],"explanation":["엄마는 씨호박 하려던 호박이 없어져 서운했어요.","그 언짢은 마음을 혀를 차는 것으로 나타냈어요.","표현이 쓰인 문장에 뜻을 넣어 읽어 봐요."],"asset":{"type":"passage","lines":["(간추림) 엄마가 돌담 위 호박 넝쿨을 살피다가 호박이 없어진 것을 알았다.","(간추림) 씨호박 하려던 호박이었는데, 아빠도 새달이도 마달이도 몰랐다.","(간추림) 엄마는 누가 탐이 나서 훔쳐 간 것 같다며 아까워했다.","엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다."],"title":"「랑랑별 때때롱」 — 『국어』 272~273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#7','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C59',2,'mc','auto','새달이가 엄마에게 때때롱 얘기를 하지 못한 까닭은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":7,"concept":"K4-2-u6-C59","difficulty":2,"kind":"mc","stem":"새달이가 엄마에게 때때롱 얘기를 하지 못한 까닭은 무엇인가요?","options":[{"t":"엄마가 곧이들어 주지 않을 것이라고 생각했기 때문","correct":true},{"t":"때때롱이 비밀로 하라고 했기 때문","mis":"K4-2-u6-X08"},{"t":"호박씨를 혼자 숨기고 싶었기 때문","mis":"K4-2-u6-X08"},{"t":"때때롱의 이름을 잊어버렸기 때문","mis":"K4-2-u6-X08"}],"explanation":["「곧이듣다」는 남의 말을 듣고 그대로 믿는다는 뜻이에요.","새달이는 엄마가 랑랑별 이야기를 믿지 않을 것 같았어요.","그래서 친구 애가 따 갔다고만 말했어요."],"asset":{"type":"passage","lines":["(간추림) 새달이가 호박씨를 보여 주자 엄마는 그 애가 양심이 있다고 했다.","(간추림) 새달이는 엄마가 곧이들어 주지 않을 것 같아 때때롱 얘기는 하지 못했다.","그렇게 하고 말았지만 새달이는 마음이 찜찜했습니다.","(간추림) 그날 밤 아무리 불러도 때때롱과 매매롱은 대답이 없었다."],"title":"「랑랑별 때때롱」 — 『국어』 274~275쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#8','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C33',2,'mc','auto','『국어』 278쪽처럼 이야기의 흐름을 정리했어요. ⑤ 다음에 이어질 내용을 상상할 때 가장 먼저 붙잡을 것은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X05']::text[],false,'{"seq":8,"concept":"K4-2-u6-C33","difficulty":2,"kind":"mc","stem":"『국어』 278쪽처럼 이야기의 흐름을 정리했어요. ⑤ 다음에 이어질 내용을 상상할 때 가장 먼저 붙잡을 것은 무엇인가요?","options":[{"t":"때때롱이 준 호박씨를 내년에 심기로 했고, 때때롱이 「심어 보면 알 거야.」라고 한 일","correct":true},{"t":"새달이가 학교에서 벌을 선 일만","mis":"K4-2-u6-X24"},{"t":"호박죽이 맛있었다는 때때롱의 말만","mis":"K4-2-u6-X24"},{"t":"이야기와 상관없이 가장 놀라운 일을 새로 떠올리는 것","mis":"K4-2-u6-X05"}],"explanation":["이야기는 호박씨를 내년에 심기로 한 데까지 왔어요.","때때롱은 호박씨를 심어 보면 알 거라고 했어요.","끊긴 대목에서 흐름을 이어 상상해요."],"asset":{"type":"passage","lines":["① 한밤중에 랑랑별 때때롱이 새달이네 호박을 몰래 따 갔다.","② 다음 날 아침, 새달이네 집에서는 호박이 없어진 것을 알고 깜짝 놀랐다.","③ 그날 밤, 때때롱이 호박을 따서 호박죽을 만들어 먹었다고 새달이에게 말했다.","④ 새달이네 집에서는 호박씨를 잘 갈무리해 두었다가 내년에 심기로 했다.","⑤ 새달이는 때때롱이 어떻게 기다란 집게로 호박을 따 갔는지 물었다."],"numbered":false,"title":"이야기의 흐름 정리 — 『국어』 278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#9','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C36',2,'mc','auto','두 친구가 「랑랑별 때때롱」의 이어질 내용을 서로 다르게 상상했어요. 그 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X26','K4-2-u6-X31','K4-2-u6-X29']::text[],false,'{"seq":9,"concept":"K4-2-u6-C36","difficulty":2,"kind":"mc","stem":"두 친구가 「랑랑별 때때롱」의 이어질 내용을 서로 다르게 상상했어요. 그 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 인물의 성격을 이용해 상상했기 때문","correct":true},{"t":"한 친구가 이야기를 잘못 읽었기 때문","mis":"K4-2-u6-X26"},{"t":"누구를 따라가도 이어질 내용은 같아야 하기 때문","mis":"K4-2-u6-X31"},{"t":"더 놀라운 쪽이 정답이기 때문","mis":"K4-2-u6-X29"}],"explanation":["친구 1은 엉뚱하지만 착한 때때롱의 성격을 이용했어요.","친구 2는 쉽게 화를 내는 새달이의 성격을 이용했어요.","누구를 따라가느냐에 따라 이어질 내용이 달라져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"때때롱은 가끔 이해하지 못할 엉뚱한 행동을 하지만 마음은 착하니까, 호박씨를 심으면 아주 맛있는 호박이 주렁주렁 열릴 것 같아."},{"who":"친구 2","text":"새달이는 때때롱의 행동을 이해할 수 없을 때마다 쉽게 화를 냈어. 이번에도 거짓말이라고 생각하고 호박씨를 그냥 버릴 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_basic#10','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_basic','lesson_basic','K4-2-u6-C39',3,'essay','teacher','『국어』 279쪽 3번처럼, 새달이가 때때롱이 준 호박씨를 심은 뒤의 일을 원인과 결과가 이어지게 세 단계로 상상해 쓰세요. (교과서 예시의 포도 맛 말고 다른 내용으로)','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C39","difficulty":3,"kind":"essay","stem":"『국어』 279쪽 3번처럼, 새달이가 때때롱이 준 호박씨를 심은 뒤의 일을 원인과 결과가 이어지게 세 단계로 상상해 쓰세요. (교과서 예시의 포도 맛 말고 다른 내용으로)","answer_guide":{"answer":"예: 새달이는 호박씨를 텃밭에 심었다. → 싹이 나자 새달이는 궁금해서 날마다 텃밭에 나가 살펴보았다. → 그래서 호박이 열린 첫날 바로 찾아냈고, 호박 속에서 때때롱이 보낸 쪽지를 발견했다.","scoring_points":["호박씨를 심은 일에서 시작했는가","앞 단계의 결과가 다음 단계의 원인이 되게 이었는가","인물의 성격과 이야기의 흐름에 어울리는가"]},"explanation":["흐름을 정리한 끝에서 시작해요.","원인과 결과가 자연스럽게 이어지게 써요.","인물의 성격을 살리면 더 그럴듯해요."],"asset":{"type":"passage","lines":["원인 새달이는 랑랑별 때때롱이 준 호박씨를 심었다.","결과 땅속의 호박씨는 무럭무럭 자랐다.","결과 수많은 호박이 주렁주렁 열렸다.","결과 새달이가 호박을 따서 반을 갈랐다.","결과 그 호박은 새달이가 좋아하는 포도 맛이었다.","(결과는 다시 다음 일의 원인이 된다.)"],"numbered":false,"title":"원인과 결과를 생각하며 상상한 이어질 내용 — 『국어』 279쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#1','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C60',2,'blank','auto','「일이 너무 뜻밖이어서 기가 막히는 듯하다.」라는 뜻의 표현을 넣어 문장을 완성하려고 해요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#2','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C41',2,'mc','auto','「랑랑별 때때롱」의 뒷이야기를 쓰면서 스스로 물어볼 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X06','K4-2-u6-X52','K4-2-u6-X26']::text[],false,'{"seq":2,"concept":"K4-2-u6-C41","difficulty":2,"kind":"mc","stem":"「랑랑별 때때롱」의 뒷이야기를 쓰면서 스스로 물어볼 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“이 인물이 이렇게 할 까닭이 앞 이야기에 있나?”","correct":true},{"t":"“어떻게 하면 가장 길게 쓸까?”","mis":"K4-2-u6-X06"},{"t":"“무엇을 쓰면 가장 웃길까?”","mis":"K4-2-u6-X52"},{"t":"“친구와 똑같이 썼나?”","mis":"K4-2-u6-X26"}],"explanation":["뒷이야기는 앞 이야기에서 이어져야 해요.","인물이 그렇게 할 까닭이 앞에 있는지 살펴요.","까닭이 없으면 먼저 까닭을 만들어 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#3','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C37',3,'mc','auto','친구 2는 새달이의 어떤 성격을 이용해 이어질 내용을 상상했나요?',ARRAY['K4-2-u6-X23']::text[],false,'{"seq":3,"concept":"K4-2-u6-C37","difficulty":3,"kind":"mc","stem":"친구 2는 새달이의 어떤 성격을 이용해 이어질 내용을 상상했나요?","options":[{"t":"때때롱의 행동을 이해할 수 없을 때마다 쉽게 화를 내는 성격","correct":true},{"t":"장난치는 것을 좋아하는 성격","mis":"K4-2-u6-X23"},{"t":"부끄러움을 많이 타는 성격","mis":"K4-2-u6-X23"},{"t":"무엇이든 남과 나누기를 좋아하는 성격","mis":"K4-2-u6-X23"}],"explanation":["새달이는 호박을 따 간 때때롱에게 도둑이라며 화를 냈어요.","때때롱의 생김새까지 나쁘게 짐작하며 또 화를 냈어요.","친구 2는 이런 성격 때문에 호박씨를 버릴 것이라고 상상했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"때때롱은 가끔 이해하지 못할 엉뚱한 행동을 하지만 마음은 착하니까, 호박씨를 심으면 아주 맛있는 호박이 주렁주렁 열릴 것 같아."},{"who":"친구 2","text":"새달이는 때때롱의 행동을 이해할 수 없을 때마다 쉽게 화를 냈어. 이번에도 거짓말이라고 생각하고 호박씨를 그냥 버릴 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#4','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C59',3,'error','auto','「랑랑별 때때롱」의 인물을 두고 친구들이 한 말이에요. 이야기에 나오지 않은 것을 짐작으로 덧붙여 알맞지 않게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X20']::text[],false,'{"seq":4,"concept":"K4-2-u6-C59","difficulty":3,"kind":"error","stem":"「랑랑별 때때롱」의 인물을 두고 친구들이 한 말이에요. 이야기에 나오지 않은 것을 짐작으로 덧붙여 알맞지 않게 말한 것은 무엇인가요?","options":[{"t":"“새달이가 때때롱이 늑대처럼 무섭게 생겼을 거라고 했으니 때때롱은 정말 무섭게 생겼어.”","correct":true,"mis_target":"K4-2-u6-X08"},{"t":"“새달이가 높은 하늘에서 무얼로 어떻게 따 갔는지 물은 것을 보면 궁금한 것을 참지 못하는 성격이야.”","mis":"K4-2-u6-X20"},{"t":"“때때롱이 기다란 집게로 뚝 따 왔다고 한 것을 보면 장난치는 것을 좋아하는 성격이야.”","mis":"K4-2-u6-X20"}],"explanation":["무섭게 생겼을 거라는 말은 화가 난 새달이의 짐작일 뿐이에요.","때때롱은 「우린 절대 나쁜 짓 안 한다.」라고 했어요.","성격은 인물이 한 말과 행동을 근거로 짐작해요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#5','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C39',3,'mc','auto','친구들이 쓴 「랑랑별 때때롱」의 이어질 이야기 가운데 가장 재미있는 이야기를 고르려고 해요. 고르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X28','K4-2-u6-X29','K4-2-u6-X52']::text[],false,'{"seq":5,"concept":"K4-2-u6-C39","difficulty":3,"kind":"mc","stem":"친구들이 쓴 「랑랑별 때때롱」의 이어질 이야기 가운데 가장 재미있는 이야기를 고르려고 해요. 고르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"인물의 성격에 알맞고, 이야기의 흐름과 인과 관계에 어울리는가","correct":true},{"t":"가장 길게 쓴 이야기인가","mis":"K4-2-u6-X28"},{"t":"가장 놀라운 일이 일어나는가","mis":"K4-2-u6-X29"},{"t":"가장 장난스러워서 웃긴가","mis":"K4-2-u6-X52"}],"explanation":["인물의 성격에 적절한지 생각해요.","이야기의 흐름과 인과 관계에 적당한지 생각해요.","그 가운데 가장 재미있는 이야기를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#6','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C40',3,'mc','auto','뒷이야기에서 쉽게 화를 내던 새달이가 때때롱을 갑자기 무척 믿게 된다면, 무엇을 함께 써야 할까요?',ARRAY['K4-2-u6-X32','K4-2-u6-X20','K4-2-u6-X52']::text[],false,'{"seq":6,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"뒷이야기에서 쉽게 화를 내던 새달이가 때때롱을 갑자기 무척 믿게 된다면, 무엇을 함께 써야 할까요?","options":[{"t":"새달이의 마음이 왜 바뀌었는지 그 까닭","correct":true},{"t":"아무것도 더 쓰지 않아도 된다","mis":"K4-2-u6-X32"},{"t":"새달이의 키와 생김새","mis":"K4-2-u6-X20"},{"t":"때때롱이 더 장난스럽게 행동한 일","mis":"K4-2-u6-X52"}],"explanation":["인물이 앞과 다르게 움직이면 읽는 사람이 어리둥절해요.","마음이 바뀐 까닭을 함께 써야 이어져요.","까닭이 앞에 있어야 자연스러운 이야기가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#7','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C39',3,'ox','auto','뒷이야기는 상상이니까 호박씨가 갑자기 폭발해 마을이 모두 사라지는 것처럼 아무리 황당한 이야기라도 괜찮아요.',ARRAY['K4-2-u6-X52']::text[],false,'{"seq":7,"concept":"K4-2-u6-C39","difficulty":3,"kind":"ox","stem":"뒷이야기는 상상이니까 호박씨가 갑자기 폭발해 마을이 모두 사라지는 것처럼 아무리 황당한 이야기라도 괜찮아요.","answer":"X","reason_options":[{"t":"상상은 자유롭지만 인물의 성격, 이야기의 흐름, 원인과 결과에 어울려야 하기 때문에","correct":true},{"t":"상상한 이야기는 장난스럽고 황당할수록 좋은 이야기이기 때문에","mis":"K4-2-u6-X52"}],"mis":"K4-2-u6-X52","explanation":["때때롱은 호박씨를 심어 보면 알 거라며 나쁜 짓은 안 한다고 했어요.","까닭 없이 황당한 일은 앞 이야기와 이어지지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#8','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C37',4,'essay','teacher','때때롱이나 새달이 가운데 한 인물을 골라, 그 인물의 성격과 그렇게 짐작한 말이나 행동을 쓰고, 그 성격을 이용해 이어질 내용을 상상해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C37","difficulty":4,"kind":"essay","stem":"때때롱이나 새달이 가운데 한 인물을 골라, 그 인물의 성격과 그렇게 짐작한 말이나 행동을 쓰고, 그 성격을 이용해 이어질 내용을 상상해 쓰세요.","answer_guide":{"answer":"예: 인물 — 때때롱. 성격 — 장난치는 것을 좋아하지만 마음은 착하다. 근거 — 「기다란 기다란 집게로 뚝 따 가지고 왔지.」라고 장난스럽게 말하면서도 대신 호박씨를 놓고 갔다. 이어질 내용 — 이듬해 새달이가 호박씨를 심자 큰 호박이 열렸고, 호박 속에서 「놀랐지?」라고 쓴 때때롱의 쪽지가 나왔다.","scoring_points":["인물의 성격을 썼는가","성격의 근거가 된 말이나 행동을 썼는가","그 성격을 이용해 이어질 내용을 상상했는가"]},"explanation":["성격은 인물의 말과 행동에서 찾아요.","그 성격이라면 어떻게 할지 생각해요.","누구의 성격을 이용하느냐에 따라 이야기가 달라져요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#9','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C33',4,'essay','teacher','『국어』 280쪽 「글쓰기」처럼, 때때롱이 놓고 간 호박씨를 심었을 때 새달이에게 어떤 일이 벌어질지 상상하며 「랑랑별 때때롱」의 이어질 내용을 글로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C33","difficulty":4,"kind":"essay","stem":"『국어』 280쪽 「글쓰기」처럼, 때때롱이 놓고 간 호박씨를 심었을 때 새달이에게 어떤 일이 벌어질지 상상하며 「랑랑별 때때롱」의 이어질 내용을 글로 쓰세요.","answer_guide":{"answer":"예: 새달이는 때때롱이 준 호박씨를 텃밭에 심었다. 땅속의 호박씨는 무럭무럭 자라 수많은 호박이 주렁주렁 열렸다. 새달이가 호박을 따서 반을 갈랐더니 새달이가 좋아하는 맛이 났고, 가족들이 딴 호박도 모두 저마다 좋아하는 맛이었다. 새달이네 가족은 이웃들에게도 호박을 나누어 주었고, 새달이는 하늘을 보며 「때때롱아, 고마워!」라고 외쳤다.","scoring_points":["호박씨를 심은 뒤의 일을 상상해 썼는가","인물의 성격과 이야기의 흐름에 어울리는가","사건 사이의 원인과 결과가 자연스럽게 이어지는가"]},"explanation":["앞 이야기의 흐름을 떠올려요.","인물의 성격을 생각하며 상상해요.","사건 사이의 원인과 결과가 자연스러운지 살펴요."],"asset":{"type":"passage","lines":["① 한밤중에 랑랑별 때때롱이 새달이네 호박을 몰래 따 갔다.","② 다음 날 아침, 새달이네 집에서는 호박이 없어진 것을 알고 깜짝 놀랐다.","③ 그날 밤, 때때롱이 호박을 따서 호박죽을 만들어 먹었다고 새달이에게 말했다.","④ 새달이네 집에서는 호박씨를 잘 갈무리해 두었다가 내년에 심기로 했다.","⑤ 새달이는 때때롱이 어떻게 기다란 집게로 호박을 따 갔는지 물었다."],"numbered":false,"title":"이야기의 흐름 정리 — 『국어』 278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L08_challenge#10','kor',4,2,'u6','L08','tb_g4_2_kor_u6_L08_challenge','lesson_challenge','K4-2-u6-C39',4,'essay','teacher','친구가 쓴 이어질 이야기 「새달이가 호박을 따서 반을 갈랐더니 새달이가 좋아하는 포도 맛이었다.」를 읽고, 인물의 성격·이야기의 흐름·원인과 결과의 세 가지 면에서 친구에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C39","difficulty":4,"kind":"essay","stem":"친구가 쓴 이어질 이야기 「새달이가 호박을 따서 반을 갈랐더니 새달이가 좋아하는 포도 맛이었다.」를 읽고, 인물의 성격·이야기의 흐름·원인과 결과의 세 가지 면에서 친구에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 이야기의 흐름 — 때때롱이 「심어 보면 알 거야.」라고 한 말과 잘 이어져. 원인과 결과 — 호박씨를 심어서 호박이 열리고, 그 호박을 갈라 맛을 보는 차례가 자연스러워. 인물의 성격 — 장난치기 좋아하지만 착한 때때롱이 준 선물답게 특별한 맛이 나는 점이 잘 어울려.","scoring_points":["이야기의 흐름 면에서 말했는가","원인과 결과 면에서 말했는가","인물의 성격 면에서 말했는가"]},"explanation":["친구의 발표를 들을 때 세 가지를 생각하며 들어요.","잘된 점을 근거와 함께 말해요.","비슷한 점과 다른 점도 견주어 볼 수 있어요."],"asset":{"type":"passage","lines":["원인 새달이는 랑랑별 때때롱이 준 호박씨를 심었다.","결과 땅속의 호박씨는 무럭무럭 자랐다.","결과 수많은 호박이 주렁주렁 열렸다.","결과 새달이가 호박을 따서 반을 갈랐다.","결과 그 호박은 새달이가 좋아하는 포도 맛이었다.","(결과는 다시 다음 일의 원인이 된다.)"],"numbered":false,"title":"원인과 결과를 생각하며 상상한 이어질 내용 — 『국어』 279쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#1','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C42',1,'mc','auto','이야기 이어 말하기 놀이에서 모둠의 두 번째 학생이 할 일은 무엇인가요?',ARRAY['K4-2-u6-X34','K4-2-u6-X35','K4-2-u6-X24']::text[],false,'{"seq":1,"concept":"K4-2-u6-C42","difficulty":1,"kind":"mc","stem":"이야기 이어 말하기 놀이에서 모둠의 두 번째 학생이 할 일은 무엇인가요?","options":[{"t":"원인과 결과, 시간의 흐름에 맞게 이어지는 뒤 문장을 말하면서 물건을 한 개 책상 위에 올려놓는다","correct":true},{"t":"가장 길게 말하고 다른 친구의 물건을 가져온다","mis":"K4-2-u6-X34"},{"t":"앞 문장과 상관없는 새 이야기를 시작한다","mis":"K4-2-u6-X35"},{"t":"첫 번째 학생이 한 문장을 그대로 따라 말한다","mis":"K4-2-u6-X24"}],"explanation":["첫 번째 학생이 한 문장을 읽거나 직접 말해요.","다음 학생은 그 문장에 이어지는 뒤 문장을 말해요.","말하면서 자신의 물건을 하나 책상 위에 올려놓아요."],"asset":{"type":"passage","lines":["1 모둠의 첫 번째 학생이 이야기에서 한 문장을 읽거나 직접 말한다.","2 두 번째 학생이 원인과 결과, 시간의 흐름에 맞게 이어지는 뒤 문장을 말하면서","  자신이 가지고 있는 물건을 한 개 책상 위에 올려놓는다.","3 인원수만큼 물건이 모이면 손을 머리에 올리며 모둠 이름을 외친다.","4 모둠에서 만든 이야기를 발표한다."],"numbered":false,"title":"이야기 이어 말하기 놀이 방법 — 『국어』 282쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#2','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C48',1,'mc','auto','기초 다지기 1에서 괄호 안의 알맞은 말끼리 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-2-u6-X42','K4-2-u6-X41']::text[],false,'{"seq":2,"concept":"K4-2-u6-C48","difficulty":1,"kind":"mc","stem":"기초 다지기 1에서 괄호 안의 알맞은 말끼리 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"학급 회장으로서 · 말로써","correct":true},{"t":"학급 회장으로써 · 말로서","mis":"K4-2-u6-X42"},{"t":"학급 회장으로써 · 말로써","mis":"K4-2-u6-X42"},{"t":"학급 회장으로서 · 말로서","mis":"K4-2-u6-X41"}],"explanation":["학급 회장은 신분이나 자격이라서 ‘으로서’를 써요.","말은 빚을 갚는 수단이라서 ‘로써’를 써요.","자격이면 (으)로서, 재료·수단·도구면 (으)로써예요."],"asset":{"type":"passage","lines":["나는 학급 회장(으로서, 으로써) 맡은 일에 최선을 다하고 있다.","말(로서, 로써) 천 냥 빚을 갚는다.","※ ‘(으)로서’는 신분 또는 자격을 나타내고,","‘(으)로써’는 어떤 물건의 재료나 원료, 수단이나 도구를 나타낼 때 사용해요."],"title":"기초 다지기 1 — 『국어』 286쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#3','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C61',1,'mc','auto','「마음에 꺼림칙한 느낌이 있다.」라는 뜻을 가진 낱말을 본문에서 찾았어요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":3,"concept":"K4-2-u6-C61","difficulty":1,"kind":"mc","stem":"「마음에 꺼림칙한 느낌이 있다.」라는 뜻을 가진 낱말을 본문에서 찾았어요. 알맞은 것은 무엇인가요?","options":[{"t":"찜찜하다","correct":true},{"t":"서운하다","mis":"K4-2-u6-X53"},{"t":"놀라다","mis":"K4-2-u6-X53"}],"explanation":["「랑랑별 때때롱」에 「새달이는 마음이 찜찜했습니다.」가 나와요.","엄마에게 사실대로 말하지 못해 마음이 꺼림칙했어요.","뜻을 문장에 넣어 읽어 보면 알 수 있어요."],"asset":{"type":"passage","lines":["● 마음에 모자라 아쉽거나 섭섭한 느낌이 있다.","● 뜻밖의 일이나 무서움에 가슴이 두근거리다.","● 마음에 꺼림칙한 느낌이 있다."],"numbered":false,"title":"기초 다지기 2 — 문장이 설명하는 낱말을 본문에서 찾기 (『국어』 286쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#4','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C62',1,'mc','auto','기초 다지기 3 글씨 쓰기 낱말이에요. 겹받침을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u6-X46']::text[],false,'{"seq":4,"concept":"K4-2-u6-C62","difficulty":1,"kind":"mc","stem":"기초 다지기 3 글씨 쓰기 낱말이에요. 겹받침을 바르게 쓴 것은 무엇인가요?","options":[{"t":"겉핥기","correct":true},{"t":"겉할기","mis":"K4-2-u6-X46"},{"t":"거탈기","mis":"K4-2-u6-X46"},{"t":"겉핣기","mis":"K4-2-u6-X46"}],"explanation":["「겉핥기」는 받침에 ㄹ과 ㅌ이 함께 들어가요.","소리 나는 대로 쓰지 않아요.","겹받침을 그대로 바르게 써요."],"asset":{"type":"passage","lines":["겉핥기 · 훑다 · 읊조리다","닳다 · 싫증 · 옳다 · 끓다"],"title":"기초 다지기 3 글씨 쓰기 — 『국어』 287쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#5','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C43',2,'mc','auto','친구 3이 이어 말할 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X36','K4-2-u6-X37','K4-2-u6-X35']::text[],false,'{"seq":5,"concept":"K4-2-u6-C43","difficulty":2,"kind":"mc","stem":"친구 3이 이어 말할 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그래서 나는 마당에서 친구들과 눈사람을 만들었습니다.","correct":true},{"t":"그런데 갑자기 한여름이 되어 수영장에 갔습니다.","mis":"K4-2-u6-X36"},{"t":"사실 눈은 하나도 쌓여 있지 않았습니다.","mis":"K4-2-u6-X37"},{"t":"우리 반 친구는 피아노를 잘 칩니다.","mis":"K4-2-u6-X35"}],"explanation":["앞 문장에서 눈이 쌓였고, 장갑을 챙겨 밖으로 나갔어요.","그래서 눈으로 할 수 있는 일이 이어져요.","갑자기 큰일, 끝난 일 되돌리기, 상관없는 일은 이야기를 끊어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"오늘 아침에 일어나 창밖을 내다보니 흰 눈이 소복하게 쌓여 있었습니다."},{"who":"친구 2","text":"그래서 나는 장갑을 챙겨 밖으로 나갔습니다."},{"who":"친구 3","text":"그래서……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#6','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C45',2,'mc','auto','「이어질 내용을 상상하여 역할놀이하기」에서 「모둠 친구들과 역할을 나누어 연습하기」 바로 앞에 할 일은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X40']::text[],false,'{"seq":6,"concept":"K4-2-u6-C45","difficulty":2,"kind":"mc","stem":"「이어질 내용을 상상하여 역할놀이하기」에서 「모둠 친구들과 역할을 나누어 연습하기」 바로 앞에 할 일은 무엇인가요?","options":[{"t":"「당나귀, 황소 그리고 농부」를 듣고 이어질 내용을 모둠 친구들과 함께 상상하기","correct":true},{"t":"친구들 앞에서 역할놀이하기","mis":"K4-2-u6-X19"},{"t":"친구들의 연극을 보고 생각이나 느낌 발표하기","mis":"K4-2-u6-X19"},{"t":"가장 긴 대사를 먼저 외우기","mis":"K4-2-u6-X40"}],"explanation":["먼저 「당나귀, 황소 그리고 농부」를 들어요.","이어질 내용을 모둠 친구들과 함께 상상해요.","그다음 역할을 나누어 연습하고 친구들 앞에서 역할놀이를 해요."],"asset":{"type":"passage","lines":["1 「당나귀, 황소 그리고 농부」 듣기","2 이어질 내용을 모둠 친구들과 함께 상상하기","3 모둠 친구들과 역할을 나누어 연습하기","4 친구들 앞에서 역할놀이하기"],"numbered":false,"title":"이런 활동 어때요 2 이어질 내용을 상상하여 역할놀이하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#7','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C43',2,'mc','auto','「당나귀, 황소 그리고 농부」를 듣고, 당나귀의 조언을 들은 황소가 이어서 할 행동으로 이야기 흐름에 맞는 것은 무엇인가요?',ARRAY['K4-2-u6-X36','K4-2-u6-X24','K4-2-u6-X38']::text[],false,'{"seq":7,"concept":"K4-2-u6-C43","difficulty":2,"kind":"mc","stem":"「당나귀, 황소 그리고 농부」를 듣고, 당나귀의 조언을 들은 황소가 이어서 할 행동으로 이야기 흐름에 맞는 것은 무엇인가요?","options":[{"t":"농부가 밭일을 시키려 하자 드러누워 아픈 척을 한다","correct":true},{"t":"갑자기 하늘을 날아 다른 마을로 떠난다","mis":"K4-2-u6-X36"},{"t":"당나귀의 말을 듣자마자 잠이 들어 이야기가 끝난다","mis":"K4-2-u6-X24"},{"t":"까닭 없이 당나귀의 여물을 모두 빼앗는다","mis":"K4-2-u6-X38"}],"explanation":["황소는 당나귀를 부러워했어요.","당나귀는 드러누워 일어나지 말고 아픈 척을 하라고 했어요.","그러니 황소가 그 조언대로 해 보는 것이 흐름에 맞아요."],"asset":{"type":"passage","lines":["(간추림) 짐승의 말을 알아듣는 농부가 마구간에서 당나귀와 황소의 대화를 엿들었다.","(간추림) 황소는 일이 적은 당나귀가 부럽다며, 자신은 새벽부터 땅을 판다고 했다.","“먼저, 밭일을 시키려고 하면 드러누워서 절대 일어나지 마.”","“그리고 음식도 먹지 말고 아픈 척을 해.”"],"title":"「당나귀, 황소 그리고 농부」 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#8','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C44',2,'mc','auto','「당나귀, 황소 그리고 농부」 대본 예시에서 농부가 황소 대신 당나귀를 밭으로 데려가게 한 까닭은 무엇인가요?',ARRAY['K4-2-u6-X18','K4-2-u6-X08']::text[],false,'{"seq":8,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"「당나귀, 황소 그리고 농부」 대본 예시에서 농부가 황소 대신 당나귀를 밭으로 데려가게 한 까닭은 무엇인가요?","options":[{"t":"당나귀가 황소에게 꾀병 부리는 법을 알려 주었다는 것을 알았기 때문","correct":true},{"t":"당나귀가 밭일을 하고 싶다고 졸랐기 때문","mis":"K4-2-u6-X18"},{"t":"황소가 정말로 크게 아팠기 때문","mis":"K4-2-u6-X08"},{"t":"하인이 당나귀를 무척 좋아했기 때문","mis":"K4-2-u6-X18"}],"explanation":["농부는 짐승의 말을 알아들어 둘의 대화를 엿들었어요.","황소가 당나귀의 잔꾀대로 꾀병을 부린다는 것을 알았어요.","그래서 꾀를 알려 준 당나귀에게 일을 시켰어요."],"asset":{"type":"passage","lines":["황소: (바닥에 드러누워 발버둥 치며) 에이, 모르겠다! 오늘 일 안 해요!","농부: (하인을 부르며) 여봐라. 황소 대신 당나귀를 밭으로 데려가거라.","당나귀: (깜짝 놀라며) 어? 뭐라고? 이게 아닌데…….","당나귀: (후회하는 목소리로) 아이고, 힘들다. 내가 내 잔꾀에 넘어갔구나."],"numbered":false,"title":"「당나귀, 황소 그리고 농부」 대본 예시 (소품: 여물통 · 쟁기)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#9','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C47',2,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_basic#10','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_basic','lesson_basic','K4-2-u6-C42',3,'essay','teacher','이야기 이어 말하기 놀이를 해요. 「오늘 아침에 일어나 창밖을 내다보니 흰 눈이 소복하게 쌓여 있었습니다. 그래서 나는 장갑을 챙겨 밖으로 나갔습니다.」에 이어질 문장 두 개를 원인과 결과, 시간의 흐름에 맞게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C42","difficulty":3,"kind":"essay","stem":"이야기 이어 말하기 놀이를 해요. 「오늘 아침에 일어나 창밖을 내다보니 흰 눈이 소복하게 쌓여 있었습니다. 그래서 나는 장갑을 챙겨 밖으로 나갔습니다.」에 이어질 문장 두 개를 원인과 결과, 시간의 흐름에 맞게 쓰세요.","answer_guide":{"answer":"예: 그래서 나는 동생과 함께 커다란 눈사람을 만들었습니다. 눈사람을 다 만들고 나니 손이 꽁꽁 얼어서 따뜻한 집으로 들어왔습니다.","scoring_points":["앞 문장에 이어지는 문장을 썼는가","원인과 결과가 드러나게 이었는가","시간의 흐름에 맞게 썼는가"]},"explanation":["앞 문장이 까닭이 되는 일을 이어요.","시간의 흐름에 맞게 차례대로 말해요.","「그래서」를 넣어 말이 되는지 확인해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"오늘 아침에 일어나 창밖을 내다보니 흰 눈이 소복하게 쌓여 있었습니다."},{"who":"친구 2","text":"그래서 나는 장갑을 챙겨 밖으로 나갔습니다."},{"who":"친구 3","text":"그래서……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#1','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C48',2,'mc','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#2','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C61',2,'mc','auto','「뜻밖의 일이나 무서움에 가슴이 두근거리다.」라는 뜻을 가진 낱말이 들어 있는 본문 문장은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":2,"concept":"K4-2-u6-C61","difficulty":2,"kind":"mc","stem":"「뜻밖의 일이나 무서움에 가슴이 두근거리다.」라는 뜻을 가진 낱말이 들어 있는 본문 문장은 무엇인가요?","options":[{"t":"실베스터는 자지러질 듯 놀랐지요.","correct":true},{"t":"그렇게 하고 말았지만 새달이는 마음이 찜찜했습니다.","mis":"K4-2-u6-X53"},{"t":"엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다.","mis":"K4-2-u6-X53"}],"explanation":["실베스터는 굶주린 사자를 보고 무서워 가슴이 두근거렸어요.","그 뜻을 가진 낱말은 ‘놀라다’예요.","찜찜하다와 서운하다는 다른 마음을 나타내요."],"asset":{"type":"passage","lines":["● 마음에 모자라 아쉽거나 섭섭한 느낌이 있다.","● 뜻밖의 일이나 무서움에 가슴이 두근거리다.","● 마음에 꺼림칙한 느낌이 있다."],"numbered":false,"title":"기초 다지기 2 — 문장이 설명하는 낱말을 본문에서 찾기 (『국어』 286쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#3','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C46',3,'mc','auto','친구들의 역할놀이를 감상할 때 가장 먼저 살펴볼 것은 무엇인가요?',ARRAY['K4-2-u6-X39','K4-2-u6-X40','K4-2-u6-X50']::text[],false,'{"seq":3,"concept":"K4-2-u6-C46","difficulty":3,"kind":"mc","stem":"친구들의 역할놀이를 감상할 때 가장 먼저 살펴볼 것은 무엇인가요?","options":[{"t":"인물의 성격에 맞고 앞 이야기와 자연스럽게 이어지는가","correct":true},{"t":"가장 웃긴 모둠이 어디인가","mis":"K4-2-u6-X39"},{"t":"대사가 가장 긴 친구는 누구인가","mis":"K4-2-u6-X40"},{"t":"소품을 가장 많이 준비한 모둠은 어디인가","mis":"K4-2-u6-X50"}],"explanation":["이어질 내용은 인물들의 성격을 생각하며 상상해요.","앞 이야기와 흐름이 자연스럽게 이어지는지 봐요.","감상한 뒤에는 자신의 생각이나 느낌을 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#4','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C45',3,'mc','auto','모둠 친구들과 「당나귀, 황소 그리고 농부」의 뒷이야기를 상상할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u6-X26','K4-2-u6-X50']::text[],false,'{"seq":4,"concept":"K4-2-u6-C45","difficulty":3,"kind":"mc","stem":"모둠 친구들과 「당나귀, 황소 그리고 농부」의 뒷이야기를 상상할 때 알맞은 방법은 무엇인가요?","options":[{"t":"모둠 친구들이 합의한 내용으로도, 한 친구의 의견으로도 상상해 보며 여러 방향을 겪어 본다","correct":true},{"t":"모둠장의 의견 하나로만 정하고 다른 생각은 듣지 않는다","mis":"K4-2-u6-X26"},{"t":"정답 결말 하나를 찾을 때까지 고친다","mis":"K4-2-u6-X26"},{"t":"대사만 외우고 이어질 내용은 상상하지 않는다","mis":"K4-2-u6-X50"}],"explanation":["뒷이야기는 여러 방향으로 상상할 수 있어요.","모둠이 합의한 내용과 한 사람의 의견을 모두 해 봐요.","그래야 다양한 상상의 방향을 겪을 수 있어요."],"asset":{"type":"passage","lines":["1 「당나귀, 황소 그리고 농부」 듣기","2 이어질 내용을 모둠 친구들과 함께 상상하기","3 모둠 친구들과 역할을 나누어 연습하기","4 친구들 앞에서 역할놀이하기"],"numbered":false,"title":"이런 활동 어때요 2 이어질 내용을 상상하여 역할놀이하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#5','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C53',3,'mc','auto','계단책의 가장 앞 장 다음 세 장에 처음·가운데·끝 이야기를 요약하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X28','K4-2-u6-X26','K4-2-u6-X49']::text[],false,'{"seq":5,"concept":"K4-2-u6-C53","difficulty":3,"kind":"mc","stem":"계단책의 가장 앞 장 다음 세 장에 처음·가운데·끝 이야기를 요약하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"전체 이야기의 흐름을 파악해, 그 흐름에서 이어지면서도 새로운 뒷이야기를 상상하기 위해","correct":true},{"t":"글자를 많이 써서 계단책을 두껍게 만들기 위해","mis":"K4-2-u6-X28"},{"t":"친구와 같은 이야기를 그대로 쓰기 위해","mis":"K4-2-u6-X26"},{"t":"앞 이야기와는 아주 다르게만 쓰기 위해","mis":"K4-2-u6-X49"}],"explanation":["처음·가운데·끝을 요약하면 이야기의 흐름이 보여요.","그 흐름에서 이어지게 뒷이야기를 상상해요.","같은 이야기를 고른 친구와 상상한 뒷이야기의 차이도 비교해요."],"asset":{"type":"passage","lines":["① 자신이 좋아하는 이야기를 하나 골라 뒷이야기를 상상해 본다.","② 계단책을 만든다.","③ 가장 앞 장은 표지로, 다음 세 장에는 처음·가운데·끝 이야기를 요약해 흐름을 정리한다.","④ 교실에 전시하고, 같은 이야기를 고른 친구와 상상한 뒷이야기를 비교한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 상상한 이야기로 계단책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#6','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C43',3,'error','auto','「원인과 결과로 놀이 하기」에서 두 카드를 이어 말했어요. 원인과 결과가 자연스럽게 이어지지 않아 카드를 가져갈 수 없는 것은 무엇인가요?',ARRAY['K4-2-u6-X51']::text[],false,'{"seq":6,"concept":"K4-2-u6-C43","difficulty":3,"kind":"error","stem":"「원인과 결과로 놀이 하기」에서 두 카드를 이어 말했어요. 원인과 결과가 자연스럽게 이어지지 않아 카드를 가져갈 수 없는 것은 무엇인가요?","options":[{"t":"“눈이 내립니다. 그래서 강아지가 피아노를 쳤습니다.”","correct":true,"mis_target":"K4-2-u6-X51"},{"t":"“눈이 내립니다. 그래서 강아지는 밖으로 나가자고 낑낑댔습니다.”","mis":"K4-2-u6-X51"},{"t":"“눈이 내립니다. 그래서 길이 하얗게 덮였습니다.”","mis":"K4-2-u6-X51"}],"explanation":["두 카드를 「그래서」로 이어 읽어 보아요.","눈이 내린 것이 피아노를 친 까닭이 되지 않아요.","자연스럽게 잇지 못하면 카드를 다시 내려놓아요."],"asset":{"type":"passage","lines":["① 그림 카드를 섞어서 그림이 보이지 않게 뒤집어 놓는다.","② 가위바위보를 하여 이긴 친구가 카드 두 장을 고른다.","③ 두 카드의 그림을 연결해 원인과 결과가 드러나게 말하면 두 카드를 가져간다.","④ 자연스럽게 연결하여 말하지 못하면 카드를 다시 내려놓는다.","⑤ 번갈아 가며 놀이를 하여 카드를 많이 가져간 친구가 이긴다.","예: 눈이 내립니다. 그래서 강아지는 밖으로 나가자고 낑낑댔습니다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 1 — 원인과 결과로 놀이 하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#7','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C54',3,'mc','auto','「생활 속으로」에서 세 친구가 다짐을 말했어요. 소단원 2(이어질 내용을 상상해 쓰기)에서 배운 것을 실천하겠다는 친구는 누구인가요?',ARRAY['K4-2-u6-X48']::text[],false,'{"seq":7,"concept":"K4-2-u6-C54","difficulty":3,"kind":"mc","stem":"「생활 속으로」에서 세 친구가 다짐을 말했어요. 소단원 2(이어질 내용을 상상해 쓰기)에서 배운 것을 실천하겠다는 친구는 누구인가요?","options":[{"t":"친구 2","correct":true},{"t":"친구 1","mis":"K4-2-u6-X48"},{"t":"친구 3","mis":"K4-2-u6-X48"}],"explanation":["친구 1은 내 경험을 원인과 결과에 따라 정리하겠다고 했어요.","친구 3은 원인과 결과를 생각하며 뉴스 기사를 읽겠다고 했어요.","친구 2는 이야기를 읽고 나만의 뒷이야기를 상상하겠다고 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"원인과 결과에 따라 내 경험을 정리해서 영상을 만들어 보겠어."},{"who":"친구 2","text":"이야기를 읽고 나만의 뒷이야기를 상상해 볼래."},{"who":"친구 3","text":"원인과 결과를 생각하며 뉴스 기사를 읽어 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#8','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C44',4,'essay','teacher','「당나귀, 황소 그리고 농부」에서 당나귀가 황소 대신 밭일을 하고 돌아온 다음의 장면을 상상해, 당나귀와 황소의 대사와 몸짓을 대본으로 쓰세요. 인물의 성격과 앞 이야기의 흐름이 드러나야 해요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u6-C44","difficulty":4,"kind":"essay","stem":"「당나귀, 황소 그리고 농부」에서 당나귀가 황소 대신 밭일을 하고 돌아온 다음의 장면을 상상해, 당나귀와 황소의 대사와 몸짓을 대본으로 쓰세요. 인물의 성격과 앞 이야기의 흐름이 드러나야 해요.","answer_guide":{"answer":"예: 당나귀 — (다리를 절뚝거리며) 아이고, 허리야. 황소야, 내일도 아픈 척할 거니? / 황소 — (고개를 갸웃하며) 너 덕분에 오늘 하루 편히 쉬었는걸. / 당나귀 — (손을 내저으며) 아니야, 아니야! 내일은 꼭 일어나서 밭에 나가. 내가 내 잔꾀에 넘어갔다니까.","scoring_points":["앞 이야기(당나귀가 밭일을 함)에서 이어지는가","인물의 성격(꾀 많은 당나귀 등)에 맞는 대사인가","대사와 함께 몸짓을 썼는가"]},"explanation":["앞 이야기에서 무슨 일이 왜 일어났는지 떠올려요.","인물의 성격에 맞는 말을 생각해요.","대사와 몸짓을 함께 정해 연습해요."],"asset":{"type":"passage","lines":["황소: (바닥에 드러누워 발버둥 치며) 에이, 모르겠다! 오늘 일 안 해요!","농부: (하인을 부르며) 여봐라. 황소 대신 당나귀를 밭으로 데려가거라.","당나귀: (깜짝 놀라며) 어? 뭐라고? 이게 아닌데…….","당나귀: (후회하는 목소리로) 아이고, 힘들다. 내가 내 잔꾀에 넘어갔구나."],"numbered":false,"title":"「당나귀, 황소 그리고 농부」 대본 예시 (소품: 여물통 · 쟁기)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#9','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C47',4,'essay','teacher','‘(으)로서’가 들어간 문장과 ‘(으)로써’가 들어간 문장을 하나씩 지어 쓰고, 각각 왜 그 말을 썼는지 쓰세요. (『국어』 286쪽에 나온 문장 말고)','{}'::text[],false,'{"seq":9,"concept":"K4-2-u6-C47","difficulty":4,"kind":"essay","stem":"‘(으)로서’가 들어간 문장과 ‘(으)로써’가 들어간 문장을 하나씩 지어 쓰고, 각각 왜 그 말을 썼는지 쓰세요. (『국어』 286쪽에 나온 문장 말고)","answer_guide":{"answer":"예: 나는 우리 반 도서 도우미로서 책을 정리한다. — 도서 도우미는 자격을 나타내므로 ‘로서’를 썼다. / 우리는 대화로써 다툼을 풀었다. — 대화는 다툼을 푸는 수단이므로 ‘로써’를 썼다.","scoring_points":["(으)로서를 자격·신분 자리에 썼는가","(으)로써를 재료·수단·도구 자리에 썼는가","각각 그렇게 쓴 까닭을 밝혔는가"]},"explanation":["(으)로서는 신분이나 자격을 나타내요.","(으)로써는 재료나 원료, 수단이나 도구를 나타내요.","받침이 있으면 ‘으’를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_L11_challenge#10','kor',4,2,'u6','L11','tb_g4_2_kor_u6_L11_challenge','lesson_challenge','K4-2-u6-C54',4,'essay','teacher','「생활 속으로」의 친구 1처럼, 최근에 내가 겪은 일 하나를 원인과 결과에 따라 세 칸(원인 → 결과이면서 원인 → 결과)으로 정리하고, 다음에는 어떻게 하고 싶은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u6-C54","difficulty":4,"kind":"essay","stem":"「생활 속으로」의 친구 1처럼, 최근에 내가 겪은 일 하나를 원인과 결과에 따라 세 칸(원인 → 결과이면서 원인 → 결과)으로 정리하고, 다음에는 어떻게 하고 싶은지 쓰세요.","answer_guide":{"answer":"예: 원인 — 늦게까지 게임을 했다. → 결과이면서 원인 — 아침에 늦잠을 잤다. → 결과 — 학교에 지각해서 아침 활동을 못 했다. 다음에는 정한 시간에 게임을 끄고 일찍 자겠다.","scoring_points":["내가 겪은 일을 골랐는가","세 칸이 원인과 결과로 이어지는가","원인을 생각해 다음에 할 일을 썼는가"]},"explanation":["원인과 결과는 이야기에만 있는 것이 아니에요.","내 경험에서도 결과가 다시 원인이 되어 이어져요.","원인을 알면 다음 일을 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#1','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C1',1,'mc','auto','원인과 결과의 뜻을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X35','K4-2-u6-X04']::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"원인과 결과의 뜻을 바르게 말한 것은 무엇인가요?","options":[{"t":"원인은 일이 일어난 까닭이고, 결과는 그 원인 때문에 벌어진 일이다","correct":true},{"t":"원인은 나중에 일어난 일이고, 결과는 먼저 일어난 일이다","mis":"K4-2-u6-X01"},{"t":"원인과 결과는 서로 상관없는 두 가지 일이다","mis":"K4-2-u6-X35"},{"t":"원인은 기분이고, 결과는 생각이다","mis":"K4-2-u6-X04"}],"explanation":["원인은 어떤 일이 일어난 까닭이에요.","결과는 그 까닭 때문에 벌어진 일이에요.","원인이 먼저, 결과가 나중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#2','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C55',1,'mc','auto','「소연이네 반에서 일어난 일」 뒷부분에서 방울토마토를 가져간 것은 무엇이었나요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":2,"concept":"K4-2-u6-C55","difficulty":1,"kind":"mc","stem":"「소연이네 반에서 일어난 일」 뒷부분에서 방울토마토를 가져간 것은 무엇이었나요?","options":[{"t":"새","correct":true},{"t":"소연이","mis":"K4-2-u6-X08"},{"t":"옆 반 친구들","mis":"K4-2-u6-X08"},{"t":"이웃 사람","mis":"K4-2-u6-X08"}],"explanation":["친구들은 누군가 가져갔을 것이라고도 예상했어요.","뒷부분을 보니 사람이 아니라 새가 가져간 것이었어요.","그래서 새를 쫓는 방법을 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#3','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C56',1,'mc','auto','『국어』 258쪽 그림에서 얼룩말이 나타난 장소는 어디인가요?',ARRAY['K4-2-u6-X12','K4-2-u6-X08']::text[],false,'{"seq":3,"concept":"K4-2-u6-C56","difficulty":1,"kind":"mc","stem":"『국어』 258쪽 그림에서 얼룩말이 나타난 장소는 어디인가요?","options":[{"t":"사람들이 사는 주택가 한복판","correct":true},{"t":"동물원 우리 안","mis":"K4-2-u6-X12"},{"t":"넓은 초원","mis":"K4-2-u6-X12"},{"t":"학교 운동장","mis":"K4-2-u6-X08"}],"explanation":["얼룩말은 사람들이 사는 주택가 한복판에 나타났어요.","동물원에나 있을 법한 동물이 주택가에 있었어요.","있을 만한 곳이 아니라서 까닭이 궁금해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#4','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C57',1,'mc','auto','「방 씨 규수의 이야기」에서 방진이 소문이 자자했던 까닭은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X16']::text[],false,'{"seq":4,"concept":"K4-2-u6-C57","difficulty":1,"kind":"mc","stem":"「방 씨 규수의 이야기」에서 방진이 소문이 자자했던 까닭은 무엇인가요?","options":[{"t":"백발백중의 활쏘기 솜씨","correct":true},{"t":"뛰어난 그림 솜씨","mis":"K4-2-u6-X08"},{"t":"어마어마한 재산","mis":"K4-2-u6-X16"},{"t":"빠른 달리기 솜씨","mis":"K4-2-u6-X08"}],"explanation":["방진은 백발백중의 활쏘기 솜씨로 소문이 자자했어요.","도둑들도 그 소문을 알고 있었어요.","그래서 미리 화살을 없애려고 했어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#5','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C58',1,'mc','auto','실베스터가 요술 조약돌을 찾아낸 곳은 어디인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X08']::text[],false,'{"seq":5,"concept":"K4-2-u6-C58","difficulty":1,"kind":"mc","stem":"실베스터가 요술 조약돌을 찾아낸 곳은 어디인가요?","options":[{"t":"시냇가","correct":true},{"t":"딸기 언덕","mis":"K4-2-u6-X19"},{"t":"집 마당","mis":"K4-2-u6-X08"},{"t":"바닷가","mis":"K4-2-u6-X08"}],"explanation":["비가 주룩주룩 내리는 토요일이었어요.","실베스터는 시냇가에서 놀다가 특이한 조약돌을 찾아냈어요.","딸기 언덕은 사자를 만난 곳이에요."],"asset":{"type":"passage","lines":["(간추림) 꼬마 당나귀 실베스터는 모양과 색깔이 특이한 조약돌 모으기를 좋아했다.","(간추림) 비 오는 토요일, 시냇가에서 새빨갛고 동그란 조약돌 하나를 찾아냈다.","“아, 제발 비 좀 그만 왔으면.”","(간추림) 그러자 비가 한순간에 딱 그쳤다.","(간추림) 돌을 땅 위에 내려놓고 말했을 때는 아무 일도 일어나지 않았지만,","(간추림) 돌을 손에 쥐고 같은 말을 하자 비가 억수같이 쏟아졌다."],"title":"「당나귀 실베스터와 요술 조약돌」 앞부분 — 『국어』 264~265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#6','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C59',1,'mc','auto','「랑랑별 때때롱」에서 호박이 없어진 것을 처음 알아챈 사람은 누구인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C59","difficulty":1,"kind":"mc","stem":"「랑랑별 때때롱」에서 호박이 없어진 것을 처음 알아챈 사람은 누구인가요?","options":[{"t":"엄마","correct":true},{"t":"새달이","mis":"K4-2-u6-X08"},{"t":"마달이","mis":"K4-2-u6-X08"},{"t":"아빠","mis":"K4-2-u6-X08"}],"explanation":["엄마가 돌담 위 호박 넝쿨을 살피다가 깜짝 놀랐어요.","아빠에게 호박이 없어졌다고 알렸어요.","아빠도 아이들도 몰랐어요."],"asset":{"type":"passage","lines":["(간추림) 엄마가 돌담 위 호박 넝쿨을 살피다가 호박이 없어진 것을 알았다.","(간추림) 씨호박 하려던 호박이었는데, 아빠도 새달이도 마달이도 몰랐다.","(간추림) 엄마는 누가 탐이 나서 훔쳐 간 것 같다며 아까워했다.","엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다."],"title":"「랑랑별 때때롱」 — 『국어』 272~273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#7','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C60',1,'mc','auto','『국어』 277쪽 낱말 알기에서 ‘어이가 없다’의 뜻은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":7,"concept":"K4-2-u6-C60","difficulty":1,"kind":"mc","stem":"『국어』 277쪽 낱말 알기에서 ‘어이가 없다’의 뜻은 무엇인가요?","options":[{"t":"일이 너무 뜻밖이어서 기가 막히는 듯하다","correct":true},{"t":"가지거나 차지하고 싶은 마음이 생기다","mis":"K4-2-u6-X53"},{"t":"마음이 언짢거나 불만스러움을 나타내다","mis":"K4-2-u6-X53"},{"t":"남의 말을 듣고 그대로 믿다","mis":"K4-2-u6-X53"}],"explanation":["새달이는 때때롱의 말을 듣고 화도 나고 어이가 없었어요.","너무 뜻밖의 일이라 기가 막혔어요.","보기의 뜻 ㉰와 이어져요."],"asset":{"type":"passage","lines":["보기: 어이가 없다 · 탐이 나다 · 혀를 차다","㉮ 가지거나 차지하고 싶은 마음이 생기다.","㉯ 마음이 언짢거나 불만스러움을 나타내다.","㉰ 일이 너무 뜻밖이어서 기가 막히는 듯하다."],"numbered":false,"title":"낱말 알기 — 『국어』 277쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#8','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C47',1,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#9','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C2',2,'mc','auto','「흥부와 놀부」에서 ②「제비는 이듬해 흥부에게 박씨를 물어다 주었습니다.」는 어떤 일인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X02']::text[],false,'{"seq":9,"concept":"K4-2-u6-C2","difficulty":2,"kind":"mc","stem":"「흥부와 놀부」에서 ②「제비는 이듬해 흥부에게 박씨를 물어다 주었습니다.」는 어떤 일인가요?","options":[{"t":"①의 결과이면서 ③의 원인인 일","correct":true},{"t":"①의 원인인 일","mis":"K4-2-u6-X01"},{"t":"③의 결과인 일","mis":"K4-2-u6-X01"},{"t":"원인도 결과도 아닌 일","mis":"K4-2-u6-X02"}],"explanation":["흥부가 제비 다리를 치료해 준 결과 제비가 박씨를 물어다 주었어요.","그 박씨에서 나온 금은보화로 흥부가 부자가 되었어요.","어떤 일의 결과가 다음 일의 원인이 되기도 해요."],"asset":{"type":"passage","lines":["① 흥부는 다친 제비 다리를 정성스레 치료해 주었습니다.","② 제비는 이듬해 흥부에게 박씨를 물어다 주었습니다.","③ 박에서 나온 금은보화로 흥부는 큰 부자가 되었습니다.","④ 이를 시샘한 놀부는 제비 다리를 일부러 부러뜨렸습니다.","⑤ 제비가 이듬해에 놀부에게 박씨를 물어다 주었습니다.","⑥ 놀부는 박에서 나온 도깨비들에게 혼쭐이 났습니다."],"numbered":false,"title":"익숙한 이야기에서 원인과 결과 찾기 — 「흥부와 놀부」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#10','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C17',2,'mc','auto','이야기를 듣고 원인과 결과로 정리할 때 도움이 되는 방법은 무엇인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X07']::text[],false,'{"seq":10,"concept":"K4-2-u6-C17","difficulty":2,"kind":"mc","stem":"이야기를 듣고 원인과 결과로 정리할 때 도움이 되는 방법은 무엇인가요?","options":[{"t":"일이 일어난 시간의 흐름(차례)을 먼저 생각해 본다","correct":true},{"t":"가장 재미있는 장면부터 적는다","mis":"K4-2-u6-X19"},{"t":"이야기에 나온 차례가 언제나 일이 일어난 차례라고 여긴다","mis":"K4-2-u6-X19"},{"t":"마지막 장면만 적는다","mis":"K4-2-u6-X07"}],"explanation":["원인과 결과로 정리할 때는 시간의 흐름을 생각해요.","먼저 일이 일어난 순서로 정리해 보아요.","그다음 인과 관계를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#11','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C29',2,'mc','auto','『국어』 268쪽 대화에서 친구 5의 말은 이어질 내용을 상상하는 방법 가운데 무엇을 알려 주나요?',ARRAY['K4-2-u6-X23','K4-2-u6-X24','K4-2-u6-X05']::text[],false,'{"seq":11,"concept":"K4-2-u6-C29","difficulty":2,"kind":"mc","stem":"『국어』 268쪽 대화에서 친구 5의 말은 이어질 내용을 상상하는 방법 가운데 무엇을 알려 주나요?","options":[{"t":"원인과 결과를 생각해요","correct":true},{"t":"인물의 성격을 생각해요","mis":"K4-2-u6-X23"},{"t":"이야기의 흐름을 파악해요","mis":"K4-2-u6-X24"},{"t":"가장 놀라운 일을 생각해요","mis":"K4-2-u6-X05"}],"explanation":["친구 5는 사건들 사이의 원인과 결과를 연결 지어야 한다고 했어요.","그래야 앞으로 벌어질 일이 자연스러워요.","세 가지 방법은 성격, 흐름, 원인과 결과예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인물의 성격을 알면 인물이 앞으로 어떤 행동을 할지 예상할 수 있어."},{"who":"친구 2","text":"성격은 인물의 말과 행동을 보면 알 수 있지."},{"who":"친구 3","text":"앞 이야기와 뒤에 이어질 이야기가 자연스럽게 연결되려면 어떻게 해야 할까?"},{"who":"친구 4","text":"이야기의 흐름을 생각하며 뒤에 이어질 내용을 상상해 보자."},{"who":"친구 5","text":"앞으로 벌어질 일이 자연스러우려면 사건들 사이의 원인과 결과를 연결 지어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#12','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C21',2,'mc','auto','「방 씨 규수의 이야기」에서 방 씨 규수가 지혜롭다는 것을 짐작할 수 있는 행동은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X20']::text[],false,'{"seq":12,"concept":"K4-2-u6-C21","difficulty":2,"kind":"mc","stem":"「방 씨 규수의 이야기」에서 방 씨 규수가 지혜롭다는 것을 짐작할 수 있는 행동은 무엇인가요?","options":[{"t":"화살이 떨어지자 베 짜는 데 쓰던 대나무를 화살인 척 내던져 도둑들을 속였다","correct":true},{"t":"도둑들이 무서워 방 안에 숨어 있었다","mis":"K4-2-u6-X08"},{"t":"나이가 열두 살이었다","mis":"K4-2-u6-X20"},{"t":"뒷날 이순신 장군과 혼인했다","mis":"K4-2-u6-X20"}],"explanation":["도둑들이 집 안마당까지 쳐들어왔는데 화살이 떨어졌어요.","방 씨 규수는 대나무 소리로 화살이 많은 것처럼 꾀를 냈어요.","성격은 그 상황에서 한 말과 행동으로 짐작해요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#13','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C10',2,'mc','auto','영상의 뒷부분을 보고 자신의 예상과 비교해 쓸 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u6-X11','K4-2-u6-X54','K4-2-u6-X06']::text[],false,'{"seq":13,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"영상의 뒷부분을 보고 자신의 예상과 비교해 쓸 때 알맞은 방법은 무엇인가요?","options":[{"t":"“~기 때문에 이런 결과를 예상했는데 영상의 뒷부분을 보니 ~이/가 달랐다.”처럼 쓴다","correct":true},{"t":"“같아서 좋았다.”처럼 느낌만 쓴다","mis":"K4-2-u6-X11"},{"t":"“내 예상이 맞았다.”처럼 맞고 틀림만 쓴다","mis":"K4-2-u6-X54"},{"t":"영상의 줄거리를 처음부터 다시 쓴다","mis":"K4-2-u6-X06"}],"explanation":["느낌이나 맞고 틀림만 쓰면 비교가 되지 않아요.","무엇을 까닭으로 예상했는지 밝혀요.","같은 점과 다른 점을 인과 관계에 맞추어 써요."],"asset":{"type":"passage","lines":["“~을/를 까닭으로 나는 이렇게 예상했는데 그 부분이 같았다.”","“~기 때문에 이런 결과를 예상했는데","영상의 뒷부분을 보니 ~이/가 달랐다.”"],"title":"예상과 비교하여 쓰는 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#14','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C22',2,'mc','auto','이야기를 듣고 원인과 결과를 정리하기 어려울 때 해 볼 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X07','K4-2-u6-X14','K4-2-u6-X15']::text[],false,'{"seq":14,"concept":"K4-2-u6-C22","difficulty":2,"kind":"mc","stem":"이야기를 듣고 원인과 결과를 정리하기 어려울 때 해 볼 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"일이 일어난 순서대로 먼저 정리한 뒤 원인과 결과를 확인한다","correct":true},{"t":"다시 듣지 않고 기억나는 장면만 쓴다","mis":"K4-2-u6-X07"},{"t":"들은 말을 모두 받아 적은 뒤에야 생각한다","mis":"K4-2-u6-X14"},{"t":"원인과 결과의 짝을 하나만 찾고 멈춘다","mis":"K4-2-u6-X15"}],"explanation":["간단히 메모하며 들어요.","일이 일어난 순서로 정리해 보아요.","그다음 인과 관계를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#15','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C42',2,'mc','auto','이야기 이어 말하기 놀이에서 모둠 학생들이 손을 머리에 올리며 모둠 이름을 외치는 때는 언제인가요?',ARRAY['K4-2-u6-X34','K4-2-u6-X19']::text[],false,'{"seq":15,"concept":"K4-2-u6-C42","difficulty":2,"kind":"mc","stem":"이야기 이어 말하기 놀이에서 모둠 학생들이 손을 머리에 올리며 모둠 이름을 외치는 때는 언제인가요?","options":[{"t":"모둠의 인원수만큼 물건이 모였을 때","correct":true},{"t":"가장 긴 문장을 말했을 때","mis":"K4-2-u6-X34"},{"t":"첫 번째 학생이 문장을 말했을 때","mis":"K4-2-u6-X19"},{"t":"이야기가 끝나기 전 아무 때나","mis":"K4-2-u6-X34"}],"explanation":["이어지는 문장을 말할 때마다 물건을 하나씩 올려놓아요.","인원수만큼 물건이 모이면 모둠 이름을 외쳐요.","그다음 모둠에서 만든 이야기를 발표해요."],"asset":{"type":"passage","lines":["1 모둠의 첫 번째 학생이 이야기에서 한 문장을 읽거나 직접 말한다.","2 두 번째 학생이 원인과 결과, 시간의 흐름에 맞게 이어지는 뒤 문장을 말하면서","  자신이 가지고 있는 물건을 한 개 책상 위에 올려놓는다.","3 인원수만큼 물건이 모이면 손을 머리에 올리며 모둠 이름을 외친다.","4 모둠에서 만든 이야기를 발표한다."],"numbered":false,"title":"이야기 이어 말하기 놀이 방법 — 『국어』 282쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#16','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C45',2,'mc','auto','「당나귀, 황소 그리고 농부」의 이어질 내용을 모둠 친구들과 상상할 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X39','K4-2-u6-X40','K4-2-u6-X50']::text[],false,'{"seq":16,"concept":"K4-2-u6-C45","difficulty":2,"kind":"mc","stem":"「당나귀, 황소 그리고 농부」의 이어질 내용을 모둠 친구들과 상상할 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"인물들의 성격, 앞 이야기와의 흐름, 왜 이런 일이 일어났는지","correct":true},{"t":"가장 웃길 만한 장면","mis":"K4-2-u6-X39"},{"t":"가장 긴 대사","mis":"K4-2-u6-X40"},{"t":"소품의 개수","mis":"K4-2-u6-X50"}],"explanation":["인물들의 성격을 고려하며 상상해요.","앞 이야기와 흐름이 자연스럽게 이어지게 해요.","왜 이런 일이 일어났는지 원인과 결과를 살펴요."],"asset":{"type":"passage","lines":["1 「당나귀, 황소 그리고 농부」 듣기","2 이어질 내용을 모둠 친구들과 함께 상상하기","3 모둠 친구들과 역할을 나누어 연습하기","4 친구들 앞에서 역할놀이하기"],"numbered":false,"title":"이런 활동 어때요 2 이어질 내용을 상상하여 역할놀이하기 — 『국어』 283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#17','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C17',3,'mc','auto','「서윤이의 일기」에서 서윤이가 집에 늦게 돌아온 까닭은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X18']::text[],false,'{"seq":17,"concept":"K4-2-u6-C17","difficulty":3,"kind":"mc","stem":"「서윤이의 일기」에서 서윤이가 집에 늦게 돌아온 까닭은 무엇인가요?","options":[{"t":"길을 잃은 아이를 파출소의 경찰관 아저씨께 데려다주고 왔기 때문","correct":true},{"t":"친구들과 놀다가 왔기 때문","mis":"K4-2-u6-X08"},{"t":"학교에 남아 숙제를 했기 때문","mis":"K4-2-u6-X08"},{"t":"서윤이가 길을 잃었기 때문","mis":"K4-2-u6-X18"}],"explanation":["아이는 이사 와서 집을 못 찾겠다고 했어요.","서윤이는 아이를 파출소에 데려다주었어요.","그래서 평소보다 한참 늦었어요."],"asset":{"type":"passage","lines":["(간추림) 학교를 마치고 오는 길에 혼자 울고 있는 대여섯 살쯤 된 아이를 보았다.","(간추림) 누가 도와주겠지 하고 지나갔다가, 아무도 돕지 않아 아이에게 되돌아갔다.","“집을 못 찾겠어.” “이사 와서 몰라.”","(간추림) 가까운 파출소의 경찰관 아저씨께 아이를 데려다주니 뿌듯한 마음이 들었다.","“서윤아, 도대체 왜 이렇게 늦었어? 어디에서 놀다 온 거니?”","(간추림) 평소보다 한참 늦어 죄송했지만 한편으로 억울한 생각이 들었다."],"title":"「서윤이의 일기」 간추린 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#18','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C39',3,'mc','auto','이어질 내용을 상상해 쓴 글을 평가할 때 가장 중요하게 보는 것은 무엇인가요?',ARRAY['K4-2-u6-X26','K4-2-u6-X28','K4-2-u6-X29']::text[],false,'{"seq":18,"concept":"K4-2-u6-C39","difficulty":3,"kind":"mc","stem":"이어질 내용을 상상해 쓴 글을 평가할 때 가장 중요하게 보는 것은 무엇인가요?","options":[{"t":"정답은 없지만 인물의 성격, 이야기의 흐름 및 인과 관계에 어울리게 상상했는가","correct":true},{"t":"원래 이야기의 결말과 똑같이 썼는가","mis":"K4-2-u6-X26"},{"t":"가장 길게 썼는가","mis":"K4-2-u6-X28"},{"t":"가장 놀랍게 썼는가","mis":"K4-2-u6-X29"}],"explanation":["이어질 내용에는 정해진 답이 없어요.","하지만 인물의 성격, 흐름, 인과 관계에 어울려야 해요.","상상하는 과정 전체를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#19','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C31',3,'mc','auto','「랑랑별 때때롱」 뒷이야기로 「호박을 갈랐더니 갑자기 괴물이 튀어나와 마을을 모두 부수었다.」를 썼어요. 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u6-X28','K4-2-u6-X27','K4-2-u6-X52']::text[],false,'{"seq":19,"concept":"K4-2-u6-C31","difficulty":3,"kind":"mc","stem":"「랑랑별 때때롱」 뒷이야기로 「호박을 갈랐더니 갑자기 괴물이 튀어나와 마을을 모두 부수었다.」를 썼어요. 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"나쁜 짓은 안 한다던 때때롱의 말과 이어지지 않고, 까닭 없이 황당한 일이 벌어지기 때문","correct":true},{"t":"문장이 너무 짧기 때문","mis":"K4-2-u6-X28"},{"t":"너무 평범한 일이기 때문","mis":"K4-2-u6-X27"},{"t":"괴물이 더 무섭게 나와야 하기 때문","mis":"K4-2-u6-X52"}],"explanation":["때때롱은 「우린 절대 나쁜 짓 안 한다.」라고 했어요.","괴물이 나와 마을을 부수는 일은 그 흐름과 어긋나요.","까닭 없이 황당한 이야기는 이어지지 않아요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#20','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C12',3,'mc','auto','얼룩말이 주택가에 나타난 까닭을 친구마다 다르게 예상했어요. 가장 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u6-X10','K4-2-u6-X13','K4-2-u6-X55']::text[],false,'{"seq":20,"concept":"K4-2-u6-C12","difficulty":3,"kind":"mc","stem":"얼룩말이 주택가에 나타난 까닭을 친구마다 다르게 예상했어요. 가장 알맞은 생각은 무엇인가요?","options":[{"t":"그림에 근거해 원인과 결과로 말할 수 있으면 저마다 다르게 예상해도 된다","correct":true},{"t":"정답인 까닭은 하나뿐이다","mis":"K4-2-u6-X10"},{"t":"그럴듯하기만 하면 근거가 없어도 된다","mis":"K4-2-u6-X13"},{"t":"실제 뉴스와 다른 예상은 모두 틀렸다","mis":"K4-2-u6-X55"}],"explanation":["예상은 정답을 찾는 활동이 아니에요.","저마다 다르게 예상할 수 있어요.","다만 그렇게 예상한 까닭은 그림에서 찾아요."],"asset":{"type":"passage","lines":["[그림] 사람들이 사는 주택가 한복판에 얼룩말이 나타났다.","[그림] 그 모습을 본 아저씨가 놀란 표정을 짓고 있다."],"numbered":false,"title":"영상의 한 장면 — 『국어』 258쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#21','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C29',3,'mc','auto','『국어활동』 89쪽에서 「두근두근」의 이어질 내용을 상상할 때 생각해 볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X24','K4-2-u6-X06']::text[],false,'{"seq":21,"concept":"K4-2-u6-C29","difficulty":3,"kind":"mc","stem":"『국어활동』 89쪽에서 「두근두근」의 이어질 내용을 상상할 때 생각해 볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"브레드 씨를 찾은 동물들의 고민과, 브레드 씨의 빵이 그 고민을 어떻게 해결할지","correct":true},{"t":"브레드 씨가 까닭 없이 성격이 바뀌어 동물들을 쫓아내는 일","mis":"K4-2-u6-X32"},{"t":"빵과 상관없는 우주여행 이야기","mis":"K4-2-u6-X24"},{"t":"어떻게 하면 가장 길게 쓸지","mis":"K4-2-u6-X06"}],"explanation":["브레드 씨는 빵 만드는 실력 때문에 여러 동물을 만나요.","동물들의 고민을 먼저 생각해요.","빵이 그 고민을 어떻게 풀지 원인과 결과로 상상해요."],"asset":{"type":"passage","lines":["(간추림) 「두근두근」의 브레드 씨는 부끄러움을 많이 타는 소심한 사람이다.","(간추림) 하지만 브레드 씨는 빵을 맛깔스럽게 만들 수 있다.","(간추림) 빵 만드는 실력 때문에 브레드 씨는 여러 동물을 만나 빵을 나누게 된다."],"title":"『국어활동』 84~88쪽 「두근두근」 인물과 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#22','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C24',3,'mc','auto','스스로 확인하기에서 ● 하나(보통임)를 칠한 줄이 있어요. 어떻게 하면 좋을까요?',ARRAY['K4-2-u6-X21']::text[],false,'{"seq":22,"concept":"K4-2-u6-C24","difficulty":3,"kind":"mc","stem":"스스로 확인하기에서 ● 하나(보통임)를 칠한 줄이 있어요. 어떻게 하면 좋을까요?","options":[{"t":"그 줄의 내용을 공부한 쪽으로 돌아가 다시 살펴본다","correct":true},{"t":"●●●로 고쳐 칠한다","mis":"K4-2-u6-X21"},{"t":"그 줄은 그냥 건너뛴다","mis":"K4-2-u6-X21"},{"t":"●의 개수를 더해 점수를 매긴다","mis":"K4-2-u6-X21"}],"explanation":["스스로 확인하기는 점수를 매기는 표가 아니에요.","부족한 줄은 다시 공부할 곳을 알려 줘요.","그 내용으로 돌아가 다시 살펴봐요."],"asset":{"type":"passage","lines":["원인과 결과를 생각하며 동영상을 볼 수 있나요?  ○○○","이야기를 듣고 원인과 결과를 잘 정리할 수 있나요?  ○○○","이야기를 읽고 이어질 내용을 상상해 쓸 수 있나요?  ○○○","이야기가 원인과 결과에 따라 자연스럽게 이어지게 상상할 수 있나요?  ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"스스로 확인하기 — 『국어』 285쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#23','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C17',4,'essay','teacher','「서윤이의 일기」를 듣고, 서윤이가 집에 늦게 돌아온 까닭을 원인과 결과가 잘 드러나게 소개하는 말을 쓰세요. ‘왜냐하면 …… 때문이다’를 넣어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C17","difficulty":4,"kind":"essay","stem":"「서윤이의 일기」를 듣고, 서윤이가 집에 늦게 돌아온 까닭을 원인과 결과가 잘 드러나게 소개하는 말을 쓰세요. ‘왜냐하면 …… 때문이다’를 넣어 쓰세요.","answer_guide":{"answer":"예: 서윤이는 평소보다 한참 늦게 집에 돌아왔습니다. 왜냐하면 길을 잃은 어린이를 아무도 도와주지 않는 것을 보고 걱정이 되어 근처에 있는 파출소까지 데려다주고 왔기 때문입니다.","scoring_points":["일어난 일(늦게 돌아옴)을 썼는가","원인(어린이를 파출소에 데려다줌)을 바르게 썼는가","‘왜냐하면 …… 때문이다’로 원인과 결과를 드러냈는가"]},"explanation":["이야기를 듣고 일어난 순서대로 정리해요.","늦은 것이 결과, 어린이를 도운 것이 원인이에요.","원인과 결과를 이어 주는 말을 넣어요."],"asset":{"type":"passage","lines":["(간추림) 학교를 마치고 오는 길에 혼자 울고 있는 대여섯 살쯤 된 아이를 보았다.","(간추림) 누가 도와주겠지 하고 지나갔다가, 아무도 돕지 않아 아이에게 되돌아갔다.","“집을 못 찾겠어.” “이사 와서 몰라.”","(간추림) 가까운 파출소의 경찰관 아저씨께 아이를 데려다주니 뿌듯한 마음이 들었다.","“서윤아, 도대체 왜 이렇게 늦었어? 어디에서 놀다 온 거니?”","(간추림) 평소보다 한참 늦어 죄송했지만 한편으로 억울한 생각이 들었다."],"title":"「서윤이의 일기」 간추린 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#24','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C30',4,'essay','teacher','「당나귀 실베스터와 요술 조약돌」을 읽고 이어질 이야기를 상상해 쓰세요. 실베스터를 걱정하는 엄마, 아빠가 나오게 하고, 인물의 성격·이야기의 흐름·원인과 결과가 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C30","difficulty":4,"kind":"essay","stem":"「당나귀 실베스터와 요술 조약돌」을 읽고 이어질 이야기를 상상해 쓰세요. 실베스터를 걱정하는 엄마, 아빠가 나오게 하고, 인물의 성격·이야기의 흐름·원인과 결과가 드러나게 쓰세요.","answer_guide":{"answer":"예: 실베스터가 돌아오지 않자 엄마, 아빠는 온 동네를 누비며 실베스터를 찾았다. 여러 달이 지나 실베스터를 그리워하던 엄마, 아빠는 딸기 언덕에 갔다가 반짝이는 빨간 조약돌을 주웠다. 엄마가 조약돌을 바위 위에 올려놓고 「실베스터가 돌아오면 좋겠어요.」라고 말하자, 조약돌이 실베스터의 몸에 닿아 실베스터는 다시 당나귀가 되었다. 실베스터는 엄마, 아빠를 꼭 안았다.","scoring_points":["엄마, 아빠가 나오고 인물의 성격에 어울리는가","앞 이야기의 흐름과 자연스럽게 이어지는가","원인과 결과(조약돌이 몸에 닿아야 함 등)가 드러나는가"]},"explanation":["엄마, 아빠는 실베스터를 걱정했을 거예요.","요술이 일어나는 조건을 떠올려요.","흐름과 원인·결과에 어울리게 상상해요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_a#25','kor',4,2,'u6','','tb_g4_2_kor_u6_review_a','unit_review','K4-2-u6-C45',4,'essay','teacher','「당나귀, 황소 그리고 농부」의 이어질 장면을 모둠 역할놀이 대본으로 쓰세요. 다음 날 아침 농부가 다시 황소를 밭으로 데려가려는 장면을, 인물마다 대사와 몸짓이 드러나게 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C45","difficulty":4,"kind":"essay","stem":"「당나귀, 황소 그리고 농부」의 이어질 장면을 모둠 역할놀이 대본으로 쓰세요. 다음 날 아침 농부가 다시 황소를 밭으로 데려가려는 장면을, 인물마다 대사와 몸짓이 드러나게 쓰세요.","answer_guide":{"answer":"예: 농부 — (쟁기를 들고) 황소야, 오늘은 일어날 수 있겠지? / 황소 — (벌떡 일어나며) 네, 주인님! 오늘은 다 나았어요. / 당나귀 — (한숨을 쉬며 작은 목소리로) 다행이다. 다시는 남에게 잔꾀를 알려 주지 말아야지.","scoring_points":["앞 이야기와 자연스럽게 이어지는가","인물의 성격에 맞는 대사를 썼는가","대사와 함께 몸짓을 썼는가"]},"explanation":["앞 장면에서 무슨 일이 왜 일어났는지 떠올려요.","인물의 성격에 맞게 말과 행동을 정해요.","역할을 나누어 연습하고 발표해요."],"asset":{"type":"passage","lines":["황소: (바닥에 드러누워 발버둥 치며) 에이, 모르겠다! 오늘 일 안 해요!","농부: (하인을 부르며) 여봐라. 황소 대신 당나귀를 밭으로 데려가거라.","당나귀: (깜짝 놀라며) 어? 뭐라고? 이게 아닌데…….","당나귀: (후회하는 목소리로) 아이고, 힘들다. 내가 내 잔꾀에 넘어갔구나."],"numbered":false,"title":"「당나귀, 황소 그리고 농부」 대본 예시 (소품: 여물통 · 쟁기)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#1','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C1',1,'mc','auto','세린이에게 일어난 일에서 「감기에 걸렸다」의 원인은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X22']::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":1,"kind":"mc","stem":"세린이에게 일어난 일에서 「감기에 걸렸다」의 원인은 무엇인가요?","options":[{"t":"눈이 오는 날 얇은 옷차림으로 밖에서 놀았다","correct":true},{"t":"병원에 갔다","mis":"K4-2-u6-X01"},{"t":"엄마가 옷을 따뜻하게 입으라고 하셨다","mis":"K4-2-u6-X22"},{"t":"의사 선생님이 ‘아’ 해 보라고 하셨다","mis":"K4-2-u6-X01"}],"explanation":["엄마 말씀과 달리 세린이는 얇은 옷을 입고 나갔어요.","눈 오는 날 얇은 옷차림으로 놀아서 감기에 걸렸어요.","병원에 간 것은 감기에 걸린 결과예요."],"asset":{"type":"passage","lines":["1 엄마: “세린아, 오늘 날씨가 추우니까 옷 따뜻하게 입어.” 세린: “네.”","2 세린: “얼른 밖에 나가서 놀아야지!” [그림] 눈이 오는 날 얇은 옷차림","3 엄마: “감기에 걸렸나 보네. 얼른 병원에 가자.”","4 의사: “‘아’ 해 보세요.” 세린: “아.”"],"numbered":false,"title":"경험 떠올리기 만화 — 『국어』 260쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#2','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C55',1,'mc','auto','「소연이네 반에서 일어난 일」 뒷부분에서 방울토마토를 지키려고 한 일은 무엇인가요?',ARRAY['K4-2-u6-X09','K4-2-u6-X08']::text[],false,'{"seq":2,"concept":"K4-2-u6-C55","difficulty":1,"kind":"mc","stem":"「소연이네 반에서 일어난 일」 뒷부분에서 방울토마토를 지키려고 한 일은 무엇인가요?","options":[{"t":"허수아비를 설치했다","correct":true},{"t":"경고 팻말을 세웠다","mis":"K4-2-u6-X09"},{"t":"방울토마토를 모두 땄다","mis":"K4-2-u6-X08"},{"t":"텃밭 문을 잠갔다","mis":"K4-2-u6-X08"}],"explanation":["방울토마토를 가져간 것은 새였어요.","새를 쫓는 데에는 허수아비가 효과가 있어요.","원인에 맞는 방법으로 결과가 이어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#3','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C56',1,'mc','auto','뉴스 영상에서 얼룩말을 동물원으로 돌려보낸 사람들은 누구인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":3,"concept":"K4-2-u6-C56","difficulty":1,"kind":"mc","stem":"뉴스 영상에서 얼룩말을 동물원으로 돌려보낸 사람들은 누구인가요?","options":[{"t":"신고를 받고 출동한 경찰과 소방관","correct":true},{"t":"지나가던 학생들","mis":"K4-2-u6-X08"},{"t":"얼룩말을 기르던 이웃","mis":"K4-2-u6-X08"},{"t":"그림 속 아저씨 혼자","mis":"K4-2-u6-X08"}],"explanation":["얼룩말 세로는 동물원을 탈출해 주택가에 나타났어요.","신고를 받고 경찰과 소방관이 출동했어요.","얼룩말은 동물원으로 돌아갔어요."],"asset":{"type":"passage","lines":["(간추림) 얼룩말 세로가 동물원을 탈출해 주택가에 나타났다.","(간추림) 신고를 받고 출동한 경찰과 소방관이 얼룩말을 동물원에 돌려보냈다."],"title":"뉴스 영상의 내용 — 『국어』 259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#4','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C57',1,'sa','auto','「방 씨 규수의 이야기」에서 도둑들이 미리 손을 써서 방진의 화살을 훔쳐 가게 한 사람은 누구인지 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u6-C57","difficulty":1,"kind":"sa","stem":"「방 씨 규수의 이야기」에서 도둑들이 미리 손을 써서 방진의 화살을 훔쳐 가게 한 사람은 누구인지 쓰세요.","answer":["하인","방진의 하인","방진 댁 하인"],"explanation":["도둑들은 방진 댁 하인 한 명을 한편으로 만들었어요.","그 하인이 대부분의 화살을 훔쳐 갔어요.","그래서 집 안에는 화살이 매우 적었어요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#5','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C58',1,'mc','auto','실베스터가 찾아낸 조약돌은 어떤 모양이었나요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":5,"concept":"K4-2-u6-C58","difficulty":1,"kind":"mc","stem":"실베스터가 찾아낸 조약돌은 어떤 모양이었나요?","options":[{"t":"불처럼 새빨갛고 반짝반짝 빛나며 유리구슬처럼 동그란 돌","correct":true},{"t":"까맣고 네모난 돌","mis":"K4-2-u6-X08"},{"t":"하얗고 납작한 돌","mis":"K4-2-u6-X08"},{"t":"파랗고 길쭉한 돌","mis":"K4-2-u6-X08"}],"explanation":["『국어』 264쪽에 조약돌의 모습이 나와요.","불처럼 새빨갛고 반짝반짝 빛났어요.","유리구슬처럼 아주 동그란 돌이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#6','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C59',1,'mc','auto','때때롱은 새달이네 호박을 어떻게 따 갔다고 말했나요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C59","difficulty":1,"kind":"mc","stem":"때때롱은 새달이네 호박을 어떻게 따 갔다고 말했나요?","options":[{"t":"기다란 기다란 집게로 뚝 따 갔다","correct":true},{"t":"사다리를 타고 내려와 땄다","mis":"K4-2-u6-X08"},{"t":"새를 시켜 물어 갔다","mis":"K4-2-u6-X08"},{"t":"주문을 외워 가져갔다","mis":"K4-2-u6-X08"}],"explanation":["새달이는 높은 하늘에서 무얼로 따 갔는지 물었어요.","때때롱은 기다란 기다란 집게로 뚝 따 왔다고 했어요.","새달이는 이 말을 듣고 기가 막혔어요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#7','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C60',1,'mc','auto','「랑랑별 때때롱」에 나온 낱말 ‘갈무리하다’의 뜻은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":7,"concept":"K4-2-u6-C60","difficulty":1,"kind":"mc","stem":"「랑랑별 때때롱」에 나온 낱말 ‘갈무리하다’의 뜻은 무엇인가요?","options":[{"t":"물건 따위를 잘 정리하거나 간수하다","correct":true},{"t":"남의 말을 듣고 그대로 믿다","mis":"K4-2-u6-X53"},{"t":"생김새가 몹시 험상궂고 무섭다","mis":"K4-2-u6-X53"},{"t":"씨를 받기 위해 잘 익은 다음에 따다","mis":"K4-2-u6-X53"}],"explanation":["엄마는 호박씨를 잘 갈무리해 뒀다가 심어 보자고 했어요.","갈무리하다는 잘 정리하거나 간수한다는 뜻이에요.","낱말 풀이와 문장을 함께 읽어요."],"asset":{"type":"passage","lines":["● 씨호박: 씨를 받기 위해 잘 익은 다음에 따는 호박.","● 곧이듣다: 남의 말을 듣고 그대로 믿다.","● 갈무리하다: 물건 따위를 잘 정리하거나 간수하다.","● 흉측하다: 생김새가 몹시 험상궂고 무섭다."],"numbered":false,"title":"낱말 풀이 — 『국어』 272~276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#8','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C61',1,'mc','auto','「마음에 모자라 아쉽거나 섭섭한 느낌이 있다.」라는 뜻을 가진 낱말을 본문에서 찾았어요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":8,"concept":"K4-2-u6-C61","difficulty":1,"kind":"mc","stem":"「마음에 모자라 아쉽거나 섭섭한 느낌이 있다.」라는 뜻을 가진 낱말을 본문에서 찾았어요. 알맞은 것은 무엇인가요?","options":[{"t":"서운하다","correct":true},{"t":"찜찜하다","mis":"K4-2-u6-X53"},{"t":"놀라다","mis":"K4-2-u6-X53"}],"explanation":["「엄마는 혀를 끌끌 차면서 몹시 서운한 눈치였습니다.」에서 찾아요.","씨호박이 없어져 아쉽고 섭섭했어요.","뜻을 넣어 읽어 보면 알 수 있어요."],"asset":{"type":"passage","lines":["● 마음에 모자라 아쉽거나 섭섭한 느낌이 있다.","● 뜻밖의 일이나 무서움에 가슴이 두근거리다.","● 마음에 꺼림칙한 느낌이 있다."],"numbered":false,"title":"기초 다지기 2 — 문장이 설명하는 낱말을 본문에서 찾기 (『국어』 286쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#9','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C14',2,'mc','auto','「포도 치마」에서 「어떤 일의 결과는 또 다른 일의 원인이 될 수 있다」를 잘 보여 주는 것은 무엇인가요?',ARRAY['K4-2-u6-X18','K4-2-u6-X02','K4-2-u6-X01']::text[],false,'{"seq":9,"concept":"K4-2-u6-C14","difficulty":2,"kind":"mc","stem":"「포도 치마」에서 「어떤 일의 결과는 또 다른 일의 원인이 될 수 있다」를 잘 보여 주는 것은 무엇인가요?","options":[{"t":"포도 그림이 그려진 멋진 치마가 탄생했고, 그 치마가 비싼 값에 팔렸다","correct":true},{"t":"여인이 잔치에 왔다","mis":"K4-2-u6-X18"},{"t":"국물을 쏟은 일은 원인도 결과도 아니다","mis":"K4-2-u6-X02"},{"t":"치맛값을 갚은 일이 국물을 쏟은 원인이다","mis":"K4-2-u6-X01"}],"explanation":["그림을 그린 결과 멋진 치마가 탄생했어요.","그 멋진 치마는 다시 원인이 되어 비싼 값에 팔렸어요.","그래서 여인은 치맛값을 갚을 수 있었어요."],"asset":{"type":"passage","lines":["(간추림) 마을 잔칫날, 한 여인이 빌려 입은 치마에 국물을 쏟아 큰 얼룩이 생겼다.","(간추림) 신사임당은 여인을 달래며 치마를 벗어서 건네 달라고 했다.","(간추림) 신사임당은 정성스럽게 먹을 갈더니 치마폭에 붓으로 그림을 그렸다.","“얼룩이 어느새 멋진 포도송이로 바뀌었네!”","(간추림) 아름다운 치마는 비싼 값에 팔려 여인은 빌린 치맛값을 갚을 수 있었다."],"title":"「포도 치마」 간추린 내용 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#10','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C27',2,'mc','auto','「당나귀 실베스터와 요술 조약돌」에서 첫 사건과 마지막 사건을 바르게 찾은 것은 무엇인가요?',ARRAY['K4-2-u6-X19']::text[],false,'{"seq":10,"concept":"K4-2-u6-C27","difficulty":2,"kind":"mc","stem":"「당나귀 실베스터와 요술 조약돌」에서 첫 사건과 마지막 사건을 바르게 찾은 것은 무엇인가요?","options":[{"t":"첫 사건: 시냇가에서 특이한 조약돌을 찾아냄 · 마지막 사건: 놀라고 당황해 바위가 됨","correct":true},{"t":"첫 사건: 바위가 됨 · 마지막 사건: 조약돌을 찾아냄","mis":"K4-2-u6-X19"},{"t":"첫 사건: 사자를 만남 · 마지막 사건: 비가 그침","mis":"K4-2-u6-X19"},{"t":"첫 사건: 사마귀를 없앰 · 마지막 사건: 조약돌을 찾아냄","mis":"K4-2-u6-X19"}],"explanation":["이야기에서 첫 사건과 마지막 사건을 찾아요.","그 사이에 일어난 일들의 순서를 살펴요.","흐름을 알면 이어질 이야기가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#11','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C27',2,'mc','auto','『국어』 268쪽 대화에서 친구 3과 친구 4가 말한 방법은 무엇인가요?',ARRAY['K4-2-u6-X23','K4-2-u6-X09','K4-2-u6-X06']::text[],false,'{"seq":11,"concept":"K4-2-u6-C27","difficulty":2,"kind":"mc","stem":"『국어』 268쪽 대화에서 친구 3과 친구 4가 말한 방법은 무엇인가요?","options":[{"t":"이야기의 흐름을 파악해요","correct":true},{"t":"인물의 성격을 생각해요","mis":"K4-2-u6-X23"},{"t":"원인과 결과를 생각해요","mis":"K4-2-u6-X09"},{"t":"글을 길게 써요","mis":"K4-2-u6-X06"}],"explanation":["친구 3은 앞 이야기와 뒤 이야기가 자연스럽게 연결되려면 어떻게 할지 물었어요.","친구 4는 이야기의 흐름을 생각하며 상상하자고 했어요.","흐름을 파악하면 다음 일이 자연스러워요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인물의 성격을 알면 인물이 앞으로 어떤 행동을 할지 예상할 수 있어."},{"who":"친구 2","text":"성격은 인물의 말과 행동을 보면 알 수 있지."},{"who":"친구 3","text":"앞 이야기와 뒤에 이어질 이야기가 자연스럽게 연결되려면 어떻게 해야 할까?"},{"who":"친구 4","text":"이야기의 흐름을 생각하며 뒤에 이어질 내용을 상상해 보자."},{"who":"친구 5","text":"앞으로 벌어질 일이 자연스러우려면 사건들 사이의 원인과 결과를 연결 지어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#12','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C37',2,'mc','auto','때때롱이 장난치는 것을 좋아하는 성격이라는 것을 짐작할 수 있는 근거는 무엇인가요?',ARRAY['K4-2-u6-X20']::text[],false,'{"seq":12,"concept":"K4-2-u6-C37","difficulty":2,"kind":"mc","stem":"때때롱이 장난치는 것을 좋아하는 성격이라는 것을 짐작할 수 있는 근거는 무엇인가요?","options":[{"t":"「기다란 기다란 집게로 뚝 따 가지고 왔지.」라고 말한 것","correct":true},{"t":"랑랑별에 산다는 것","mis":"K4-2-u6-X20"},{"t":"동생 매매롱이 있다는 것","mis":"K4-2-u6-X20"},{"t":"밤 10시 10분쯤 새달이를 불렀다는 것","mis":"K4-2-u6-X20"}],"explanation":["성격은 인물의 말과 행동에 드러나요.","때때롱은 새달이의 물음에 장난스럽게 대답했어요.","사는 곳이나 가족은 성격의 근거가 아니에요."],"asset":{"type":"passage","lines":["(간추림) 한참 뒤 때때롱이 부르자 새달이는 호박을 어떻게 따 갔는지 물었다.","“기다란 기다란 집게로 뚝 따 가지고 왔지.”","(간추림) 새달이는 기가 막혀 화를 내며 때때롱의 생김새까지 나쁘게 짐작했다.","“아니야. 내가 준 호박씨 내년에 심어 보면 알 거야. 우린 절대 나쁜 짓 안 한다.”"],"title":"「랑랑별 때때롱」 — 『국어』 276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#13','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C10',2,'mc','auto','자신의 예상과 영상을 비교할 때 무엇을 확인해야 하나요?',ARRAY['K4-2-u6-X54','K4-2-u6-X29','K4-2-u6-X28']::text[],false,'{"seq":13,"concept":"K4-2-u6-C10","difficulty":2,"kind":"mc","stem":"자신의 예상과 영상을 비교할 때 무엇을 확인해야 하나요?","options":[{"t":"내가 예상한 원인과 결과가 인과 관계를 충분히 고려한 것인지","correct":true},{"t":"예상이 영상과 똑같이 맞았는지만","mis":"K4-2-u6-X54"},{"t":"누구의 예상이 가장 놀라웠는지","mis":"K4-2-u6-X29"},{"t":"예상을 몇 줄이나 썼는지","mis":"K4-2-u6-X28"}],"explanation":["단순히 내용이 같은지만 비교하지 않아요.","예상한 원인과 결과가 서로 이어지는지 확인해요.","그래야 원인과 결과를 생각하며 보는 힘이 자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#14','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C23',2,'mc','auto','나눔의 날 인터뷰 글에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X16']::text[],false,'{"seq":14,"concept":"K4-2-u6-C23","difficulty":2,"kind":"mc","stem":"나눔의 날 인터뷰 글에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서랍 속 물건을 나누어 보람을 느낀 나눔의 날","correct":true},{"t":"샤프를 잃어버린 날","mis":"K4-2-u6-X08"},{"t":"맛있는 음식만 먹은 날","mis":"K4-2-u6-X16"},{"t":"혼자서 물건을 모아 둔 날","mis":"K4-2-u6-X08"}],"explanation":["어린이들은 쓰지 않는 물건을 필요한 친구들에게 나누었어요.","그래서 보람 있고 뿌듯했어요.","제목에는 글의 중심 내용이 드러나야 해요."],"asset":{"type":"passage","lines":["(간추림) ○○시에서 ‘나눔의 날’ 행사가 열렸다.","어린이: 사용하지 않는 깨끗하고 쓸모 있는 물건들을 필요한 친구들에게 나누어 주었습니다.","어린이: 친구는 사용하지 않지만 저에게는 꼭 필요한 샤프를 한 자루 받았어요.","어린이: 굉장히 보람 있고 뿌듯했어요.","어린이: 서랍 속에 잠자고 있던 물건이 꼭 필요한 사람에게 가게 되어 기뻤고요."],"numbered":false,"title":"원인과 결과를 생각하며 글 읽기 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#15','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C43',2,'error','auto','이야기 이어 말하기에서 친구 3이 말할 문장을 골랐어요. 이야기가 끊기는 알맞지 않은 문장은 무엇인가요?',ARRAY['K4-2-u6-X36']::text[],false,'{"seq":15,"concept":"K4-2-u6-C43","difficulty":2,"kind":"error","stem":"이야기 이어 말하기에서 친구 3이 말할 문장을 골랐어요. 이야기가 끊기는 알맞지 않은 문장은 무엇인가요?","options":[{"t":"“그때 갑자기 하늘에서 공룡이 떨어졌습니다.”","correct":true,"mis_target":"K4-2-u6-X36"},{"t":"“그래서 나는 친구들과 눈싸움을 했습니다.”","mis":"K4-2-u6-X36"},{"t":"“눈이 많이 쌓여서 걸을 때마다 뽀드득 소리가 났습니다.”","mis":"K4-2-u6-X36"}],"explanation":["앞 문장은 눈이 쌓여 장갑을 챙겨 나간 일이에요.","까닭 없이 갑자기 큰일이 벌어지면 이야기가 끊겨요.","앞 문장이 까닭이 되는 문장을 이어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"오늘 아침에 일어나 창밖을 내다보니 흰 눈이 소복하게 쌓여 있었습니다."},{"who":"친구 2","text":"그래서 나는 장갑을 챙겨 밖으로 나갔습니다."},{"who":"친구 3","text":"그래서……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#16','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C44',2,'mc','auto','「당나귀, 황소 그리고 농부」에서 당나귀가 황소에게 한 조언은 무엇인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":16,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"「당나귀, 황소 그리고 농부」에서 당나귀가 황소에게 한 조언은 무엇인가요?","options":[{"t":"밭일을 시키려 하면 드러누워 일어나지 말고, 음식도 먹지 말고 아픈 척을 하라","correct":true},{"t":"농부에게 일을 더 시켜 달라고 하라","mis":"K4-2-u6-X08"},{"t":"여물을 더 많이 먹고 힘을 내라","mis":"K4-2-u6-X08"},{"t":"밤에 몰래 마구간을 빠져나가라","mis":"K4-2-u6-X08"}],"explanation":["황소는 일이 많은 자기 처지를 불평했어요.","당나귀는 드러누워 일어나지 말라고 했어요.","음식도 먹지 말고 아픈 척을 하라고 했어요."],"asset":{"type":"passage","lines":["(간추림) 짐승의 말을 알아듣는 농부가 마구간에서 당나귀와 황소의 대화를 엿들었다.","(간추림) 황소는 일이 적은 당나귀가 부럽다며, 자신은 새벽부터 땅을 판다고 했다.","“먼저, 밭일을 시키려고 하면 드러누워서 절대 일어나지 마.”","“그리고 음식도 먹지 말고 아픈 척을 해.”"],"title":"「당나귀, 황소 그리고 농부」 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#17','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C23',3,'mc','auto','「서윤이의 일기」에서 서윤이가 억울한 생각이 든 까닭은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X18']::text[],false,'{"seq":17,"concept":"K4-2-u6-C23","difficulty":3,"kind":"mc","stem":"「서윤이의 일기」에서 서윤이가 억울한 생각이 든 까닭은 무엇인가요?","options":[{"t":"아이를 도와주고 왔는데 어머니께서 놀다 오느라 늦은 것으로 오해하셨기 때문","correct":true},{"t":"어머니께서 걱정하지 않으셨기 때문","mis":"K4-2-u6-X08"},{"t":"도와준 아이가 고맙다고 하지 않았기 때문","mis":"K4-2-u6-X18"},{"t":"파출소가 너무 멀었기 때문","mis":"K4-2-u6-X18"}],"explanation":["어머니는 「어디에서 놀다 온 거니?」라고 물으셨어요.","서윤이는 놀다 온 것이 아니라 아이를 도왔어요.","오해를 받아서 억울한 마음이 들었어요."],"asset":{"type":"passage","lines":["(간추림) 학교를 마치고 오는 길에 혼자 울고 있는 대여섯 살쯤 된 아이를 보았다.","(간추림) 누가 도와주겠지 하고 지나갔다가, 아무도 돕지 않아 아이에게 되돌아갔다.","“집을 못 찾겠어.” “이사 와서 몰라.”","(간추림) 가까운 파출소의 경찰관 아저씨께 아이를 데려다주니 뿌듯한 마음이 들었다.","“서윤아, 도대체 왜 이렇게 늦었어? 어디에서 놀다 온 거니?”","(간추림) 평소보다 한참 늦어 죄송했지만 한편으로 억울한 생각이 들었다."],"title":"「서윤이의 일기」 간추린 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#18','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C30',3,'mc','auto','바위가 된 실베스터의 뒷이야기로 가장 알맞게 이어지는 것은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X36','K4-2-u6-X23']::text[],false,'{"seq":18,"concept":"K4-2-u6-C30","difficulty":3,"kind":"mc","stem":"바위가 된 실베스터의 뒷이야기로 가장 알맞게 이어지는 것은 무엇인가요?","options":[{"t":"실베스터를 애타게 찾던 엄마, 아빠가 딸기 언덕에서 요술 조약돌을 발견하게 된다","correct":true},{"t":"실베스터는 바위가 된 채로 다음 날 학교에 갔다","mis":"K4-2-u6-X24"},{"t":"까닭 없이 하늘에서 거대한 손이 내려와 실베스터를 당나귀로 바꾸었다","mis":"K4-2-u6-X36"},{"t":"실베스터는 바위가 된 것이 신나서 춤을 추었다","mis":"K4-2-u6-X23"}],"explanation":["실베스터의 엄마, 아빠는 실베스터를 걱정하고 있을 거예요.","조약돌이 딸기 언덕에 있다는 흐름과도 이어져요.","까닭 없는 일이나 앞과 어긋나는 일은 이어지지 않아요."],"asset":{"type":"passage","lines":["(간추림) 실베스터는 날씨를 다시 좋게 하고 왼쪽 뒷다리의 사마귀도 없앴다.","(간추림) 엄마, 아빠를 놀래 주려고 집으로 달리다가 굶주린 사자를 만났다.","“내, 내가 바, 바, 바위면 좋겠어.”","(간추림) 실베스터는 곧바로 바위가 되었고, 사자는 어리둥절해하며 발길을 돌렸다.","(간추림) 요술 조약돌은 코앞에 있었지만 손이 없으니 집을 수가 없었다.","(간추림) 요술은 돌이 몸에 닿아야 일어나는데 그럴 수가 없었다."],"title":"「당나귀 실베스터와 요술 조약돌」 뒷부분 — 『국어』 266~267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#19','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C30',3,'ox','auto','뒷이야기를 재미있게 쓰는 것도 좋지만 너무 장난스럽지 않아야 해요.',ARRAY['K4-2-u6-X52']::text[],false,'{"seq":19,"concept":"K4-2-u6-C30","difficulty":3,"kind":"ox","stem":"뒷이야기를 재미있게 쓰는 것도 좋지만 너무 장난스럽지 않아야 해요.","answer":"O","reason_options":[{"t":"장난스럽게만 지어내면 인물의 성격이나 이야기의 흐름과 어울리지 않을 수 있기 때문에","correct":true},{"t":"상상이니까 장난스러울수록 좋은 이야기이기 때문에","mis":"K4-2-u6-X52"}],"mis":"K4-2-u6-X52","explanation":["『국어』 271쪽에서 친구가 한 조언이에요.","인물의 성격, 이야기의 흐름과 어울리게 써요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"앞 이야기를 잘 살펴보고 자연스럽게 이어지도록 써야 해요."},{"who":"친구 2","text":"이야기를 재미있게 쓰는 것도 좋지만 너무 장난스럽지 않아야 해요."},{"who":"친구 3","text":"이야기의 흐름이 자연스러운지 살펴봐요."},{"who":"친구 4","text":"상상한 이야기가 등장인물의 성격과 잘 어울려야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#20','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C9',3,'mc','auto','방울토마토가 없어진 까닭을 두 친구가 다르게 예상했어요. 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u6-X09','K4-2-u6-X07']::text[],false,'{"seq":20,"concept":"K4-2-u6-C9","difficulty":3,"kind":"mc","stem":"방울토마토가 없어진 까닭을 두 친구가 다르게 예상했어요. 바르게 말한 것은 무엇인가요?","options":[{"t":"새가 먹었다고 본 친구는 허수아비를, 누군가 가져갔다고 본 친구는 경고 팻말을 예상했다","correct":true},{"t":"두 친구 모두 허수아비를 예상해야 한다","mis":"K4-2-u6-X09"},{"t":"원인이 달라도 결과는 하나여야 한다","mis":"K4-2-u6-X09"},{"t":"까닭은 생각하지 않고 결과만 정하면 된다","mis":"K4-2-u6-X07"}],"explanation":["예상한 원인이 다르면 그다음 할 일도 달라져요.","새라면 허수아비, 사람이라면 경고 팻말이 이어져요.","원인과 결과가 짝이 맞게 예상해요."],"asset":{"type":"passage","lines":["㉮ 새가 방울토마토를 쪼아 먹었을 것이다.","㉯ 방울토마토를 누군가 가져갔을 것이다."],"numbered":false,"title":"방울토마토가 없어진 까닭 예상 — 『국어』 257쪽 2번 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#21','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C29',3,'mc','auto','『국어활동』 89쪽 예시 답안에서 양의 몸이 금세 따뜻해진 원인은 무엇인가요?',ARRAY['K4-2-u6-X22','K4-2-u6-X01']::text[],false,'{"seq":21,"concept":"K4-2-u6-C29","difficulty":3,"kind":"mc","stem":"『국어활동』 89쪽 예시 답안에서 양의 몸이 금세 따뜻해진 원인은 무엇인가요?","options":[{"t":"브레드 씨가 구워 준 따끈따끈한 호빵을 먹었기 때문","correct":true},{"t":"길을 잃었기 때문","mis":"K4-2-u6-X22"},{"t":"그 뒤로 종종 브레드 씨를 찾아왔기 때문","mis":"K4-2-u6-X01"},{"t":"추위에 떨었기 때문","mis":"K4-2-u6-X01"}],"explanation":["양은 길을 잃고 추위에 떨고 있었어요.","브레드 씨가 호빵을 구워 주었어요.","호빵을 먹은 결과 몸이 따뜻해졌어요."],"asset":{"type":"passage","lines":["문밖에는 양이 추위에 떨며 오들오들.","“길을 잃었는데 맛있는 냄새가 나서. 아휴, 너무 추워.”","브레드 씨는 양에게 호빵을 구워 주었어요.","양은 따끈따끈한 호빵을 먹고 금세 몸이 따뜻해졌어요.","그 뒤로 양은 종종 브레드 씨를 찾아왔어요."],"title":"『국어활동』 89쪽 예시 답안 — 「두근두근」의 이어질 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#22','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C54',3,'mc','auto','「원인과 결과를 생각하며 뉴스 기사를 읽어 볼 거야.」라는 다짐을 실천하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X07','K4-2-u6-X18','K4-2-u6-X48']::text[],false,'{"seq":22,"concept":"K4-2-u6-C54","difficulty":3,"kind":"mc","stem":"「원인과 결과를 생각하며 뉴스 기사를 읽어 볼 거야.」라는 다짐을 실천하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"기사에서 일어난 일, 그 일이 일어난 까닭, 그래서 어떻게 되었는지를 찾으며 읽는다","correct":true},{"t":"기사 제목만 읽는다","mis":"K4-2-u6-X07"},{"t":"기사에 나오지 않은 까닭을 지어 넣는다","mis":"K4-2-u6-X18"},{"t":"원인과 결과는 이야기에만 있으니 기사는 그냥 읽는다","mis":"K4-2-u6-X48"}],"explanation":["원인과 결과는 뉴스에도 있어요.","일어난 일, 원인, 결과를 찾으며 읽어요.","기사에 나온 내용만 근거로 삼아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"원인과 결과에 따라 내 경험을 정리해서 영상을 만들어 보겠어."},{"who":"친구 2","text":"이야기를 읽고 나만의 뒷이야기를 상상해 볼래."},{"who":"친구 3","text":"원인과 결과를 생각하며 뉴스 기사를 읽어 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#23','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C9',4,'essay','teacher','「서윤이의 일기」에서 서윤이가 앞으로 할 행동을 예상해 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C9","difficulty":4,"kind":"essay","stem":"「서윤이의 일기」에서 서윤이가 앞으로 할 행동을 예상해 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 쓰세요.","answer_guide":{"answer":"예: 앞으로 할 행동 — 서윤이는 어머니께 늦은 까닭을 설명해서 오해를 풀 것 같다. 까닭 — 서윤이는 어린이를 도와주고 왔는데 어머니께서 놀다 오느라 늦은 것으로 오해하셔서 억울한 마음이기 때문이다.","scoring_points":["서윤이가 앞으로 할 행동을 예상해 썼는가","그렇게 생각한 까닭을 이야기에서 찾아 썼는가","원인과 결과가 자연스럽게 이어지는가"]},"explanation":["서윤이의 마음(죄송함과 억울함)을 떠올려요.","그 마음이 원인이 되어 어떤 행동을 할지 예상해요.","까닭은 이야기 안에서 찾아요."],"asset":{"type":"passage","lines":["(간추림) 학교를 마치고 오는 길에 혼자 울고 있는 대여섯 살쯤 된 아이를 보았다.","(간추림) 누가 도와주겠지 하고 지나갔다가, 아무도 돕지 않아 아이에게 되돌아갔다.","“집을 못 찾겠어.” “이사 와서 몰라.”","(간추림) 가까운 파출소의 경찰관 아저씨께 아이를 데려다주니 뿌듯한 마음이 들었다.","“서윤아, 도대체 왜 이렇게 늦었어? 어디에서 놀다 온 거니?”","(간추림) 평소보다 한참 늦어 죄송했지만 한편으로 억울한 생각이 들었다."],"title":"「서윤이의 일기」 간추린 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#24','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C37',4,'essay','teacher','「랑랑별 때때롱」에서 새달이가 때때롱이 준 호박씨를 심지 않는다면 어떤 일이 벌어질지 상상해 쓰세요. 새달이의 성격과 원인과 결과가 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C37","difficulty":4,"kind":"essay","stem":"「랑랑별 때때롱」에서 새달이가 때때롱이 준 호박씨를 심지 않는다면 어떤 일이 벌어질지 상상해 쓰세요. 새달이의 성격과 원인과 결과가 드러나게 쓰세요.","answer_guide":{"answer":"예: 새달이는 때때롱이 거짓말을 한다고 생각해 호박씨를 서랍 속에 넣어 두고 잊어버렸다. 그런데 이듬해 봄, 서랍을 열자 호박씨에서 싹이 돋아 있었다. 궁금한 것을 참지 못하는 새달이는 서둘러 싹을 텃밭에 옮겨 심었고, 때때롱을 의심한 일을 미안해했다.","scoring_points":["호박씨를 심지 않는 쪽으로 상상했는가","새달이의 성격(궁금한 것을 참지 못함·쉽게 화를 냄)이 드러나는가","원인과 결과가 자연스럽게 이어지는가"]},"explanation":["이어질 내용은 심거나 심지 않거나 두 갈래로 상상할 수 있어요.","새달이의 성격을 살려요.","사건 사이의 원인과 결과가 자연스러운지 살펴요."],"asset":{"type":"passage","lines":["① 한밤중에 랑랑별 때때롱이 새달이네 호박을 몰래 따 갔다.","② 다음 날 아침, 새달이네 집에서는 호박이 없어진 것을 알고 깜짝 놀랐다.","③ 그날 밤, 때때롱이 호박을 따서 호박죽을 만들어 먹었다고 새달이에게 말했다.","④ 새달이네 집에서는 호박씨를 잘 갈무리해 두었다가 내년에 심기로 했다.","⑤ 새달이는 때때롱이 어떻게 기다란 집게로 호박을 따 갔는지 물었다."],"numbered":false,"title":"이야기의 흐름 정리 — 『국어』 278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_b#25','kor',4,2,'u6','','tb_g4_2_kor_u6_review_b','unit_review','K4-2-u6-C42',4,'essay','teacher','「원인과 결과로 놀이 하기」를 해요. 그림 카드 두 장에 들어갈 장면을 직접 정해 쓰고, 두 카드를 원인과 결과가 드러나게 이어 말하는 문장을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C42","difficulty":4,"kind":"essay","stem":"「원인과 결과로 놀이 하기」를 해요. 그림 카드 두 장에 들어갈 장면을 직접 정해 쓰고, 두 카드를 원인과 결과가 드러나게 이어 말하는 문장을 쓰세요.","answer_guide":{"answer":"예: 카드 1 — 바람이 세게 분다. 카드 2 — 빨랫줄의 옷이 떨어져 있다. 이어 말하기 — 바람이 세게 불었습니다. 그래서 빨랫줄에 널어 둔 옷이 바닥에 떨어졌습니다.","scoring_points":["두 카드의 장면을 썼는가","한 장면이 다른 장면의 원인이 되게 이었는가","「그래서」 같은 말로 자연스럽게 이어 말했는가"]},"explanation":["두 장면 가운데 어느 것이 먼저인지 생각해요.","앞 장면이 뒤 장면의 까닭이 되게 이어요.","「그래서」를 넣어 읽어 말이 되는지 확인해요."],"asset":{"type":"passage","lines":["① 그림 카드를 섞어서 그림이 보이지 않게 뒤집어 놓는다.","② 가위바위보를 하여 이긴 친구가 카드 두 장을 고른다.","③ 두 카드의 그림을 연결해 원인과 결과가 드러나게 말하면 두 카드를 가져간다.","④ 자연스럽게 연결하여 말하지 못하면 카드를 다시 내려놓는다.","⑤ 번갈아 가며 놀이를 하여 카드를 많이 가져간 친구가 이긴다.","예: 눈이 내립니다. 그래서 강아지는 밖으로 나가자고 낑낑댔습니다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 1 — 원인과 결과로 놀이 하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#1','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C1',1,'ox','auto','「관광객이 많아서 바다가 푸른 형광색으로 변한다」는 말은 원인과 결과를 바르게 말한 것이에요.',ARRAY['K4-2-u6-X01']::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":1,"kind":"ox","stem":"「관광객이 많아서 바다가 푸른 형광색으로 변한다」는 말은 원인과 결과를 바르게 말한 것이에요.","answer":"X","reason_options":[{"t":"바다가 빛나는 모습이 원인이 되어 관광객이 많아진 것인데 거꾸로 말했기 때문에","correct":true},{"t":"관광객이 많아진 일이 바다가 빛나기 전에 먼저 일어났기 때문에","mis":"K4-2-u6-X01"}],"mis":"K4-2-u6-X01","explanation":["바다가 빛나는 까닭은 바닷속에 빛을 내는 생물이 있어서예요.","관광객은 그 신기한 모습을 보러 왔어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"뉴스","text":"밤이면 푸른 형광색으로 변하는 바다가 있다고 합니다. 그 까닭은 자극을 받으면 빛을 내는 생물이 바닷속에 있기 때문입니다."},{"who":"뉴스","text":"이 신기한 모습을 보기 위해 관광객이 많아지고 있다고 합니다."},{"who":"수영","text":"너희 그거 알아? 밤이면 푸른 형광색으로 변하는 바다가 있대."},{"who":"친구","text":"왜 그런 일이 생긴 거야?"},{"who":"수영","text":"관광객이 많아서 그랬다고 한 것 같은데?"},{"who":"친구","text":"관광객?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#2','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C55',1,'ox','auto','소연이네 반 친구들은 방울토마토를 수확할 날을 기대하고 있었어요.',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":2,"concept":"K4-2-u6-C55","difficulty":1,"kind":"ox","stem":"소연이네 반 친구들은 방울토마토를 수확할 날을 기대하고 있었어요.","answer":"O","reason_options":[{"t":"잘 익은 방울토마토가 감쪽같이 사라져서 놀랐다고 했기 때문에","correct":true},{"t":"친구들은 방울토마토가 사라지기를 바랐기 때문에","mis":"K4-2-u6-X08"}],"mis":"K4-2-u6-X08","explanation":["친구들은 봄부터 방울토마토를 정성껏 길렀어요.","수확을 기대했기 때문에 사라진 것을 보고 놀랐어요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 소연이네 반 친구들은 올해 봄부터 옥상 텃밭에서 방울토마토를 길렀다.","(간추림) 친구들은 방울토마토를 수확할 날을 기대하고 있었다.","(간추림) 그런데 잘 익은 방울토마토가 감쪽같이 사라졌다."],"title":"「소연이네 반에서 일어난 일」 앞부분 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#3','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C11',1,'ox','auto','중심 사건(얼룩말이 주택가에 나타남)의 앞에 있었던 일은 그 사건의 원인이 될 수 있어요.',ARRAY['K4-2-u6-X35']::text[],false,'{"seq":3,"concept":"K4-2-u6-C11","difficulty":1,"kind":"ox","stem":"중심 사건(얼룩말이 주택가에 나타남)의 앞에 있었던 일은 그 사건의 원인이 될 수 있어요.","answer":"O","reason_options":[{"t":"동물원에서 탈출한 일이 원인이 되어 주택가에 나타났다고 예상할 수 있기 때문에","correct":true},{"t":"앞에 있었던 일은 중심 사건과 아무 관계가 없기 때문에","mis":"K4-2-u6-X35"}],"mis":"K4-2-u6-X35","explanation":["중심 사건을 먼저 붙잡아요.","그 앞의 일은 원인, 그 뒤의 일은 결과가 될 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["[이전에 있었던 일] 근처 동물원에서 얼룩말이 탈출했을 것이다.","[중심 사건] 얼룩말이 사람들이 사는 주택가에 나타났다.","[뒤에 벌어진 일] 얼룩말이 번잡한 도심의 모습에 놀라","사람들을 공격하거나 여러 물건을 망가뜨렸을 것이다."],"numbered":false,"title":"중심 사건의 앞뒤 예상 — 『국어』 258쪽 5번 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#4','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C57',1,'ox','auto','『국어』 261쪽에 따르면 방 씨 규수는 뒷날 이순신 장군과 혼인했어요.',ARRAY['K4-2-u6-X18']::text[],false,'{"seq":4,"concept":"K4-2-u6-C57","difficulty":1,"kind":"ox","stem":"『국어』 261쪽에 따르면 방 씨 규수는 뒷날 이순신 장군과 혼인했어요.","answer":"O","reason_options":[{"t":"『국어』 261쪽에 방 씨 규수가 뒷날 이순신 장군과 혼인했다고 나오기 때문에","correct":true},{"t":"방 씨 규수는 이야기 속에서만 있는 사람이라 혼인 이야기는 나오지 않기 때문에","mis":"K4-2-u6-X18"}],"mis":"K4-2-u6-X18","explanation":["방 씨 규수는 방진의 딸이에요.","뒷날 이순신 장군과 혼인했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#5','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C58',1,'ox','auto','실베스터가 조약돌을 땅 위에 내려놓고 「다시 비가 오면 좋겠어.」라고 말하자 비가 쏟아졌어요.',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":5,"concept":"K4-2-u6-C58","difficulty":1,"kind":"ox","stem":"실베스터가 조약돌을 땅 위에 내려놓고 「다시 비가 오면 좋겠어.」라고 말하자 비가 쏟아졌어요.","answer":"X","reason_options":[{"t":"돌을 내려놓았을 때는 아무 일도 없었고, 손에 쥐고 같은 말을 하자 비가 왔기 때문에","correct":true},{"t":"요술 조약돌은 어디에 있든 소원을 들어주기 때문에","mis":"K4-2-u6-X08"}],"mis":"K4-2-u6-X08","explanation":["돌을 땅에 내려놓고 말했을 때는 아무 일도 일어나지 않았어요.","손에 쥐고 말하자 하늘이 어두워지며 비가 쏟아졌어요.","그래서 X예요."],"asset":{"type":"passage","lines":["(간추림) 꼬마 당나귀 실베스터는 모양과 색깔이 특이한 조약돌 모으기를 좋아했다.","(간추림) 비 오는 토요일, 시냇가에서 새빨갛고 동그란 조약돌 하나를 찾아냈다.","“아, 제발 비 좀 그만 왔으면.”","(간추림) 그러자 비가 한순간에 딱 그쳤다.","(간추림) 돌을 땅 위에 내려놓고 말했을 때는 아무 일도 일어나지 않았지만,","(간추림) 돌을 손에 쥐고 같은 말을 하자 비가 억수같이 쏟아졌다."],"title":"「당나귀 실베스터와 요술 조약돌」 앞부분 — 『국어』 264~265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#6','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C59',1,'ox','auto','때때롱은 호박을 따 간 대신 돌담 위에 호박씨를 놓고 갔어요.',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":6,"concept":"K4-2-u6-C59","difficulty":1,"kind":"ox","stem":"때때롱은 호박을 따 간 대신 돌담 위에 호박씨를 놓고 갔어요.","answer":"O","reason_options":[{"t":"이튿날 아침 돌담 위 종이 봉지에 호박씨 다섯 개가 들어 있었기 때문에","correct":true},{"t":"때때롱은 아무것도 남기지 않고 호박만 가져갔기 때문에","mis":"K4-2-u6-X08"}],"mis":"K4-2-u6-X08","explanation":["때때롱은 더 맛있는 호박씨를 얹어 놓고 왔다고 했어요.","새달이가 가 보니 정말 호박씨가 있었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 그날 밤, 때때롱이 새달이네 호박을 따다가 호박죽을 끓여 먹었다고 했다.","(간추림) 새달이는 화가 나고 기가 막혔다.","(간추림) 때때롱은 화내지 말라며, 대신 돌담 위에 호박씨를 놓고 왔으니 내년에 심어 보라고 했다.","(간추림) 이튿날 아침 돌담 위 종이 봉지에 예쁜 호박씨 다섯 개가 들어 있었다."],"title":"「랑랑별 때때롱」 — 『국어』 273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#7','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C60',1,'mc','auto','「랑랑별 때때롱」에 나온 ‘씨호박’은 어떤 호박인가요?',ARRAY['K4-2-u6-X53','K4-2-u6-X08']::text[],false,'{"seq":7,"concept":"K4-2-u6-C60","difficulty":1,"kind":"mc","stem":"「랑랑별 때때롱」에 나온 ‘씨호박’은 어떤 호박인가요?","options":[{"t":"씨를 받기 위해 잘 익은 다음에 따는 호박","correct":true},{"t":"호박죽을 끓이려고 일찍 딴 호박","mis":"K4-2-u6-X53"},{"t":"씨가 하나도 없는 호박","mis":"K4-2-u6-X53"},{"t":"랑랑별에서만 자라는 호박","mis":"K4-2-u6-X08"}],"explanation":["아빠는 없어진 호박이 씨호박 하려던 것이라고 했어요.","씨호박은 씨를 받으려고 잘 익힌 뒤 따는 호박이에요.","그래서 엄마가 더 아까워했어요."],"asset":{"type":"passage","lines":["● 씨호박: 씨를 받기 위해 잘 익은 다음에 따는 호박.","● 곧이듣다: 남의 말을 듣고 그대로 믿다.","● 갈무리하다: 물건 따위를 잘 정리하거나 간수하다.","● 흉측하다: 생김새가 몹시 험상궂고 무섭다."],"numbered":false,"title":"낱말 풀이 — 『국어』 272~276쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#8','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C62',1,'mc','auto','기초 다지기 3 글씨 쓰기 낱말이에요. 받침을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u6-X46']::text[],false,'{"seq":8,"concept":"K4-2-u6-C62","difficulty":1,"kind":"mc","stem":"기초 다지기 3 글씨 쓰기 낱말이에요. 받침을 바르게 쓴 것은 무엇인가요?","options":[{"t":"읊조리다","correct":true},{"t":"읍조리다","mis":"K4-2-u6-X46"},{"t":"을조리다","mis":"K4-2-u6-X46"},{"t":"읖조리다","mis":"K4-2-u6-X46"}],"explanation":["「읊조리다」는 받침에 ㄹ과 ㅍ이 함께 들어가요.","소리 나는 대로 쓰지 않아요.","겹받침을 그대로 바르게 써요."],"asset":{"type":"passage","lines":["겉핥기 · 훑다 · 읊조리다","닳다 · 싫증 · 옳다 · 끓다"],"title":"기초 다지기 3 글씨 쓰기 — 『국어』 287쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#9','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C14',2,'mc','auto','「도경이가 겪은 일」 정리에서 맨 처음 원인이 된 일은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X02','K4-2-u6-X18']::text[],false,'{"seq":9,"concept":"K4-2-u6-C14","difficulty":2,"kind":"mc","stem":"「도경이가 겪은 일」 정리에서 맨 처음 원인이 된 일은 무엇인가요?","options":[{"t":"이어달리기 시합에서 우리 편이 뒤처지기 시작했다","correct":true},{"t":"지수는 발목에 석고 붕대를 하게 됐다","mis":"K4-2-u6-X01"},{"t":"발이 엉키면서 지수와 함께 넘어졌다","mis":"K4-2-u6-X02"},{"t":"나와 지수가 같은 편이 되었다","mis":"K4-2-u6-X18"}],"explanation":["우리 편이 뒤처지자 도경이는 더 빠르게 달렸어요.","그러다 발이 엉켜 함께 넘어졌어요.","석고 붕대는 마지막 결과예요."],"asset":{"type":"passage","lines":["이어달리기 시합에서 우리 편이 뒤처지기 시작했다.","→ 나는 상대편인 지수를 따라잡기 위해 더욱 빠르게 달렸다.","→ 발이 엉키면서 지수와 함께 넘어졌다.","→ 지수는 발목에 석고 붕대를 하게 됐다."],"numbered":false,"title":"『국어활동』 83쪽 예시 답안에 실린 「도경이가 겪은 일」 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#10','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C33',2,'mc','auto','「랑랑별 때때롱」에서 일이 일어난 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u6-X19']::text[],false,'{"seq":10,"concept":"K4-2-u6-C33","difficulty":2,"kind":"mc","stem":"「랑랑별 때때롱」에서 일이 일어난 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"호박을 몰래 따 감 → 호박이 없어진 것을 알고 놀람 → 호박죽을 먹었다고 말함 → 호박씨를 내년에 심기로 함","correct":true},{"t":"호박이 없어진 것을 알고 놀람 → 호박을 몰래 따 감 → 호박씨를 내년에 심기로 함 → 호박죽을 먹었다고 말함","mis":"K4-2-u6-X19"},{"t":"호박죽을 먹었다고 말함 → 호박을 몰래 따 감 → 호박이 없어진 것을 알고 놀람 → 호박씨를 내년에 심기로 함","mis":"K4-2-u6-X19"},{"t":"호박씨를 내년에 심기로 함 → 호박이 없어진 것을 알고 놀람 → 호박을 몰래 따 감 → 호박죽을 먹었다고 말함","mis":"K4-2-u6-X19"}],"explanation":["한밤중에 때때롱이 호박을 몰래 따 갔어요.","다음 날 아침 없어진 것을 알았고, 그날 밤 때때롱이 호박죽 이야기를 했어요.","그 뒤 호박씨를 갈무리해 내년에 심기로 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#11','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C26',2,'mc','auto','「인물의 성격을 알면 인물이 앞으로 어떤 행동을 할지 예상할 수 있어.」라는 방법을 쓴 상상으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X23','K4-2-u6-X52','K4-2-u6-X24']::text[],false,'{"seq":11,"concept":"K4-2-u6-C26","difficulty":2,"kind":"mc","stem":"「인물의 성격을 알면 인물이 앞으로 어떤 행동을 할지 예상할 수 있어.」라는 방법을 쓴 상상으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"겁이 많고 쉽게 당황하는 실베스터라면 다시 당나귀가 된 뒤에도 위험한 일 앞에서 쉽게 놀랄 것이다","correct":true},{"t":"겁이 많은 실베스터가 까닭 없이 사자를 찾아가 싸워 이길 것이다","mis":"K4-2-u6-X23"},{"t":"바위가 된 실베스터가 우주로 날아갈 것이다","mis":"K4-2-u6-X52"},{"t":"실베스터가 이야기와 상관없이 학교에 갈 것이다","mis":"K4-2-u6-X24"}],"explanation":["실베스터는 사자 앞에서 놀라고 당황해 말을 더듬었어요.","그 성격이라면 앞으로도 비슷하게 행동할 수 있어요.","성격에 어울리는 행동을 상상해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"인물의 성격을 알면 인물이 앞으로 어떤 행동을 할지 예상할 수 있어."},{"who":"친구 2","text":"성격은 인물의 말과 행동을 보면 알 수 있지."},{"who":"친구 3","text":"앞 이야기와 뒤에 이어질 이야기가 자연스럽게 연결되려면 어떻게 해야 할까?"},{"who":"친구 4","text":"이야기의 흐름을 생각하며 뒤에 이어질 내용을 상상해 보자."},{"who":"친구 5","text":"앞으로 벌어질 일이 자연스러우려면 사건들 사이의 원인과 결과를 연결 지어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#12','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C37',2,'match','auto','『국어』에서 정리한 인물과 그 성격을 바르게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K4-2-u6-C37","difficulty":2,"kind":"match","stem":"『국어』에서 정리한 인물과 그 성격을 바르게 이어 보세요.","pairs":[{"l":"새달이","r":"궁금한 것을 참지 못한다."},{"l":"때때롱","r":"장난치는 것을 좋아한다."},{"l":"실베스터","r":"겁이 많고 쉽게 당황한다."}],"mis":"K4-2-u6-X23","explanation":["새달이는 호박을 어떻게 따 갔는지 끝까지 물었어요.","때때롱은 장난스럽게 대답했어요.","실베스터는 사자 앞에서 놀라 말을 더듬었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#13','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C12',2,'ox','auto','얼룩말이 사람들에게 피해를 주었을 것이라고 예상했는데 실제로는 피해가 없었어요. 그래도 그림에 근거해 원인과 결과를 따진 예상이라면 의미 있는 예상이에요.',ARRAY['K4-2-u6-X55']::text[],false,'{"seq":13,"concept":"K4-2-u6-C12","difficulty":2,"kind":"ox","stem":"얼룩말이 사람들에게 피해를 주었을 것이라고 예상했는데 실제로는 피해가 없었어요. 그래도 그림에 근거해 원인과 결과를 따진 예상이라면 의미 있는 예상이에요.","answer":"O","reason_options":[{"t":"예상은 정답을 찾는 것이 아니라 그림에서 본 내용을 바탕으로 원인과 결과를 따져 보는 것이기 때문에","correct":true},{"t":"실제와 다른 예상은 모두 틀린 예상이기 때문에","mis":"K4-2-u6-X55"}],"mis":"K4-2-u6-X55","explanation":["예상은 저마다 다를 수 있어요.","중요한 것은 그림에 근거해 원인과 결과로 말하는 것이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 얼룩말 세로가 동물원을 탈출해 주택가에 나타났다.","(간추림) 신고를 받고 출동한 경찰과 소방관이 얼룩말을 동물원에 돌려보냈다."],"title":"뉴스 영상의 내용 — 『국어』 259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#14','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C23',2,'mc','auto','『국어』 263쪽처럼 신사임당이나 에디슨 같은 다른 인물의 이야기를 찾아 읽을 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X07','K4-2-u6-X05','K4-2-u6-X18']::text[],false,'{"seq":14,"concept":"K4-2-u6-C23","difficulty":2,"kind":"mc","stem":"『국어』 263쪽처럼 신사임당이나 에디슨 같은 다른 인물의 이야기를 찾아 읽을 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"무슨 일이 일어났는지, 왜 일어났는지, 그래서 어떻게 되었는지를 생각하며 읽는다","correct":true},{"t":"인물의 이름만 외운다","mis":"K4-2-u6-X07"},{"t":"가장 놀라운 장면 하나만 고른다","mis":"K4-2-u6-X05"},{"t":"이야기에 나오지 않은 일도 짝으로 잇는다","mis":"K4-2-u6-X18"}],"explanation":["다른 인물의 이야기에도 원인과 결과가 있어요.","세 가지를 물으며 읽어요.","떠오르는 생각을 친구들과 자유롭게 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#15','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C42',2,'mc','auto','「원인과 결과로 놀이 하기」에서 카드 두 장을 가져갈 수 있는 때는 언제인가요?',ARRAY['K4-2-u6-X34','K4-2-u6-X35']::text[],false,'{"seq":15,"concept":"K4-2-u6-C42","difficulty":2,"kind":"mc","stem":"「원인과 결과로 놀이 하기」에서 카드 두 장을 가져갈 수 있는 때는 언제인가요?","options":[{"t":"두 카드의 그림을 연결해 원인과 결과가 드러나게 말했을 때","correct":true},{"t":"가위바위보에서 이겼을 때","mis":"K4-2-u6-X34"},{"t":"카드를 가장 빨리 뒤집었을 때","mis":"K4-2-u6-X34"},{"t":"두 그림과 상관없는 이야기를 길게 말했을 때","mis":"K4-2-u6-X35"}],"explanation":["가위바위보에서 이기면 카드 두 장을 골라요.","두 그림을 원인과 결과로 이어 말하면 가져가요.","자연스럽게 잇지 못하면 다시 내려놓아요."],"asset":{"type":"passage","lines":["① 그림 카드를 섞어서 그림이 보이지 않게 뒤집어 놓는다.","② 가위바위보를 하여 이긴 친구가 카드 두 장을 고른다.","③ 두 카드의 그림을 연결해 원인과 결과가 드러나게 말하면 두 카드를 가져간다.","④ 자연스럽게 연결하여 말하지 못하면 카드를 다시 내려놓는다.","⑤ 번갈아 가며 놀이를 하여 카드를 많이 가져간 친구가 이긴다.","예: 눈이 내립니다. 그래서 강아지는 밖으로 나가자고 낑낑댔습니다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 1 — 원인과 결과로 놀이 하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#16','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C44',2,'mc','auto','대본 예시 마지막에 당나귀가 「내가 내 잔꾀에 넘어갔구나.」라고 한 까닭은 무엇인가요?',ARRAY['K4-2-u6-X09','K4-2-u6-X08']::text[],false,'{"seq":16,"concept":"K4-2-u6-C44","difficulty":2,"kind":"mc","stem":"대본 예시 마지막에 당나귀가 「내가 내 잔꾀에 넘어갔구나.」라고 한 까닭은 무엇인가요?","options":[{"t":"황소에게 꾀병을 가르쳐 준 탓에 자신이 황소 대신 밭일을 하게 되었기 때문","correct":true},{"t":"밭일이 생각보다 무척 쉬웠기 때문","mis":"K4-2-u6-X09"},{"t":"농부가 당나귀를 칭찬했기 때문","mis":"K4-2-u6-X08"},{"t":"황소가 당나귀를 도와주었기 때문","mis":"K4-2-u6-X08"}],"explanation":["당나귀는 황소에게 아픈 척하는 꾀를 알려 주었어요.","그 꾀를 알아챈 농부가 당나귀에게 밭일을 시켰어요.","자기 꾀 때문에 자기가 힘들어졌어요."],"asset":{"type":"passage","lines":["황소: (바닥에 드러누워 발버둥 치며) 에이, 모르겠다! 오늘 일 안 해요!","농부: (하인을 부르며) 여봐라. 황소 대신 당나귀를 밭으로 데려가거라.","당나귀: (깜짝 놀라며) 어? 뭐라고? 이게 아닌데…….","당나귀: (후회하는 목소리로) 아이고, 힘들다. 내가 내 잔꾀에 넘어갔구나."],"numbered":false,"title":"「당나귀, 황소 그리고 농부」 대본 예시 (소품: 여물통 · 쟁기)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#17','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C9',3,'mc','auto','서윤이가 앞으로 할 행동을 이야기에 근거해 가장 알맞게 예상한 것은 무엇인가요?',ARRAY['K4-2-u6-X13','K4-2-u6-X52','K4-2-u6-X24']::text[],false,'{"seq":17,"concept":"K4-2-u6-C9","difficulty":3,"kind":"mc","stem":"서윤이가 앞으로 할 행동을 이야기에 근거해 가장 알맞게 예상한 것은 무엇인가요?","options":[{"t":"어머니께 왜 늦었는지 설명해서 오해를 풀 것이다","correct":true},{"t":"아무 말 없이 방에 들어가 다시는 남을 돕지 않을 것이다","mis":"K4-2-u6-X13"},{"t":"갑자기 경찰관이 되어 마을을 지킬 것이다","mis":"K4-2-u6-X52"},{"t":"어머니와 함께 놀이공원에 갈 것이다","mis":"K4-2-u6-X24"}],"explanation":["서윤이는 죄송하면서도 억울한 마음이었어요.","오해를 풀려면 늦은 까닭을 설명해야 해요.","예상은 이야기 속 원인과 자연스럽게 이어져야 해요."],"asset":{"type":"passage","lines":["(간추림) 학교를 마치고 오는 길에 혼자 울고 있는 대여섯 살쯤 된 아이를 보았다.","(간추림) 누가 도와주겠지 하고 지나갔다가, 아무도 돕지 않아 아이에게 되돌아갔다.","“집을 못 찾겠어.” “이사 와서 몰라.”","(간추림) 가까운 파출소의 경찰관 아저씨께 아이를 데려다주니 뿌듯한 마음이 들었다.","“서윤아, 도대체 왜 이렇게 늦었어? 어디에서 놀다 온 거니?”","(간추림) 평소보다 한참 늦어 죄송했지만 한편으로 억울한 생각이 들었다."],"title":"「서윤이의 일기」 간추린 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#18','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C41',3,'error','auto','친구가 쓴 「랑랑별 때때롱」의 뒷이야기를 읽고 한 말이에요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u6-X26']::text[],false,'{"seq":18,"concept":"K4-2-u6-C41","difficulty":3,"kind":"error","stem":"친구가 쓴 「랑랑별 때때롱」의 뒷이야기를 읽고 한 말이에요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“원래 이야기와 다르니까 틀렸어. 정답과 똑같이 다시 써.”","correct":true,"mis_target":"K4-2-u6-X26"},{"t":"“호박씨를 심은 일이 원인이 되어 호박이 열리는 결과로 자연스럽게 이어져.”","mis":"K4-2-u6-X26"},{"t":"“장난치기 좋아하지만 착한 때때롱의 성격과도 잘 어울려.”","mis":"K4-2-u6-X26"}],"explanation":["이어질 내용에는 정답이 없어요.","원인과 결과, 인물의 성격에 어울리는지 말해 주어요.","다르게 상상했다고 틀린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#19','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C39',3,'mc','auto','이어질 내용을 상상해 쓴 뒤 스스로 점검할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X28','K4-2-u6-X29','K4-2-u6-X26']::text[],false,'{"seq":19,"concept":"K4-2-u6-C39","difficulty":3,"kind":"mc","stem":"이어질 내용을 상상해 쓴 뒤 스스로 점검할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"이야기의 흐름이 자연스러운지, 너무 장난스럽게만 지어낸 것은 아닌지","correct":true},{"t":"글씨가 예쁜지만","mis":"K4-2-u6-X28"},{"t":"가장 놀라운 장면이 들어갔는지만","mis":"K4-2-u6-X29"},{"t":"친구의 이야기와 똑같은지","mis":"K4-2-u6-X26"}],"explanation":["앞 이야기를 떠올리며 흐름을 점검해요.","너무 장난스럽게만 지어내지 않았는지 살펴요.","스스로 묻고 고치면 더 좋은 이야기가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#20','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C3',3,'ox','auto','생각 열기에서 「개구리는 그냥 파리를 잡아먹을 것 같아.」라고 한 예상은 까닭을 잘 든 예상이에요.',ARRAY['K4-2-u6-X03']::text[],false,'{"seq":20,"concept":"K4-2-u6-C3","difficulty":3,"kind":"ox","stem":"생각 열기에서 「개구리는 그냥 파리를 잡아먹을 것 같아.」라고 한 예상은 까닭을 잘 든 예상이에요.","answer":"X","reason_options":[{"t":"그림에 나온 표정 변화나 입맛을 다시는 모습 같은 근거를 들지 않았기 때문에","correct":true},{"t":"예상할 때는 까닭이 필요 없기 때문에","mis":"K4-2-u6-X03"}],"mis":"K4-2-u6-X03","explanation":["예상한 까닭은 그림에 나와 있는 것에서 찾아요.","「그냥」은 까닭이 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["[그림] 배고픈 개구리가 시무룩한 표정을 짓고 있다.","[그림] 개구리 눈앞에 파리가 나타나자 생기 있는 표정으로 바뀌었다.","[그림] 개구리가 파리를 바라보며 입맛을 다시고 있다."],"numbered":false,"title":"생각 열기 「앞으로 어떤 일이 일어날까요?」 — 『국어』 253쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#21','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C26',3,'mc','auto','『국어활동』 89쪽 예시 답안이 「두근두근」의 앞 이야기와 잘 이어지는 까닭은 무엇인가요?',ARRAY['K4-2-u6-X32','K4-2-u6-X29','K4-2-u6-X28']::text[],false,'{"seq":21,"concept":"K4-2-u6-C26","difficulty":3,"kind":"mc","stem":"『국어활동』 89쪽 예시 답안이 「두근두근」의 앞 이야기와 잘 이어지는 까닭은 무엇인가요?","options":[{"t":"빵을 맛깔스럽게 만드는 브레드 씨가 빵으로 동물을 도우며 만나게 된다는 흐름과 이어지기 때문","correct":true},{"t":"브레드 씨가 갑자기 대담한 성격으로 바뀌었기 때문","mis":"K4-2-u6-X32"},{"t":"양이 가장 귀여운 동물이기 때문","mis":"K4-2-u6-X29"},{"t":"문장이 짧고 간단하기 때문","mis":"K4-2-u6-X28"}],"explanation":["브레드 씨는 부끄러움이 많지만 빵을 잘 만들어요.","빵 덕분에 여러 동물을 만나 빵을 나누어요.","예시 답안도 그 성격과 흐름을 따랐어요."],"asset":{"type":"passage","lines":["문밖에는 양이 추위에 떨며 오들오들.","“길을 잃었는데 맛있는 냄새가 나서. 아휴, 너무 추워.”","브레드 씨는 양에게 호빵을 구워 주었어요.","양은 따끈따끈한 호빵을 먹고 금세 몸이 따뜻해졌어요.","그 뒤로 양은 종종 브레드 씨를 찾아왔어요."],"title":"『국어활동』 89쪽 예시 답안 — 「두근두근」의 이어질 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#22','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C58',3,'mc','auto','「당나귀 실베스터와 요술 조약돌」의 원래 이야기에서 실베스터가 다시 당나귀가 될 수 있었던 것은 누구 덕분인가요?',ARRAY['K4-2-u6-X08']::text[],false,'{"seq":22,"concept":"K4-2-u6-C58","difficulty":3,"kind":"mc","stem":"「당나귀 실베스터와 요술 조약돌」의 원래 이야기에서 실베스터가 다시 당나귀가 될 수 있었던 것은 누구 덕분인가요?","options":[{"t":"딸기 언덕에서 요술 조약돌을 발견한 엄마, 아빠","correct":true},{"t":"물, 흙, 바람, 나무","mis":"K4-2-u6-X08"},{"t":"사자","mis":"K4-2-u6-X08"},{"t":"마을 친구들","mis":"K4-2-u6-X08"}],"explanation":["엄마, 아빠는 실베스터를 그리워하며 딸기 언덕으로 소풍을 갔어요.","그곳에서 요술 조약돌을 발견했어요.","물, 흙, 바람, 나무는 『국어』 270쪽에서 상상한 이야기예요."],"asset":{"type":"passage","lines":["(간추림) 봄이 오자 실베스터를 그리워하던 엄마, 아빠가 딸기 언덕으로 소풍을 갔다.","(간추림) 바위가 된 실베스터 위에 소풍 자리를 마련하다가 그 곁에서 요술 조약돌을 발견했다.","(간추림) 조약돌을 보며 실베스터를 생각하던 엄마, 아빠 덕분에 실베스터는 다시 당나귀가 되었다."],"title":"「당나귀 실베스터와 요술 조약돌」 원래 이야기의 끝 (『국어활동』 90~99쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#23','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C23',4,'essay','teacher','「포도 치마」를 듣고 원인과 결과를 정리한 뒤, 치맛값을 갚게 된 여인이 이어서 할 일을 예상해 쓰고 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C23","difficulty":4,"kind":"essay","stem":"「포도 치마」를 듣고 원인과 결과를 정리한 뒤, 치맛값을 갚게 된 여인이 이어서 할 일을 예상해 쓰고 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 정리 — 국물을 쏟아 얼룩이 생김 → 신사임당이 포도 그림을 그림 → 멋진 치마가 탄생함 → 비싼 값에 팔려 치맛값을 갚음. 이어서 할 일 — 여인은 신사임당을 찾아가 고맙다고 인사할 것 같다. 까닭 — 발을 동동 구르며 눈물을 글썽일 만큼 걱정했던 일을 신사임당 덕분에 해결했기 때문이다.","scoring_points":["일의 차례와 원인·결과를 정리했는가","여인이 이어서 할 일을 예상했는가","그렇게 생각한 까닭을 이야기에서 찾아 썼는가"]},"explanation":["먼저 일의 차례와 원인·결과를 정리해요.","마지막 결과가 다시 원인이 되어 무슨 일이 생길지 예상해요.","까닭은 이야기에 나온 인물의 마음과 행동에서 찾아요."],"asset":{"type":"passage","lines":["(간추림) 마을 잔칫날, 한 여인이 빌려 입은 치마에 국물을 쏟아 큰 얼룩이 생겼다.","(간추림) 신사임당은 여인을 달래며 치마를 벗어서 건네 달라고 했다.","(간추림) 신사임당은 정성스럽게 먹을 갈더니 치마폭에 붓으로 그림을 그렸다.","“얼룩이 어느새 멋진 포도송이로 바뀌었네!”","(간추림) 아름다운 치마는 비싼 값에 팔려 여인은 빌린 치맛값을 갚을 수 있었다."],"title":"「포도 치마」 간추린 내용 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#24','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C39',4,'essay','teacher','「두근두근」에서 또 다른 동물이 브레드 씨를 찾아오는 이어질 내용을 상상해 쓰세요. 동물의 고민, 브레드 씨의 빵이 고민을 해결하는 과정, 그 결과가 드러나야 해요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C39","difficulty":4,"kind":"essay","stem":"「두근두근」에서 또 다른 동물이 브레드 씨를 찾아오는 이어질 내용을 상상해 쓰세요. 동물의 고민, 브레드 씨의 빵이 고민을 해결하는 과정, 그 결과가 드러나야 해요.","answer_guide":{"answer":"예: 비 오는 날 아기 오리가 흠뻑 젖은 채 찾아왔어요. 「엄마를 잃어버렸는데 배도 고파요.」 브레드 씨는 얼굴이 빨개져 말은 잘 못했지만 따뜻한 우유 빵을 구워 주었어요. 빵 냄새가 퍼지자 아기 오리를 찾던 엄마 오리가 냄새를 따라와 아기 오리를 만났어요. 그 뒤로 오리 가족은 종종 빵집에 들렀어요.","scoring_points":["동물의 고민을 썼는가","빵이 고민을 해결하는 과정과 결과가 원인과 결과로 이어지는가","부끄러움을 많이 타는 브레드 씨의 성격과 어울리는가"]},"explanation":["찾아온 동물의 고민을 정해요.","빵 덕분에 무엇이 해결되는지 원인과 결과로 이어요.","브레드 씨의 성격을 살려요."],"asset":{"type":"passage","lines":["(간추림) 「두근두근」의 브레드 씨는 부끄러움을 많이 타는 소심한 사람이다.","(간추림) 하지만 브레드 씨는 빵을 맛깔스럽게 만들 수 있다.","(간추림) 빵 만드는 실력 때문에 브레드 씨는 여러 동물을 만나 빵을 나누게 된다."],"title":"『국어활동』 84~88쪽 「두근두근」 인물과 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_c#25','kor',4,2,'u6','','tb_g4_2_kor_u6_review_c','unit_review','K4-2-u6-C53',4,'essay','teacher','「상상한 이야기로 계단책 만들기」처럼, 자신이 좋아하는 이야기 하나를 골라 처음·가운데·끝을 한 문장씩 요약하고, 그 흐름에 이어지는 뒷이야기를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C53","difficulty":4,"kind":"essay","stem":"「상상한 이야기로 계단책 만들기」처럼, 자신이 좋아하는 이야기 하나를 골라 처음·가운데·끝을 한 문장씩 요약하고, 그 흐름에 이어지는 뒷이야기를 쓰세요.","answer_guide":{"answer":"예: 이야기 — 「흥부와 놀부」. 처음 — 흥부가 다친 제비 다리를 치료해 주었다. 가운데 — 제비가 준 박씨에서 금은보화가 나와 흥부는 부자가 되었다. 끝 — 제비 다리를 일부러 부러뜨린 놀부는 도깨비에게 혼쭐이 났다. 뒷이야기 — 혼쭐이 난 놀부는 흥부를 찾아가 잘못을 빌었고, 흥부는 놀부를 따뜻하게 맞아 함께 살았다.","scoring_points":["처음·가운데·끝을 요약해 흐름을 정리했는가","뒷이야기가 그 흐름과 이어지는가","원인과 결과가 드러나는가"]},"explanation":["처음·가운데·끝을 요약하면 흐름이 보여요.","그 흐름에서 뒷이야기를 이어 써요.","같은 이야기를 고른 친구와 비교해 봐요."],"asset":{"type":"passage","lines":["① 자신이 좋아하는 이야기를 하나 골라 뒷이야기를 상상해 본다.","② 계단책을 만든다.","③ 가장 앞 장은 표지로, 다음 세 장에는 처음·가운데·끝 이야기를 요약해 흐름을 정리한다.","④ 교실에 전시하고, 같은 이야기를 고른 친구와 상상한 뒷이야기를 비교한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 상상한 이야기로 계단책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#1','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C1',1,'sa','auto','친구 2가 「그래서 나는 장갑을 챙겨 밖으로 나갔습니다.」라고 이어 말했어요. 그 원인이 된 친구 1의 말에서 창밖에 소복하게 쌓여 있던 것은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u6-C1","difficulty":1,"kind":"sa","stem":"친구 2가 「그래서 나는 장갑을 챙겨 밖으로 나갔습니다.」라고 이어 말했어요. 그 원인이 된 친구 1의 말에서 창밖에 소복하게 쌓여 있던 것은 무엇인지 쓰세요.","answer":["흰 눈","눈"],"explanation":["친구 1은 창밖에 흰 눈이 소복하게 쌓여 있었다고 했어요.","눈이 쌓여서 장갑을 챙겨 나갔어요.","앞 문장이 뒤 문장의 원인이 되었어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"오늘 아침에 일어나 창밖을 내다보니 흰 눈이 소복하게 쌓여 있었습니다."},{"who":"친구 2","text":"그래서 나는 장갑을 챙겨 밖으로 나갔습니다."},{"who":"친구 3","text":"그래서……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#2','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C55',1,'sa','auto','소연이네 반 친구들이 방울토마토를 기른 곳은 어디인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u6-C55","difficulty":1,"kind":"sa","stem":"소연이네 반 친구들이 방울토마토를 기른 곳은 어디인지 쓰세요.","answer":["옥상 텃밭","옥상","텃밭"],"explanation":["영상은 학교에서 일어난 일이에요.","친구들은 옥상 텃밭에서 방울토마토를 길렀어요.","장소를 붙잡으면 일어난 일을 파악하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#3','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C56',1,'mc','auto','『국어』 258쪽 5번 예시에서 중심 사건 뒤에 벌어질 일로 예상한 것은 무엇인가요?',ARRAY['K4-2-u6-X01','K4-2-u6-X19','K4-2-u6-X13']::text[],false,'{"seq":3,"concept":"K4-2-u6-C56","difficulty":1,"kind":"mc","stem":"『국어』 258쪽 5번 예시에서 중심 사건 뒤에 벌어질 일로 예상한 것은 무엇인가요?","options":[{"t":"얼룩말이 도심의 모습에 놀라 사람들을 공격하거나 물건을 망가뜨렸을 것이다","correct":true},{"t":"근처 동물원에서 얼룩말이 탈출했을 것이다","mis":"K4-2-u6-X01"},{"t":"얼룩말이 사람들이 사는 주택가에 나타났다","mis":"K4-2-u6-X19"},{"t":"얼룩말이 주택가에서 새끼를 낳았을 것이다","mis":"K4-2-u6-X13"}],"explanation":["동물원에서 탈출한 일은 중심 사건 앞의 일이에요.","주택가에 나타난 것은 중심 사건이에요.","뒤에 벌어질 일은 중심 사건의 결과로 예상한 것이에요."],"asset":{"type":"passage","lines":["[이전에 있었던 일] 근처 동물원에서 얼룩말이 탈출했을 것이다.","[중심 사건] 얼룩말이 사람들이 사는 주택가에 나타났다.","[뒤에 벌어진 일] 얼룩말이 번잡한 도심의 모습에 놀라","사람들을 공격하거나 여러 물건을 망가뜨렸을 것이다."],"numbered":false,"title":"중심 사건의 앞뒤 예상 — 『국어』 258쪽 5번 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#4','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C57',1,'mc','auto','『국어』 261쪽 낱말 풀이에서 ‘규수’의 뜻은 무엇인가요?',ARRAY['K4-2-u6-X53']::text[],false,'{"seq":4,"concept":"K4-2-u6-C57","difficulty":1,"kind":"mc","stem":"『국어』 261쪽 낱말 풀이에서 ‘규수’의 뜻은 무엇인가요?","options":[{"t":"혼인하지 않은 남의 집 딸을 정중하게 이르는 말","correct":true},{"t":"나이가 많은 할머니를 이르는 말","mis":"K4-2-u6-X53"},{"t":"활을 잘 쏘는 사람을 이르는 말","mis":"K4-2-u6-X53"},{"t":"집안일을 돕는 사람을 이르는 말","mis":"K4-2-u6-X53"}],"explanation":["‘방 씨 규수’는 방 씨 집안의 딸을 높여 이른 말이에요.","규수는 혼인하지 않은 남의 집 딸을 정중하게 이르는 말이에요.","낱말 풀이를 보고 뜻을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#5','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C58',1,'mc','auto','실베스터가 굶주린 사자를 만나 바위가 된 곳은 어디인가요?',ARRAY['K4-2-u6-X19','K4-2-u6-X08']::text[],false,'{"seq":5,"concept":"K4-2-u6-C58","difficulty":1,"kind":"mc","stem":"실베스터가 굶주린 사자를 만나 바위가 된 곳은 어디인가요?","options":[{"t":"딸기 언덕","correct":true},{"t":"시냇가","mis":"K4-2-u6-X19"},{"t":"귀리죽 마을의 집 안","mis":"K4-2-u6-X08"},{"t":"학교 운동장","mis":"K4-2-u6-X08"}],"explanation":["실베스터는 부지런히 딸기 언덕을 넘어가고 있었어요.","그곳에서 굶주린 사자를 만났어요.","바위가 된 실베스터는 딸기 언덕에서 꼼짝도 못 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#6','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C59',1,'sa','auto','때때롱은 새달이네 호박을 따다가 무엇을 끓여 먹었다고 했는지 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u6-C59","difficulty":1,"kind":"sa","stem":"때때롱은 새달이네 호박을 따다가 무엇을 끓여 먹었다고 했는지 쓰세요.","answer":["호박죽"],"explanation":["때때롱은 그날 밤 새달이를 불렀어요.","호박을 따다가 호박죽을 끓여 먹었다고 했어요.","새달이는 화도 나고 어이가 없었어요."],"asset":{"type":"passage","lines":["(간추림) 그날 밤, 때때롱이 새달이네 호박을 따다가 호박죽을 끓여 먹었다고 했다.","(간추림) 새달이는 화가 나고 기가 막혔다.","(간추림) 때때롱은 화내지 말라며, 대신 돌담 위에 호박씨를 놓고 왔으니 내년에 심어 보라고 했다.","(간추림) 이튿날 아침 돌담 위 종이 봉지에 예쁜 호박씨 다섯 개가 들어 있었다."],"title":"「랑랑별 때때롱」 — 『국어』 273쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#7','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C60',1,'match','auto','「랑랑별 때때롱」의 표현과 그 뜻을 바르게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u6-C60","difficulty":1,"kind":"match","stem":"「랑랑별 때때롱」의 표현과 그 뜻을 바르게 이어 보세요.","pairs":[{"l":"탐이 나다","r":"가지거나 차지하고 싶은 마음이 생기다"},{"l":"혀를 차다","r":"마음이 언짢거나 불만스러움을 나타내다"},{"l":"어이가 없다","r":"일이 너무 뜻밖이어서 기가 막히는 듯하다"}],"mis":"K4-2-u6-X53","explanation":["호박을 누가 훔쳐 갔을까 하는 엄마의 말에서 탐이 나다를 찾아요.","서운해하는 엄마의 모습에서 혀를 차다를 찾아요.","화도 나고 기가 막힌 새달이의 마음에서 어이가 없다를 찾아요."],"asset":{"type":"passage","lines":["보기: 어이가 없다 · 탐이 나다 · 혀를 차다","㉮ 가지거나 차지하고 싶은 마음이 생기다.","㉯ 마음이 언짢거나 불만스러움을 나타내다.","㉰ 일이 너무 뜻밖이어서 기가 막히는 듯하다."],"numbered":false,"title":"낱말 알기 — 『국어』 277쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#8','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C48',1,'ox','auto','‘(으)로써’는 어떤 물건의 재료나 원료, 수단이나 도구를 나타낼 때 써요.',ARRAY['K4-2-u6-X42']::text[],false,'{"seq":8,"concept":"K4-2-u6-C48","difficulty":1,"kind":"ox","stem":"‘(으)로써’는 어떤 물건의 재료나 원료, 수단이나 도구를 나타낼 때 써요.","answer":"O","reason_options":[{"t":"「말로써 천 냥 빚을 갚는다」에서 말이 빚을 갚는 수단이기 때문에","correct":true},{"t":"‘(으)로써’는 신분이나 자격을 나타내기 때문에","mis":"K4-2-u6-X42"}],"mis":"K4-2-u6-X42","explanation":["‘(으)로서’는 신분이나 자격을 나타내요.","‘(으)로써’는 재료나 원료, 수단이나 도구를 나타내요.","그래서 O예요."],"asset":{"type":"passage","lines":["나는 학급 회장(으로서, 으로써) 맡은 일에 최선을 다하고 있다.","말(로서, 로써) 천 냥 빚을 갚는다.","※ ‘(으)로서’는 신분 또는 자격을 나타내고,","‘(으)로써’는 어떤 물건의 재료나 원료, 수단이나 도구를 나타낼 때 사용해요."],"title":"기초 다지기 1 — 『국어』 286쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#9','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C2',2,'mc','auto','「흥부와 놀부」에서 ④ 놀부가 제비 다리를 일부러 부러뜨린 원인은 무엇인가요?',ARRAY['K4-2-u6-X18','K4-2-u6-X01','K4-2-u6-X22']::text[],false,'{"seq":9,"concept":"K4-2-u6-C2","difficulty":2,"kind":"mc","stem":"「흥부와 놀부」에서 ④ 놀부가 제비 다리를 일부러 부러뜨린 원인은 무엇인가요?","options":[{"t":"흥부가 박에서 나온 금은보화로 큰 부자가 된 것을 시샘했기 때문","correct":true},{"t":"제비가 놀부를 물었기 때문","mis":"K4-2-u6-X18"},{"t":"놀부가 도깨비들에게 혼쭐이 났기 때문","mis":"K4-2-u6-X01"},{"t":"흥부가 다친 제비 다리를 치료해 주었기 때문","mis":"K4-2-u6-X22"}],"explanation":["④ 바로 앞에 흥부가 큰 부자가 된 일이 있어요.","놀부는 이를 시샘해서 제비 다리를 부러뜨렸어요.","도깨비에게 혼쭐이 난 것은 그 뒤의 결과예요."],"asset":{"type":"passage","lines":["① 흥부는 다친 제비 다리를 정성스레 치료해 주었습니다.","② 제비는 이듬해 흥부에게 박씨를 물어다 주었습니다.","③ 박에서 나온 금은보화로 흥부는 큰 부자가 되었습니다.","④ 이를 시샘한 놀부는 제비 다리를 일부러 부러뜨렸습니다.","⑤ 제비가 이듬해에 놀부에게 박씨를 물어다 주었습니다.","⑥ 놀부는 박에서 나온 도깨비들에게 혼쭐이 났습니다."],"numbered":false,"title":"익숙한 이야기에서 원인과 결과 찾기 — 「흥부와 놀부」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#10','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C17',2,'mc','auto','「방 씨 규수의 이야기」에서 이야기에는 나중에 나오지만 실제로는 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K4-2-u6-X19']::text[],false,'{"seq":10,"concept":"K4-2-u6-C17","difficulty":2,"kind":"mc","stem":"「방 씨 규수의 이야기」에서 이야기에는 나중에 나오지만 실제로는 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"도둑들과 한편인 하인이 방진의 화살을 훔쳐 간 일","correct":true},{"t":"도둑들이 집 안마당까지 쳐들어온 일","mis":"K4-2-u6-X19"},{"t":"방 씨 규수가 대나무를 내던진 일","mis":"K4-2-u6-X19"},{"t":"도둑들이 놀라 달아난 일","mis":"K4-2-u6-X19"}],"explanation":["이야기는 도둑들이 쳐들어온 장면부터 시작해요.","화살을 미리 훔쳐 간 일은 그 뒤에 까닭으로 밝혀져요.","시간의 흐름으로는 하인이 화살을 훔친 일이 가장 먼저예요."],"asset":{"type":"passage","lines":["(간추림) 방 씨 규수의 아버지 방진은 백발백중의 활쏘기 솜씨로 소문이 자자했다.","(간추림) 어느 날 밤, 방진의 재산을 탐낸 도둑들이 집 안마당까지 쳐들어왔다.","(간추림) 방진은 활을 쏘며 도둑을 내쫓으려 했지만 금세 화살이 떨어졌다.","(간추림) 도둑들이 미리 하인에게 손을 써서 화살을 훔쳐 가게 했기 때문이다.","“아버지, 여기 화살이 있습니다.”","(간추림) 방 씨 규수는 베 짜는 데 쓰던 대나무를 한 아름 대청마루 위에 내던졌다.","(간추림) 화살이 쏟아지는 소리 같아서 깜짝 놀란 도둑들은 도망가 버렸다.","(간추림) 이 일이 널리 전파되어 방 씨 규수의 명성이 더욱 높아졌다."],"title":"「방 씨 규수의 이야기」 간추린 내용 (듣기 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#11','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C5',2,'mc','auto','「랑랑별 때때롱」이나 「당나귀 실베스터와 요술 조약돌」의 이어질 내용을 상상하려고 해요. 맨 먼저 살펴볼 것은 무엇인가요?',ARRAY['K4-2-u6-X05','K4-2-u6-X06','K4-2-u6-X52']::text[],false,'{"seq":11,"concept":"K4-2-u6-C5","difficulty":2,"kind":"mc","stem":"「랑랑별 때때롱」이나 「당나귀 실베스터와 요술 조약돌」의 이어질 내용을 상상하려고 해요. 맨 먼저 살펴볼 것은 무엇인가요?","options":[{"t":"앞 이야기에서 어떤 일이 왜 일어났는지","correct":true},{"t":"가장 놀라운 일이 무엇일지","mis":"K4-2-u6-X05"},{"t":"어떻게 하면 가장 길게 쓸지","mis":"K4-2-u6-X06"},{"t":"어떻게 하면 가장 장난스러울지","mis":"K4-2-u6-X52"}],"explanation":["이어질 내용은 앞 이야기에서 시작해요.","앞에서 무슨 일이 왜 일어났는지 살펴요.","놀라움이나 길이는 먼저 생각할 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#12','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C26',2,'mc','auto','『국어활동』 84~88쪽 「두근두근」의 브레드 씨는 어떤 성격인가요?',ARRAY['K4-2-u6-X23']::text[],false,'{"seq":12,"concept":"K4-2-u6-C26","difficulty":2,"kind":"mc","stem":"『국어활동』 84~88쪽 「두근두근」의 브레드 씨는 어떤 성격인가요?","options":[{"t":"부끄러움을 많이 타는 소심한 성격","correct":true},{"t":"무엇이든 따지기 좋아하는 성격","mis":"K4-2-u6-X23"},{"t":"장난치기를 좋아하는 성격","mis":"K4-2-u6-X23"},{"t":"겁 없이 모험을 즐기는 성격","mis":"K4-2-u6-X23"}],"explanation":["브레드 씨는 누군가를 만나는 데 두려움을 느낄 정도로 부끄러움이 많아요.","하지만 빵을 맛깔스럽게 만들 수 있어요.","이 성격을 생각하며 이어질 내용을 상상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#13','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C9',2,'mc','auto','방울토마토가 없어진 원인을 서로 다르게 예상했다면, 뒤에 이어질 결과는 어떻게 되나요?',ARRAY['K4-2-u6-X09','K4-2-u6-X35','K4-2-u6-X10']::text[],false,'{"seq":13,"concept":"K4-2-u6-C9","difficulty":2,"kind":"mc","stem":"방울토마토가 없어진 원인을 서로 다르게 예상했다면, 뒤에 이어질 결과는 어떻게 되나요?","options":[{"t":"예상한 원인에 따라 뒤에 이어질 결과도 달라진다","correct":true},{"t":"원인이 달라도 결과는 언제나 같다","mis":"K4-2-u6-X09"},{"t":"원인을 바꾸면 이야기가 끝난다","mis":"K4-2-u6-X35"},{"t":"원인은 하나로 정해져 있어 다르게 예상할 수 없다","mis":"K4-2-u6-X10"}],"explanation":["새가 먹었다고 보면 허수아비를 세우겠지요.","누군가 가져갔다고 보면 경고 팻말을 세우겠지요.","원인이 달라지면 결과도 달라져요."],"asset":{"type":"passage","lines":["(원인) 새가 방울토마토를 쪼아 먹었다.","→ (결과) 허수아비를 세워 새를 쫓을 수 있도록 한다.","(원인) 방울토마토를 누군가 가져갔다.","→ (결과) 경고 팻말을 세워 가져가지 못하도록 한다."],"numbered":false,"title":"예상한 원인에 따라 달라지는 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#14','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C23',2,'mc','auto','「포도 치마」에서 사람들이 깜짝 놀란 까닭은 무엇인가요?',ARRAY['K4-2-u6-X22','K4-2-u6-X01']::text[],false,'{"seq":14,"concept":"K4-2-u6-C23","difficulty":2,"kind":"mc","stem":"「포도 치마」에서 사람들이 깜짝 놀란 까닭은 무엇인가요?","options":[{"t":"치마의 얼룩이 어느새 멋진 포도송이 그림으로 바뀌었기 때문","correct":true},{"t":"여인이 치마를 벗어서 건넸기 때문","mis":"K4-2-u6-X22"},{"t":"신사임당이 먹을 갈았기 때문","mis":"K4-2-u6-X22"},{"t":"치마가 비싼 값에 팔렸기 때문","mis":"K4-2-u6-X01"}],"explanation":["신사임당은 치마폭에 붓으로 그림을 그렸어요.","얼룩이 멋진 포도송이로 바뀌었어요.","치마가 팔린 것은 그 뒤의 결과예요."],"asset":{"type":"passage","lines":["(간추림) 마을 잔칫날, 한 여인이 빌려 입은 치마에 국물을 쏟아 큰 얼룩이 생겼다.","(간추림) 신사임당은 여인을 달래며 치마를 벗어서 건네 달라고 했다.","(간추림) 신사임당은 정성스럽게 먹을 갈더니 치마폭에 붓으로 그림을 그렸다.","“얼룩이 어느새 멋진 포도송이로 바뀌었네!”","(간추림) 아름다운 치마는 비싼 값에 팔려 여인은 빌린 치맛값을 갚을 수 있었다."],"title":"「포도 치마」 간추린 내용 (활동지)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#15','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C42',2,'ox','auto','이야기 이어 말하기는 원인과 결과, 시간의 흐름에 맞게 앞 문장에 이어지는 뒤 문장을 말하는 놀이예요.',ARRAY['K4-2-u6-X34']::text[],false,'{"seq":15,"concept":"K4-2-u6-C42","difficulty":2,"kind":"ox","stem":"이야기 이어 말하기는 원인과 결과, 시간의 흐름에 맞게 앞 문장에 이어지는 뒤 문장을 말하는 놀이예요.","answer":"O","reason_options":[{"t":"앞 문장이 까닭이 되는 뒤 문장을 이어 말해야 이야기가 만들어지기 때문에","correct":true},{"t":"가장 길게 말하는 사람이 이기는 놀이이기 때문에","mis":"K4-2-u6-X34"}],"mis":"K4-2-u6-X34","explanation":["놀이 방법에 원인과 결과, 시간의 흐름에 맞게 말하라고 했어요.","길게 말하는 것이 아니라 끊기지 않게 잇는 것이 중요해요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 모둠의 첫 번째 학생이 이야기에서 한 문장을 읽거나 직접 말한다.","2 두 번째 학생이 원인과 결과, 시간의 흐름에 맞게 이어지는 뒤 문장을 말하면서","  자신이 가지고 있는 물건을 한 개 책상 위에 올려놓는다.","3 인원수만큼 물건이 모이면 손을 머리에 올리며 모둠 이름을 외친다.","4 모둠에서 만든 이야기를 발표한다."],"numbered":false,"title":"이야기 이어 말하기 놀이 방법 — 『국어』 282쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#16','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C46',2,'mc','auto','친구들의 역할놀이를 감상한 뒤에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X39','K4-2-u6-X40','K4-2-u6-X50']::text[],false,'{"seq":16,"concept":"K4-2-u6-C46","difficulty":2,"kind":"mc","stem":"친구들의 역할놀이를 감상한 뒤에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"자신의 생각이나 느낌을 발표한다","correct":true},{"t":"가장 웃긴 모둠에만 손뼉을 친다","mis":"K4-2-u6-X39"},{"t":"대사가 가장 긴 친구를 뽑는다","mis":"K4-2-u6-X40"},{"t":"대본을 그대로 외워 따라 한다","mis":"K4-2-u6-X50"}],"explanation":["친구들의 연극을 감상해요.","인물의 성격과 흐름이 자연스러웠는지 생각해요.","감상한 뒤 자신의 생각이나 느낌을 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#17','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C29',3,'mc','auto','이야기를 소개할 때 원인과 결과의 관계를 분명하게 드러내려면 어떤 말을 넣으면 좋을까요?',ARRAY['K4-2-u6-X51','K4-2-u6-X36','K4-2-u6-X03']::text[],false,'{"seq":17,"concept":"K4-2-u6-C29","difficulty":3,"kind":"mc","stem":"이야기를 소개할 때 원인과 결과의 관계를 분명하게 드러내려면 어떤 말을 넣으면 좋을까요?","options":[{"t":"‘그래서’, ‘왜냐하면 …… 때문이다.’","correct":true},{"t":"‘그리고’만 계속 넣는다","mis":"K4-2-u6-X51"},{"t":"‘갑자기’를 넣는다","mis":"K4-2-u6-X36"},{"t":"‘아마도’만 넣는다","mis":"K4-2-u6-X03"}],"explanation":["‘그래서’ 뒤에는 결과가 와요.","‘왜냐하면 …… 때문이다’에는 원인이 들어가요.","이런 말을 넣으면 원인과 결과가 분명해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#18','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C30',3,'ox','auto','상상한 뒷이야기가 원래 이야기와 다르면 잘못 상상한 거예요.',ARRAY['K4-2-u6-X26']::text[],false,'{"seq":18,"concept":"K4-2-u6-C30","difficulty":3,"kind":"ox","stem":"상상한 뒷이야기가 원래 이야기와 다르면 잘못 상상한 거예요.","answer":"X","reason_options":[{"t":"그럴 만한 상상은 모두 받아들여지고, 원래 이야기와 비교하며 다른 점을 살펴볼 수 있기 때문에","correct":true},{"t":"원래 이야기가 정답이기 때문에","mis":"K4-2-u6-X26"}],"mis":"K4-2-u6-X26","explanation":["상상한 내용과 원래 이야기를 비교하며 읽을 수 있어요.","다르게 상상해도 인과 관계에 맞으면 괜찮아요.","그래서 X예요."],"asset":{"type":"passage","lines":["(간추림) 봄이 오자 실베스터를 그리워하던 엄마, 아빠가 딸기 언덕으로 소풍을 갔다.","(간추림) 바위가 된 실베스터 위에 소풍 자리를 마련하다가 그 곁에서 요술 조약돌을 발견했다.","(간추림) 조약돌을 보며 실베스터를 생각하던 엄마, 아빠 덕분에 실베스터는 다시 당나귀가 되었다."],"title":"「당나귀 실베스터와 요술 조약돌」 원래 이야기의 끝 (『국어활동』 90~99쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#19','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C40',3,'mc','auto','뒷이야기에서 겁이 많던 실베스터가 갑자기 사자와 맞서 싸우는 용감한 당나귀가 되었어요. 무엇을 함께 써야 할까요?',ARRAY['K4-2-u6-X32','K4-2-u6-X29','K4-2-u6-X06']::text[],false,'{"seq":19,"concept":"K4-2-u6-C40","difficulty":3,"kind":"mc","stem":"뒷이야기에서 겁이 많던 실베스터가 갑자기 사자와 맞서 싸우는 용감한 당나귀가 되었어요. 무엇을 함께 써야 할까요?","options":[{"t":"실베스터가 왜 용감해졌는지 그 까닭","correct":true},{"t":"까닭은 쓰지 않아도 상상이니 괜찮다","mis":"K4-2-u6-X32"},{"t":"더 놀라운 일을 덧붙인다","mis":"K4-2-u6-X29"},{"t":"글을 더 길게 늘린다","mis":"K4-2-u6-X06"}],"explanation":["실베스터는 겁이 많고 쉽게 당황하는 성격이었어요.","성격과 다르게 움직이면 바뀐 까닭이 있어야 해요.","까닭을 쓰면 이야기가 자연스럽게 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#20','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C8',3,'mc','auto','「소연이네 반에서 일어난 일」 앞부분을 보고 일어난 일을 파악했어요. 앞부분에 나와 있는 일은 무엇인가요?',ARRAY['K4-2-u6-X08','K4-2-u6-X19']::text[],false,'{"seq":20,"concept":"K4-2-u6-C8","difficulty":3,"kind":"mc","stem":"「소연이네 반에서 일어난 일」 앞부분을 보고 일어난 일을 파악했어요. 앞부분에 나와 있는 일은 무엇인가요?","options":[{"t":"잘 익은 방울토마토가 감쪽같이 사라졌다","correct":true},{"t":"새가 방울토마토를 쪼아 먹었다","mis":"K4-2-u6-X08"},{"t":"허수아비를 세웠다","mis":"K4-2-u6-X19"},{"t":"누군가 방울토마토를 훔쳐 갔다","mis":"K4-2-u6-X08"}],"explanation":["앞부분에는 방울토마토가 사라진 일까지만 나와요.","새나 사람이 가져갔다는 것은 그 뒤의 예상이에요.","짐작을 일어난 일처럼 덧붙이지 않아요."],"asset":{"type":"passage","lines":["(간추림) 소연이네 반 친구들은 올해 봄부터 옥상 텃밭에서 방울토마토를 길렀다.","(간추림) 친구들은 방울토마토를 수확할 날을 기대하고 있었다.","(간추림) 그런데 잘 익은 방울토마토가 감쪽같이 사라졌다."],"title":"「소연이네 반에서 일어난 일」 앞부분 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#21','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C27',3,'mc','auto','상상한 내용을 글과 그림으로 표현해 이야기책을 만들 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u6-X24','K4-2-u6-X07','K4-2-u6-X34']::text[],false,'{"seq":21,"concept":"K4-2-u6-C27","difficulty":3,"kind":"mc","stem":"상상한 내용을 글과 그림으로 표현해 이야기책을 만들 때 알맞은 것은 무엇인가요?","options":[{"t":"글과 그림의 관계를 생각하며 상상한 내용을 표현한다","correct":true},{"t":"그림은 이야기와 상관없이 마음대로 그린다","mis":"K4-2-u6-X24"},{"t":"글은 쓰지 않고 그림만 그린다","mis":"K4-2-u6-X07"},{"t":"가장 큰 책을 만든 사람이 이긴다","mis":"K4-2-u6-X34"}],"explanation":["이야기책은 글과 그림이 함께 이야기를 전해요.","그림은 글의 내용과 어울려야 해요.","만든 이야기책은 이어 붙여 함께 전시해요."],"asset":{"type":"passage","lines":["① 종이를 네 부분으로 나누어 접고, 접은 선 가운데에서 한 부분을 자른다.","② 네 면 가운데에서 세 면에 이야기를 쓰고 나머지 한 면에는 풀칠을 한다.","③ 풀칠한 면을 왼쪽 면의 바닥과 겹쳐서 붙인다.","④ 각자 만든 이야기책을 여러 가지 방법으로 이어 붙인 뒤에 함께 전시한다."],"numbered":false,"title":"이야기책 만드는 방법 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#22','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C54',3,'ox','auto','원인과 결과를 생각하는 방법은 이야기를 읽을 때만 쓸 수 있어요.',ARRAY['K4-2-u6-X48']::text[],false,'{"seq":22,"concept":"K4-2-u6-C54","difficulty":3,"kind":"ox","stem":"원인과 결과를 생각하는 방법은 이야기를 읽을 때만 쓸 수 있어요.","answer":"X","reason_options":[{"t":"뉴스 기사를 읽거나 내 경험을 정리할 때도 쓸 수 있기 때문에","correct":true},{"t":"원인과 결과는 이야기 속에만 있기 때문에","mis":"K4-2-u6-X48"}],"mis":"K4-2-u6-X48","explanation":["「생활 속으로」에서 내 경험과 뉴스 기사에도 써 보자고 했어요.","원인과 결과는 생활 곳곳에 있어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"원인과 결과에 따라 내 경험을 정리해서 영상을 만들어 보겠어."},{"who":"친구 2","text":"이야기를 읽고 나만의 뒷이야기를 상상해 볼래."},{"who":"친구 3","text":"원인과 결과를 생각하며 뉴스 기사를 읽어 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#23','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C14',4,'essay','teacher','세린이의 만화처럼, 어떤 일의 결과가 다음 일의 원인이 된 자신의 경험을 「원인 → 결과(원인) → 결과」 세 칸으로 정리해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u6-C14","difficulty":4,"kind":"essay","stem":"세린이의 만화처럼, 어떤 일의 결과가 다음 일의 원인이 된 자신의 경험을 「원인 → 결과(원인) → 결과」 세 칸으로 정리해 쓰세요.","answer_guide":{"answer":"예: 원인 — 아침에 늦잠을 잤다. → 결과(원인) — 서두르다가 실내화를 집에 두고 왔다. → 결과 — 학교에서 하루 종일 실내화 대신 양말만 신고 다녔다.","scoring_points":["내가 겪은 일로 썼는가","가운데 칸이 결과이면서 원인이 되게 이었는가","세 칸이 자연스럽게 이어지는가"]},"explanation":["세린이는 얇은 옷차림 → 감기 → 병원으로 이어졌어요.","내 경험에서도 이어지는 일을 찾아요.","가운데 일은 두 몫을 함께 해요."],"asset":{"type":"passage","lines":["1 엄마: “세린아, 오늘 날씨가 추우니까 옷 따뜻하게 입어.” 세린: “네.”","2 세린: “얼른 밖에 나가서 놀아야지!” [그림] 눈이 오는 날 얇은 옷차림","3 엄마: “감기에 걸렸나 보네. 얼른 병원에 가자.”","4 의사: “‘아’ 해 보세요.” 세린: “아.”"],"numbered":false,"title":"경험 떠올리기 만화 — 『국어』 260쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#24','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C58',4,'essay','teacher','「당나귀 실베스터와 요술 조약돌」에서 실베스터가 다시 당나귀가 된 뒤의 이야기를 상상해 쓰세요. 가족과 친구들을 사랑하는 실베스터의 성격과 요술 조약돌의 요술이 일어나는 조건이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u6-C58","difficulty":4,"kind":"essay","stem":"「당나귀 실베스터와 요술 조약돌」에서 실베스터가 다시 당나귀가 된 뒤의 이야기를 상상해 쓰세요. 가족과 친구들을 사랑하는 실베스터의 성격과 요술 조약돌의 요술이 일어나는 조건이 드러나게 쓰세요.","answer_guide":{"answer":"예: 다시 당나귀가 된 실베스터는 요술 조약돌을 손에 꼭 쥐고 엄마, 아빠의 소원부터 들어주었다. 그러다 이웃 친구가 아끼던 연을 잃어버려 우는 것을 보고, 조약돌을 손에 쥔 채 연이 돌아오기를 빌었다. 연이 돌아오자 친구는 무척 기뻐했고, 실베스터는 조약돌을 함부로 쓰지 않고 꼭 필요할 때만 쓰기로 했다.","scoring_points":["가족과 친구들을 사랑하는 성격에 어울리는가","조약돌을 몸에 지니고 소원을 말해야 한다는 조건을 살렸는가","원인과 결과가 자연스럽게 이어지는가"]},"explanation":["실베스터는 세상 모든 사람의 소원을 들어주고 싶어 했어요.","요술은 조약돌이 몸에 닿아야 일어나요.","성격과 조건에 어울리게 이어 써요."],"asset":{"type":"passage","lines":["말이나 행동 ㉮ ‘엄마, 아빠, 친척이랑 친구들, 아니 이 세상 모든 사람의","소원을 다 들어줘야지!’"],"numbered":false,"title":"「당나귀 실베스터와 요술 조약돌」에서 성격을 짐작할 수 있는 생각 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u6_review_d#25','kor',4,2,'u6','','tb_g4_2_kor_u6_review_d','unit_review','K4-2-u6-C54',4,'essay','teacher','『국어』 285쪽 「생활 속으로」처럼, 이 단원에서 공부한 내용 가운데 생활 속에서 실천할 것 하나를 골라 언제, 어떻게 실천할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u6-C54","difficulty":4,"kind":"essay","stem":"『국어』 285쪽 「생활 속으로」처럼, 이 단원에서 공부한 내용 가운데 생활 속에서 실천할 것 하나를 골라 언제, 어떻게 실천할지 쓰세요.","answer_guide":{"answer":"예: 저녁에 가족과 뉴스를 볼 때 원인과 결과를 생각하며 보겠다. 뉴스에서 어떤 일이 일어났는지, 왜 일어났는지, 그래서 어떻게 되었는지를 공책에 짧게 메모하고, 그 뒤에 벌어질 일을 가족과 함께 예상해 보겠다.","scoring_points":["이 단원에서 공부한 내용과 이어지는가","언제 실천할지 썼는가","어떻게 실천할지 구체적으로 썼는가"]},"explanation":["원인과 결과를 생각하며 보고 듣기, 이어질 내용 상상하기를 떠올려요.","생활 속에서 쓸 곳을 찾아요.","언제, 어떻게 할지 구체적으로 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"원인과 결과에 따라 내 경험을 정리해서 영상을 만들어 보겠어."},{"who":"친구 2","text":"이야기를 읽고 나만의 뒷이야기를 상상해 볼래."},{"who":"친구 3","text":"원인과 결과를 생각하며 뉴스 기사를 읽어 볼 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
